    def store_scope_contract(
        self,
        *,
        mission_id: str,
        expected_contract_version: int,
        contract_id: str,
        contract_version: int,
        snapshot_id: str,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        actor: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        canonical_json = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha256 = contract["integrity"]["canonical_sha256"]

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                mission = conn.execute(
                    "SELECT mission_id FROM global_missions WHERE mission_id = ?", (mission_id,)
                ).fetchone()
                if mission is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)

                duplicate = conn.execute(
                    "SELECT * FROM mission_scope_contract_versions WHERE mission_id = ? AND idempotency_key = ?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate = dict(duplicate)
                    if duplicate["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionScopeContractConflict(
                            "scope-contract idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._scope_version_row(duplicate)

                head = conn.execute(
                    "SELECT * FROM mission_scope_contract_heads WHERE mission_id = ?", (mission_id,)
                ).fetchone()
                actual_version = 0 if head is None else int(head["current_version"])
                if actual_version != expected_contract_version:
                    conn.rollback()
                    raise MissionScopeContractConflict(
                        f"expected_contract_version={expected_contract_version} does not match current contract_version={actual_version}"
                    )
                if contract_version != actual_version + 1:
                    conn.rollback()
                    raise MissionScopeContractConflict("scope contract version must increment exactly once")
                if head is not None and head["mission_scope_contract_id"] != contract_id:
                    conn.rollback()
                    raise MissionScopeContractConflict("mission scope contract identity cannot change across revisions")

                conn.execute(
                    """INSERT INTO mission_scope_contract_versions
                    (snapshot_id, mission_id, mission_scope_contract_id, contract_version, schema_version,
                     request_sha256, idempotency_key, canonical_sha256, canonical_json, created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        snapshot_id,
                        mission_id,
                        contract_id,
                        contract_version,
                        CONTRACT_SCHEMA_VERSION,
                        request_sha256,
                        idempotency_key,
                        canonical_sha256,
                        canonical_json,
                        actor,
                        reason,
                        created_at,
                    ),
                )
                if head is None:
                    conn.execute(
                        """INSERT INTO mission_scope_contract_heads
                        (mission_id, mission_scope_contract_id, current_version, current_snapshot_id, current_sha256,
                         updated_by, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                        (
                            mission_id,
                            contract_id,
                            contract_version,
                            snapshot_id,
                            canonical_sha256,
                            actor,
                            created_at,
                            created_at,
                        ),
                    )
                else:
                    cur = conn.execute(
                        """UPDATE mission_scope_contract_heads
                           SET current_version=?, current_snapshot_id=?, current_sha256=?, updated_by=?, updated_at=?
                         WHERE mission_id=? AND current_version=?""",
                        (
                            contract_version,
                            snapshot_id,
                            canonical_sha256,
                            actor,
                            created_at,
                            mission_id,
                            expected_contract_version,
                        ),
                    )
                    if cur.rowcount != 1:
                        conn.rollback()
                        raise MissionScopeContractConflict("mission scope contract changed concurrently")

                row = conn.execute(
                    "SELECT * FROM mission_scope_contract_versions WHERE snapshot_id = ?", (snapshot_id,)
                ).fetchone()
                conn.commit()
                return self._scope_version_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT mission_id FROM global_missions WHERE mission_id = %s FOR UPDATE", (mission_id,)
                    )
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)

                    cur.execute(
                        "SELECT * FROM mission_scope_contract_versions WHERE mission_id = %s AND idempotency_key = %s",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionScopeContractConflict(
                                "scope-contract idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._scope_version_row(duplicate)

                    cur.execute(
                        "SELECT * FROM mission_scope_contract_heads WHERE mission_id = %s FOR UPDATE", (mission_id,)
                    )
                    head = cur.fetchone()
                    actual_version = 0 if head is None else int(head["current_version"])
                    if actual_version != expected_contract_version:
                        raise MissionScopeContractConflict(
                            f"expected_contract_version={expected_contract_version} does not match current contract_version={actual_version}"
                        )
                    if contract_version != actual_version + 1:
                        raise MissionScopeContractConflict("scope contract version must increment exactly once")
                    if head is not None and head["mission_scope_contract_id"] != contract_id:
                        raise MissionScopeContractConflict("mission scope contract identity cannot change across revisions")

                    cur.execute(
                        """INSERT INTO mission_scope_contract_versions
                        (snapshot_id, mission_id, mission_scope_contract_id, contract_version, schema_version,
                         request_sha256, idempotency_key, canonical_sha256, canonical_json, created_by, reason, created_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            snapshot_id,
                            mission_id,
                            contract_id,
                            contract_version,
                            CONTRACT_SCHEMA_VERSION,
                            request_sha256,
                            idempotency_key,
                            canonical_sha256,
                            canonical_json,
                            actor,
                            reason,
                            self._mysql_dt(created_at),
                        ),
                    )
                    if head is None:
                        cur.execute(
                            """INSERT INTO mission_scope_contract_heads
                            (mission_id, mission_scope_contract_id, current_version, current_snapshot_id, current_sha256,
                             updated_by, created_at, updated_at) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)""",
                            (
                                mission_id,
                                contract_id,
                                contract_version,
                                snapshot_id,
                                canonical_sha256,
                                actor,
                                self._mysql_dt(created_at),
                                self._mysql_dt(created_at),
                            ),
                        )
                    else:
                        cur.execute(
                            """UPDATE mission_scope_contract_heads
                               SET current_version=%s, current_snapshot_id=%s, current_sha256=%s,
                                   updated_by=%s, updated_at=%s
                             WHERE mission_id=%s AND current_version=%s""",
                            (
                                contract_version,
                                snapshot_id,
                                canonical_sha256,
                                actor,
                                self._mysql_dt(created_at),
                                mission_id,
                                expected_contract_version,
                            ),
                        )
                        if cur.rowcount != 1:
                            raise MissionScopeContractConflict("mission scope contract changed concurrently")

                    cur.execute(
                        "SELECT * FROM mission_scope_contract_versions WHERE snapshot_id = %s", (snapshot_id,)
                    )
                    row = cur.fetchone()
                conn.commit()
                return self._scope_version_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    # ---------- Stage 3.1.4 Governance & Authorization binding ----------
    @classmethod
    def _governance_binding_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(row)
        out["binding_version"] = int(out["binding_version"])
        out["governance_scope_version"] = int(out["governance_scope_version"])
        out["binding"] = json.loads(out.pop("canonical_json"))
        out["external_response"] = json.loads(out.pop("external_response_json"))
        out["created_at"] = cls._iso_from_db(out["created_at"])
        return out

    @classmethod
    def _operation_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(row)
        if "expected_binding_version" in out:
            out["expected_binding_version"] = int(out["expected_binding_version"])
        if "governance_binding_version" in out:
            out["governance_binding_version"] = int(out["governance_binding_version"])
        out["created_at"] = cls._iso_from_db(out["created_at"])
        out["updated_at"] = cls._iso_from_db(out["updated_at"])
        return out

    @classmethod
    def _authorization_binding_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(row)
        out["governance_binding_version"] = int(out["governance_binding_version"])
        out["policy_version"] = int(out["policy_version"])
        out["scope_version"] = int(out["scope_version"])
        out["authorization_binding"] = json.loads(out.pop("canonical_json"))
        out["external_response"] = json.loads(out.pop("external_response_json"))
        out["valid_until"] = cls._iso_from_db(out["valid_until"])
        out["created_at"] = cls._iso_from_db(out["created_at"])
        return out

    def get_governance_binding_by_idempotency(
        self, mission_id: str, idempotency_key: str
    ) -> Optional[Dict[str, Any]]:
        sql = "SELECT * FROM mission_governance_binding_versions WHERE mission_id = {} AND idempotency_key = {}"
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                row = conn.execute(sql.format("?", "?"), (mission_id, idempotency_key)).fetchone()
                return None if row is None else self._governance_binding_row(dict(row))
        conn = self._connect()
        try:
            with conn.cursor() as cur:
                cur.execute(sql.format("%s", "%s"), (mission_id, idempotency_key))
                row = cur.fetchone()
                return None if row is None else self._governance_binding_row(row)
        finally:
            conn.close()

    def get_current_governance_binding(self, mission_id: str) -> Optional[Dict[str, Any]]:
        sqlite_sql = """SELECT v.* FROM mission_governance_binding_versions v
            JOIN mission_governance_binding_heads h
              ON h.mission_id=v.mission_id AND h.current_version=v.binding_version
            WHERE v.mission_id=?"""
        mysql_sql = sqlite_sql.replace("?", "%s")
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                row = conn.execute(sqlite_sql, (mission_id,)).fetchone()
                return None if row is None else self._governance_binding_row(dict(row))
        conn = self._connect()
        try:
            with conn.cursor() as cur:
                cur.execute(mysql_sql, (mission_id,))
                row = cur.fetchone()
                return None if row is None else self._governance_binding_row(row)
        finally:
            conn.close()

