    def start_governance_operation(
        self,
        *,
        operation_id: str,
        mission_id: str,
        idempotency_key: str,
        request_sha256: str,
        expected_binding_version: int,
        created_at: str,
    ) -> Dict[str, Any]:
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                existing = conn.execute(
                    "SELECT * FROM mission_governance_binding_operations WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if existing is not None:
                    existing = dict(existing)
                    if existing["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionGovernanceBindingConflict(
                            "governance-binding idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._operation_row(existing)
                conn.execute(
                    """INSERT INTO mission_governance_binding_operations
                    (operation_id, mission_id, idempotency_key, request_sha256,
                     expected_binding_version, status, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, 'PENDING', ?, ?)""",
                    (operation_id, mission_id, idempotency_key, request_sha256, expected_binding_version, created_at, created_at),
                )
                row = conn.execute(
                    "SELECT * FROM mission_governance_binding_operations WHERE operation_id=?", (operation_id,)
                ).fetchone()
                conn.commit()
                return self._operation_row(dict(row))
        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_governance_binding_operations WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    existing = cur.fetchone()
                    if existing is not None:
                        if existing["request_sha256"] != request_sha256:
                            raise MissionGovernanceBindingConflict(
                                "governance-binding idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._operation_row(existing)
                    cur.execute(
                        """INSERT INTO mission_governance_binding_operations
                        (operation_id, mission_id, idempotency_key, request_sha256,
                         expected_binding_version, status, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, 'PENDING', %s, %s)""",
                        (
                            operation_id, mission_id, idempotency_key, request_sha256,
                            expected_binding_version, self._mysql_dt(created_at), self._mysql_dt(created_at),
                        ),
                    )
                    cur.execute("SELECT * FROM mission_governance_binding_operations WHERE operation_id=%s", (operation_id,))
                    row = cur.fetchone()
                conn.commit()
                return self._operation_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

