    def store_governance_binding(
        self,
        *,
        mission_id: str,
        expected_binding_version: int,
        mission_governance_binding_id: str,
        binding_snapshot_id: str,
        binding_version: int,
        request_sha256: str,
        idempotency_key: str,
        binding: Dict[str, Any],
        governance_scope_response: Dict[str, Any],
        actor: str,
        reason: Optional[str],
        created_at: str,
        operation_id: str,
    ) -> Dict[str, Any]:
        canonical = json.dumps(binding, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        external = json.dumps(governance_scope_response, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = binding["integrity"]["canonical_sha256"]
        scope_ref = binding["canonical_scope_binding"]
        gov = binding["governance_authority"]

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                duplicate = conn.execute(
                    "SELECT * FROM mission_governance_binding_versions WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate = dict(duplicate)
                    if duplicate["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionGovernanceBindingConflict(
                            "governance-binding idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._governance_binding_row(duplicate)
                head = conn.execute(
                    "SELECT * FROM mission_governance_binding_heads WHERE mission_id=?", (mission_id,)
                ).fetchone()
                actual = 0 if head is None else int(head["current_version"])
                if actual != expected_binding_version:
                    conn.rollback()
                    raise MissionGovernanceBindingConflict(
                        f"expected_binding_version={expected_binding_version} does not match current binding_version={actual}"
                    )
                if binding_version != actual + 1:
                    conn.rollback()
                    raise MissionGovernanceBindingConflict("governance binding version must increment exactly once")
                if head is not None and head["mission_governance_binding_id"] != mission_governance_binding_id:
                    conn.rollback()
                    raise MissionGovernanceBindingConflict("mission governance binding identity cannot change")

                conn.execute(
                    """INSERT INTO mission_governance_binding_versions
                    (binding_snapshot_id, mission_id, mission_governance_binding_id, binding_version,
                     schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json,
                     mission_scope_snapshot_id, mission_scope_sha256, governance_scope_contract_id,
                     governance_scope_version, governance_scope_contract_hash, policy_set_id,
                     external_response_json, created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        binding_snapshot_id, mission_id, mission_governance_binding_id, binding_version,
                        BINDING_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha, canonical,
                        scope_ref["mission_scope_snapshot_id"], scope_ref["mission_scope_sha256"],
                        gov["governance_scope_contract_id"], gov["governance_scope_version"],
                        gov["governance_scope_contract_hash"], gov["policy_set_id"], external,
                        actor, reason, created_at,
                    ),
                )
                if head is None:
                    conn.execute(
                        """INSERT INTO mission_governance_binding_heads
                        (mission_id, mission_governance_binding_id, current_version,
                         current_binding_snapshot_id, current_scope_snapshot_id,
                         current_governance_scope_contract_id, updated_by, created_at, updated_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                        (
                            mission_id, mission_governance_binding_id, binding_version, binding_snapshot_id,
                            scope_ref["mission_scope_snapshot_id"], gov["governance_scope_contract_id"],
                            actor, created_at, created_at,
                        ),
                    )
                else:
                    cur = conn.execute(
                        """UPDATE mission_governance_binding_heads
                           SET current_version=?, current_binding_snapshot_id=?, current_scope_snapshot_id=?,
                               current_governance_scope_contract_id=?, updated_by=?, updated_at=?
                         WHERE mission_id=? AND current_version=?""",
                        (
                            binding_version, binding_snapshot_id, scope_ref["mission_scope_snapshot_id"],
                            gov["governance_scope_contract_id"], actor, created_at, mission_id, expected_binding_version,
                        ),
                    )
                    if cur.rowcount != 1:
                        conn.rollback()
                        raise MissionGovernanceBindingConflict("governance binding changed concurrently")
                conn.execute(
                    """UPDATE mission_governance_binding_operations
                       SET status='COMPLETED', governance_scope_contract_id=?, last_error=NULL, updated_at=?
                     WHERE operation_id=?""",
                    (gov["governance_scope_contract_id"], created_at, operation_id),
                )
                row = conn.execute(
                    "SELECT * FROM mission_governance_binding_versions WHERE binding_snapshot_id=?",
                    (binding_snapshot_id,),
                ).fetchone()
                conn.commit()
                return self._governance_binding_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_governance_binding_versions WHERE mission_id=%s AND idempotency_key=%s",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionGovernanceBindingConflict(
                                "governance-binding idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._governance_binding_row(duplicate)
                    cur.execute(
                        "SELECT * FROM mission_governance_binding_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    head = cur.fetchone()
                    actual = 0 if head is None else int(head["current_version"])
                    if actual != expected_binding_version:
                        raise MissionGovernanceBindingConflict(
                            f"expected_binding_version={expected_binding_version} does not match current binding_version={actual}"
                        )
                    if binding_version != actual + 1:
                        raise MissionGovernanceBindingConflict("governance binding version must increment exactly once")
                    if head is not None and head["mission_governance_binding_id"] != mission_governance_binding_id:
                        raise MissionGovernanceBindingConflict("mission governance binding identity cannot change")
                    cur.execute(
                        """INSERT INTO mission_governance_binding_versions
                        (binding_snapshot_id, mission_id, mission_governance_binding_id, binding_version,
                         schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json,
                         mission_scope_snapshot_id, mission_scope_sha256, governance_scope_contract_id,
                         governance_scope_version, governance_scope_contract_hash, policy_set_id,
                         external_response_json, created_by, reason, created_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            binding_snapshot_id, mission_id, mission_governance_binding_id, binding_version,
                            BINDING_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha, canonical,
                            scope_ref["mission_scope_snapshot_id"], scope_ref["mission_scope_sha256"],
                            gov["governance_scope_contract_id"], gov["governance_scope_version"],
                            gov["governance_scope_contract_hash"], gov["policy_set_id"], external, actor, reason,
                            self._mysql_dt(created_at),
                        ),
                    )
                    if head is None:
                        cur.execute(
                            """INSERT INTO mission_governance_binding_heads
                            (mission_id, mission_governance_binding_id, current_version,
                             current_binding_snapshot_id, current_scope_snapshot_id,
                             current_governance_scope_contract_id, updated_by, created_at, updated_at)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                            (
                                mission_id, mission_governance_binding_id, binding_version, binding_snapshot_id,
                                scope_ref["mission_scope_snapshot_id"], gov["governance_scope_contract_id"], actor,
                                self._mysql_dt(created_at), self._mysql_dt(created_at),
                            ),
                        )
                    else:
                        cur.execute(
                            """UPDATE mission_governance_binding_heads
                               SET current_version=%s, current_binding_snapshot_id=%s, current_scope_snapshot_id=%s,
                                   current_governance_scope_contract_id=%s, updated_by=%s, updated_at=%s
                             WHERE mission_id=%s AND current_version=%s""",
                            (
                                binding_version, binding_snapshot_id, scope_ref["mission_scope_snapshot_id"],
                                gov["governance_scope_contract_id"], actor, self._mysql_dt(created_at),
                                mission_id, expected_binding_version,
                            ),
                        )
                        if cur.rowcount != 1:
                            raise MissionGovernanceBindingConflict("governance binding changed concurrently")
                    cur.execute(
                        """UPDATE mission_governance_binding_operations
                           SET status='COMPLETED', governance_scope_contract_id=%s, last_error=NULL, updated_at=%s
                         WHERE operation_id=%s""",
                        (gov["governance_scope_contract_id"], self._mysql_dt(created_at), operation_id),
                    )
                    cur.execute(
                        "SELECT * FROM mission_governance_binding_versions WHERE binding_snapshot_id=%s",
                        (binding_snapshot_id,),
                    )
                    row = cur.fetchone()
                conn.commit()
                return self._governance_binding_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

