    def store_routed_task(
        self,
        *,
        mission_id: str,
        task_id: str,
        request_sha256: str,
        idempotency_key: str,
        task_contract: Dict[str, Any],
        destination_subsystem: str,
        destination_component: str,
        capability_id: str,
        created_by: str,
        created_at: str,
    ) -> Dict[str, Any]:
        canonical = json.dumps(task_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                duplicate = conn.execute(
                    "SELECT * FROM mission_routed_tasks WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate = dict(duplicate)
                    if duplicate["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionTaskConflict("task idempotency_key was already used with a different canonical request")
                    conn.rollback()
                    return self._routed_task_row(duplicate)
                existing_route = conn.execute(
                    "SELECT task_id FROM mission_routed_tasks WHERE mission_id=? AND destination_subsystem=?",
                    (mission_id, destination_subsystem),
                ).fetchone()
                if existing_route is not None:
                    conn.rollback()
                    raise MissionTaskConflict(
                        f"mission already has a governed routing task for subsystem {destination_subsystem}"
                    )
                conn.execute(
                    """INSERT INTO mission_routed_tasks
                    (task_id, mission_id, schema_version, request_sha256, idempotency_key,
                     canonical_sha256, canonical_json, destination_subsystem, destination_component,
                     capability_id, task_status, created_by, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'READY', ?, ?, ?)""",
                    (
                        task_id, mission_id, TASK_SCHEMA_VERSION, request_sha256, idempotency_key,
                        task_contract["integrity"]["canonical_sha256"], canonical,
                        destination_subsystem, destination_component, capability_id,
                        created_by, created_at, created_at,
                    ),
                )
                row = conn.execute("SELECT * FROM mission_routed_tasks WHERE task_id=?", (task_id,)).fetchone()
                conn.commit()
                return self._routed_task_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_routed_tasks WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionTaskConflict("task idempotency_key was already used with a different canonical request")
                        conn.rollback()
                        return self._routed_task_row(duplicate)
                    cur.execute(
                        "SELECT task_id FROM mission_routed_tasks WHERE mission_id=%s AND destination_subsystem=%s FOR UPDATE",
                        (mission_id, destination_subsystem),
                    )
                    if cur.fetchone() is not None:
                        raise MissionTaskConflict(
                            f"mission already has a governed routing task for subsystem {destination_subsystem}"
                        )
                    cur.execute(
                        """INSERT INTO mission_routed_tasks
                        (task_id, mission_id, schema_version, request_sha256, idempotency_key,
                         canonical_sha256, canonical_json, destination_subsystem, destination_component,
                         capability_id, task_status, created_by, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'READY', %s, %s, %s)""",
                        (
                            task_id, mission_id, TASK_SCHEMA_VERSION, request_sha256, idempotency_key,
                            task_contract["integrity"]["canonical_sha256"], canonical,
                            destination_subsystem, destination_component, capability_id, created_by,
                            self._mysql_dt(created_at), self._mysql_dt(created_at),
                        ),
                    )
                    cur.execute("SELECT * FROM mission_routed_tasks WHERE task_id=%s", (task_id,))
                    row = cur.fetchone()
                conn.commit()
                return self._routed_task_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def update_routed_task_status(self, task_id: str, *, status: str, updated_at: str) -> None:
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("UPDATE mission_routed_tasks SET task_status=?, updated_at=? WHERE task_id=?", (status, updated_at, task_id))
                conn.commit()
            return
        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE mission_routed_tasks SET task_status=%s, updated_at=%s WHERE task_id=%s",
                        (status, self._mysql_dt(updated_at), task_id),
                    )
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def start_task_dispatch_attempt(self, *, dispatch_attempt_id: str, task_id: str, created_at: str) -> Dict[str, Any]:
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                row = conn.execute(
                    "SELECT COALESCE(MAX(attempt_no),0)+1 AS next_no FROM mission_task_dispatch_attempts WHERE task_id=?",
                    (task_id,),
                ).fetchone()
                attempt_no = int(row["next_no"])
                conn.execute(
                    """INSERT INTO mission_task_dispatch_attempts
                    (dispatch_attempt_id, task_id, attempt_no, status, recovered_after_response_loss, created_at, updated_at)
                    VALUES (?, ?, ?, 'PENDING', 0, ?, ?)""",
                    (dispatch_attempt_id, task_id, attempt_no, created_at, created_at),
                )
                result = conn.execute(
                    "SELECT * FROM mission_task_dispatch_attempts WHERE dispatch_attempt_id=?", (dispatch_attempt_id,)
                ).fetchone()
                conn.commit()
                return self._dispatch_attempt_row(dict(result))
        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT COALESCE(MAX(attempt_no),0)+1 AS next_no FROM mission_task_dispatch_attempts WHERE task_id=%s FOR UPDATE",
                        (task_id,),
                    )
                    attempt_no = int(cur.fetchone()["next_no"])
                    cur.execute(
                        """INSERT INTO mission_task_dispatch_attempts
                        (dispatch_attempt_id, task_id, attempt_no, status, recovered_after_response_loss, created_at, updated_at)
                        VALUES (%s, %s, %s, 'PENDING', 0, %s, %s)""",
                        (dispatch_attempt_id, task_id, attempt_no, self._mysql_dt(created_at), self._mysql_dt(created_at)),
                    )
                    cur.execute("SELECT * FROM mission_task_dispatch_attempts WHERE dispatch_attempt_id=%s", (dispatch_attempt_id,))
                    result = cur.fetchone()
                conn.commit()
                return self._dispatch_attempt_row(result)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def update_task_dispatch_attempt(
        self,
        dispatch_attempt_id: str,
        *,
        status: str,
        updated_at: str,
        recovered_after_response_loss: bool = False,
        external_mission_id: Optional[str] = None,
        response: Optional[Dict[str, Any]] = None,
        last_error: Optional[str] = None,
    ) -> None:
        response_json = None if response is None else json.dumps(response, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute(
                    """UPDATE mission_task_dispatch_attempts
                       SET status=?, recovered_after_response_loss=?, external_mission_id=COALESCE(?, external_mission_id),
                           response_json=COALESCE(?, response_json), last_error=?, updated_at=?
                     WHERE dispatch_attempt_id=?""",
                    (
                        status, 1 if recovered_after_response_loss else 0, external_mission_id,
                        response_json, last_error, updated_at, dispatch_attempt_id,
                    ),
                )
                conn.commit()
            return
        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """UPDATE mission_task_dispatch_attempts
                           SET status=%s, recovered_after_response_loss=%s, external_mission_id=COALESCE(%s, external_mission_id),
                               response_json=COALESCE(%s, response_json), last_error=%s, updated_at=%s
                         WHERE dispatch_attempt_id=%s""",
                        (
                            status, 1 if recovered_after_response_loss else 0, external_mission_id,
                            response_json, last_error, self._mysql_dt(updated_at), dispatch_attempt_id,
                        ),
                    )
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def list_task_dispatch_attempts(self, task_id: str) -> list[Dict[str, Any]]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                rows = conn.execute(
                    "SELECT * FROM mission_task_dispatch_attempts WHERE task_id=? ORDER BY attempt_no", (task_id,)
                ).fetchall()
            else:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_task_dispatch_attempts WHERE task_id=%s ORDER BY attempt_no", (task_id,)
                    )
                    rows = cur.fetchall()
            return [self._dispatch_attempt_row(dict(row)) for row in rows]
        finally:
            conn.close()

    @classmethod
    def _command_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        out = dict(row)
        for source, target in (
            ("before_version_json", "before_version_vector"),
            ("after_version_json", "after_version_vector"),
            ("result_json", "result"),
            ("metadata_json", "metadata"),
        ):
            raw = out.pop(source, None)
            out[target] = None if raw is None else json.loads(raw)
        out["created_at"] = cls._iso_from_db(out["created_at"])
        out["updated_at"] = cls._iso_from_db(out["updated_at"])
        return out

    def get_mission_command(self, mission_id: str, command_id: str) -> Optional[Dict[str, Any]]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                row = conn.execute(
                    "SELECT * FROM mission_command_journal WHERE mission_id=? AND command_id=?",
                    (mission_id, command_id),
                ).fetchone()
            else:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_command_journal WHERE mission_id=%s AND command_id=%s",
                        (mission_id, command_id),
                    )
                    row = cur.fetchone()
            return None if row is None else self._command_row(dict(row))
        finally:
            conn.close()

