    def start_mission_command(
        self,
        *,
        mission_id: str,
        command_id: str,
        idempotency_key: str,
        operation: str,
        request_sha256: str,
        expected_version_sha256: str,
        submitted_by: str,
        metadata: Dict[str, Any],
        created_at: str,
    ) -> tuple[Dict[str, Any], bool]:
        metadata_json = json.dumps(metadata, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                by_command = conn.execute(
                    "SELECT * FROM mission_command_journal WHERE command_id=?", (command_id,)
                ).fetchone()
                by_idem = conn.execute(
                    "SELECT * FROM mission_command_journal WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                existing = by_command or by_idem
                if existing is not None:
                    row = dict(existing)
                    if row["mission_id"] != mission_id or row["command_id"] != command_id or row["idempotency_key"] != idempotency_key:
                        raise MissionCommandConflict("command_id/idempotency_key is already bound to a different mission command")
                    if row["request_sha256"] != request_sha256:
                        raise MissionCommandConflict("mission command replay conflicts with the original canonical request")
                    conn.commit()
                    return self._command_row(row), True
                conn.execute(
                    """INSERT INTO mission_command_journal
                    (command_id, mission_id, schema_version, idempotency_key, operation,
                     request_sha256, expected_version_sha256, status, submitted_by,
                     metadata_json, created_at, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, 'PENDING', ?, ?, ?, ?)""",
                    (
                        command_id, mission_id, COMMAND_SCHEMA_VERSION, idempotency_key, operation,
                        request_sha256, expected_version_sha256, submitted_by, metadata_json,
                        created_at, created_at,
                    ),
                )
                row = conn.execute(
                    "SELECT * FROM mission_command_journal WHERE command_id=?", (command_id,)
                ).fetchone()
                conn.commit()
                return self._command_row(dict(row)), False

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_command_journal WHERE command_id=%s FOR UPDATE", (command_id,)
                    )
                    by_command = cur.fetchone()
                    cur.execute(
                        "SELECT * FROM mission_command_journal WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    by_idem = cur.fetchone()
                    existing = by_command or by_idem
                    if existing is not None:
                        if (
                            existing["mission_id"] != mission_id
                            or existing["command_id"] != command_id
                            or existing["idempotency_key"] != idempotency_key
                        ):
                            raise MissionCommandConflict("command_id/idempotency_key is already bound to a different mission command")
                        if existing["request_sha256"] != request_sha256:
                            raise MissionCommandConflict("mission command replay conflicts with the original canonical request")
                        conn.rollback()
                        return self._command_row(existing), True
                    cur.execute(
                        """INSERT INTO mission_command_journal
                        (command_id, mission_id, schema_version, idempotency_key, operation,
                         request_sha256, expected_version_sha256, status, submitted_by,
                         metadata_json, created_at, updated_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, 'PENDING', %s, %s, %s, %s)""",
                        (
                            command_id, mission_id, COMMAND_SCHEMA_VERSION, idempotency_key, operation,
                            request_sha256, expected_version_sha256, submitted_by, metadata_json,
                            self._mysql_dt(created_at), self._mysql_dt(created_at),
                        ),
                    )
                    cur.execute("SELECT * FROM mission_command_journal WHERE command_id=%s", (command_id,))
                    row = cur.fetchone()
                conn.commit()
                return self._command_row(row), False
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    def update_mission_command(
        self,
        command_id: str,
        *,
        status: str,
        updated_at: str,
        before_version_vector: Optional[Dict[str, Any]] = None,
        after_version_vector: Optional[Dict[str, Any]] = None,
        result: Optional[Dict[str, Any]] = None,
        last_error: Optional[str] = None,
    ) -> None:
        before_json = None if before_version_vector is None else json.dumps(before_version_vector, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        after_json = None if after_version_vector is None else json.dumps(after_version_vector, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        result_json = None if result is None else json.dumps(result, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute(
                    """UPDATE mission_command_journal
                       SET status=?, before_version_json=COALESCE(?, before_version_json),
                           after_version_json=COALESCE(?, after_version_json),
                           result_json=COALESCE(?, result_json), last_error=?, updated_at=?
                     WHERE command_id=?""",
                    (status, before_json, after_json, result_json, last_error, updated_at, command_id),
                )
                conn.commit()
            return
        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """UPDATE mission_command_journal
                           SET status=%s, before_version_json=COALESCE(%s, before_version_json),
                               after_version_json=COALESCE(%s, after_version_json),
                               result_json=COALESCE(%s, result_json), last_error=%s, updated_at=%s
                         WHERE command_id=%s""",
                        (
                            status, before_json, after_json, result_json, last_error,
                            self._mysql_dt(updated_at), command_id,
                        ),
                    )
                conn.commit()
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

