    @staticmethod
    def _assert_plan_scope_binding_matches_head(plan_contract: Dict[str, Any], scope_head: Optional[Dict[str, Any]]) -> None:
        scope = plan_contract["mission_binding"]["scope"]
        if scope["binding_status"] == "UNBOUND":
            if scope_head is not None:
                raise MissionPlanContractConflict("canonical Scope contract changed before plan registration")
            return
        if scope_head is None:
            raise MissionPlanContractConflict("canonical Scope contract disappeared before plan registration")
        if (
            int(scope["scope_version"]) != int(scope_head["current_version"])
            or scope["scope_snapshot_id"] != scope_head["current_snapshot_id"]
            or scope["scope_sha256"] != scope_head["current_sha256"]
        ):
            raise MissionPlanContractConflict("canonical Scope head changed before plan registration")

    def store_mission_plan(
        self,
        *,
        mission_id: str,
        plan_id: str,
        plan_version: int,
        request_sha256: str,
        idempotency_key: str,
        plan_contract: Dict[str, Any],
        expected_state_version: int,
        source_transition_id: str,
        actor: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(
            plan_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        )
        canonical_sha256 = plan_contract["integrity"]["canonical_sha256"]

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                mission = conn.execute(
                    "SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if mission is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)

                duplicate = conn.execute(
                    "SELECT * FROM mission_plans WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate_dict = dict(duplicate)
                    if duplicate_dict["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionPlanContractConflict(
                            "plan-contract idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._mission_plan_row(duplicate_dict)

                existing = conn.execute(
                    "SELECT * FROM mission_plans WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if existing is not None:
                    conn.rollback()
                    raise MissionPlanContractConflict(
                        "Stage 3.3.1 allows exactly one immutable canonical plan identity per mission"
                    )

                state = conn.execute(
                    "SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if state is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)
                if state["state"] != "PLANNING" or int(state["state_version"]) != int(expected_state_version):
                    conn.rollback()
                    raise MissionPlanContractConflict(
                        "mission state changed before plan registration; exact PLANNING state/version is required"
                    )

                transition = conn.execute(
                    "SELECT * FROM mission_state_transitions WHERE mission_id=? AND transition_id=?",
                    (mission_id, source_transition_id),
                ).fetchone()
                if (
                    transition is None
                    or transition["to_state"] != "PLANNING"
                    or int(transition["to_state_version"]) != int(expected_state_version)
                ):
                    conn.rollback()
                    raise MissionPlanContractConflict(
                        "Stage-3.2.4 PLANNING activation lineage no longer matches the source state"
                    )

                scope_head_row = conn.execute(
                    "SELECT * FROM mission_scope_contract_heads WHERE mission_id=?", (mission_id,)
                ).fetchone()
                scope_head = None if scope_head_row is None else self._scope_head_row(dict(scope_head_row))
                self._assert_plan_scope_binding_matches_head(plan_contract, scope_head)

                conn.execute(
                    """INSERT INTO mission_plans
                    (plan_id, mission_id, plan_version, schema_version, request_sha256, idempotency_key,
                     canonical_sha256, canonical_json, source_state_version, source_transition_id,
                     created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        plan_id,
                        mission_id,
                        plan_version,
                        PLAN_CONTRACT_SCHEMA_VERSION,
                        request_sha256,
                        idempotency_key,
                        canonical_sha256,
                        canonical_json_value,
                        expected_state_version,
                        source_transition_id,
                        actor,
                        reason,
                        created_at,
                    ),
                )
                row = conn.execute("SELECT * FROM mission_plans WHERE plan_id=?", (plan_id,)).fetchone()
                conn.commit()
                return self._mission_plan_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)

                    cur.execute(
                        "SELECT * FROM mission_plans WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionPlanContractConflict(
                                "plan-contract idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._mission_plan_row(duplicate)

                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is not None:
                        raise MissionPlanContractConflict(
                            "Stage 3.3.1 allows exactly one immutable canonical plan identity per mission"
                        )

                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state = cur.fetchone()
                    if state is None:
                        raise MissionNotFound(mission_id)
                    if state["state"] != "PLANNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionPlanContractConflict(
                            "mission state changed before plan registration; exact PLANNING state/version is required"
                        )

                    cur.execute(
                        "SELECT * FROM mission_state_transitions WHERE mission_id=%s AND transition_id=%s FOR UPDATE",
                        (mission_id, source_transition_id),
                    )
                    transition = cur.fetchone()
                    if (
                        transition is None
                        or transition["to_state"] != "PLANNING"
                        or int(transition["to_state_version"]) != int(expected_state_version)
                    ):
                        raise MissionPlanContractConflict(
                            "Stage-3.2.4 PLANNING activation lineage no longer matches the source state"
                        )

                    cur.execute(
                        "SELECT * FROM mission_scope_contract_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    scope_head_row = cur.fetchone()
                    scope_head = None if scope_head_row is None else self._scope_head_row(scope_head_row)
                    self._assert_plan_scope_binding_matches_head(plan_contract, scope_head)

                    cur.execute(
                        """INSERT INTO mission_plans
                        (plan_id, mission_id, plan_version, schema_version, request_sha256, idempotency_key,
                         canonical_sha256, canonical_json, source_state_version, source_transition_id,
                         created_by, reason, created_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            plan_id,
                            mission_id,
                            plan_version,
                            PLAN_CONTRACT_SCHEMA_VERSION,
                            request_sha256,
                            idempotency_key,
                            canonical_sha256,
                            canonical_json_value,
                            expected_state_version,
                            source_transition_id,
                            actor,
                            reason,
                            self._mysql_dt(created_at),
                        ),
                    )
                    cur.execute("SELECT * FROM mission_plans WHERE plan_id=%s", (plan_id,))
                    row = cur.fetchone()
                conn.commit()
                return self._mission_plan_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

