        if (
            int(scope["scope_version"]) != int(scope_head["current_version"])
            or scope["scope_snapshot_id"] != scope_head["current_snapshot_id"]
            or scope["scope_sha256"] != scope_head["current_sha256"]
        ):
            raise MissionPlannerInputSnapshotConflict(
                "canonical Scope head changed before planner-input snapshot registration"
            )

