    def store_task_decomposition(
        self,
        *,
        mission_id: str,
        decomposition_id: str,
        plan_id: str,
        plan_version: int,
        snapshot_id: str,
        snapshot_version: int,
        decomposition_version: int,
        request_sha256: str,
        idempotency_key: str,
        decomposition: Dict[str, Any],
        expected_state_version: int,
        expected_plan_sha256: str,
        expected_snapshot_sha256: str,
        source_version_sha256: str,
        actor: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(
            decomposition, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        )
        canonical_sha256 = decomposition["integrity"]["canonical_sha256"]
        task_set_sha256 = decomposition["task_set"]["task_set_sha256"]
        task_contracts = list(decomposition["task_set"]["tasks"])

        def assert_snapshot_context(snapshot: Dict[str, Any], scope_head: Optional[Dict[str, Any]], governance_head: Optional[Dict[str, Any]]) -> None:
            self._assert_planner_input_scope_matches_head(snapshot, scope_head)
            self._assert_planner_input_governance_matches_head(snapshot, governance_head)

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                if conn.execute(
                    "SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)
                ).fetchone() is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)

                duplicate = conn.execute(
                    "SELECT * FROM mission_task_decompositions WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate_dict = dict(duplicate)
                    if duplicate_dict["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionTaskDecompositionConflict(
                            "task-decomposition idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._task_decomposition_row(duplicate_dict)

                if conn.execute(
                    "SELECT decomposition_id FROM mission_task_decompositions WHERE mission_id=?", (mission_id,)
                ).fetchone() is not None:
                    conn.rollback()
                    raise MissionTaskDecompositionConflict(
                        "Stage 3.3.3 allows exactly one immutable task decomposition per canonical Plan/snapshot"
                    )

                plan = conn.execute(
                    "SELECT * FROM mission_plans WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if (
                    plan is None
                    or plan["plan_id"] != plan_id
                    or int(plan["plan_version"]) != int(plan_version)
                    or plan["canonical_sha256"] != expected_plan_sha256
                ):
                    conn.rollback()
                    raise MissionTaskDecompositionConflict(
                        "canonical Plan identity/version/hash changed before task decomposition registration"
                    )

                snapshot_row = conn.execute(
                    "SELECT * FROM mission_planner_input_snapshots WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if (
                    snapshot_row is None
                    or snapshot_row["snapshot_id"] != snapshot_id
                    or int(snapshot_row["snapshot_version"]) != int(snapshot_version)
                    or snapshot_row["canonical_sha256"] != expected_snapshot_sha256
                    or snapshot_row["plan_id"] != plan_id
                ):
                    conn.rollback()
                    raise MissionTaskDecompositionConflict(
                        "planner-input snapshot identity/version/hash changed before task decomposition registration"
                    )
                snapshot = json.loads(snapshot_row["canonical_json"])

                state = conn.execute(
                    "SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if (
                    state is None
                    or state["state"] != "PLANNING"
                    or int(state["state_version"]) != int(expected_state_version)
                    or int(snapshot_row["source_state_version"]) != int(expected_state_version)
                ):
                    conn.rollback()
                    raise MissionTaskDecompositionConflict(
                        "mission PLANNING state/version drifted from planner-input snapshot before task decomposition registration"
                    )

                scope_head_row = conn.execute(
                    "SELECT * FROM mission_scope_contract_heads WHERE mission_id=?", (mission_id,)
                ).fetchone()
                scope_head = None if scope_head_row is None else self._scope_head_row(dict(scope_head_row))
                governance_head_row = conn.execute(
                    "SELECT * FROM mission_governance_binding_heads WHERE mission_id=?", (mission_id,)
                ).fetchone()
                governance_head = None if governance_head_row is None else self._governance_head_row(dict(governance_head_row))
                assert_snapshot_context(snapshot, scope_head, governance_head)

                conn.execute(
                    """INSERT INTO mission_task_decompositions
                    (decomposition_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                     decomposition_version, schema_version, request_sha256, idempotency_key,
                     canonical_sha256, task_set_sha256, canonical_json, source_state_version,
                     source_plan_sha256, source_snapshot_sha256, source_version_sha256, task_count,
                     created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        decomposition_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                        decomposition_version, TASK_DECOMPOSITION_SCHEMA_VERSION, request_sha256, idempotency_key,
                        canonical_sha256, task_set_sha256, canonical_json_value, expected_state_version,
                        expected_plan_sha256, expected_snapshot_sha256, source_version_sha256, len(task_contracts),
                        actor, reason, created_at,
                    ),
                )
                for task in task_contracts:
                    identity = task["identity"]
                    spec = task["specification"]
                    conn.execute(
                        """INSERT INTO mission_planned_tasks
                        (planned_task_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                         snapshot_id, snapshot_version, task_key, task_index, schema_version, canonical_sha256,
                         canonical_json, required_subsystem, required_capability, task_status, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                        (
                            identity["planned_task_id"], mission_id, decomposition_id, decomposition_version,
                            plan_id, plan_version, snapshot_id, snapshot_version, identity["task_key"],
                            int(identity["task_index"]), PLANNED_TASK_SCHEMA_VERSION,
                            task["integrity"]["canonical_sha256"],
                            json.dumps(task, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
                            spec["required_subsystem"], spec["required_capability"],
                            task["semantics"]["task_status"], created_at,
                        ),
                    )
                row = conn.execute(
                    "SELECT * FROM mission_task_decompositions WHERE decomposition_id=?", (decomposition_id,)
                ).fetchone()
                conn.commit()
                return self._task_decomposition_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)

                    cur.execute(
                        "SELECT * FROM mission_task_decompositions WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionTaskDecompositionConflict(
                                "task-decomposition idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._task_decomposition_row(duplicate)

                    cur.execute(
                        "SELECT decomposition_id FROM mission_task_decompositions WHERE mission_id=%s FOR UPDATE",
                        (mission_id,),
                    )
                    if cur.fetchone() is not None:
                        raise MissionTaskDecompositionConflict(
                            "Stage 3.3.3 allows exactly one immutable task decomposition per canonical Plan/snapshot"
                        )

                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    plan = cur.fetchone()
                    if (
                        plan is None
                        or plan["plan_id"] != plan_id
                        or int(plan["plan_version"]) != int(plan_version)
                        or plan["canonical_sha256"] != expected_plan_sha256
                    ):
                        raise MissionTaskDecompositionConflict(
                            "canonical Plan identity/version/hash changed before task decomposition registration"
                        )

                    cur.execute(
                        "SELECT * FROM mission_planner_input_snapshots WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    snapshot_row = cur.fetchone()
                    if (
                        snapshot_row is None
                        or snapshot_row["snapshot_id"] != snapshot_id
                        or int(snapshot_row["snapshot_version"]) != int(snapshot_version)
                        or snapshot_row["canonical_sha256"] != expected_snapshot_sha256
                        or snapshot_row["plan_id"] != plan_id
                    ):
                        raise MissionTaskDecompositionConflict(
                            "planner-input snapshot identity/version/hash changed before task decomposition registration"
                        )
                    snapshot = json.loads(snapshot_row["canonical_json"])

                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state = cur.fetchone()
                    if (
                        state is None
                        or state["state"] != "PLANNING"
                        or int(state["state_version"]) != int(expected_state_version)
                        or int(snapshot_row["source_state_version"]) != int(expected_state_version)
                    ):
                        raise MissionTaskDecompositionConflict(
                            "mission PLANNING state/version drifted from planner-input snapshot before task decomposition registration"
                        )

                    cur.execute(
                        "SELECT * FROM mission_scope_contract_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    scope_head_row = cur.fetchone()
                    scope_head = None if scope_head_row is None else self._scope_head_row(scope_head_row)
                    cur.execute(
                        "SELECT * FROM mission_governance_binding_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)
                    )
                    governance_head_row = cur.fetchone()
                    governance_head = None if governance_head_row is None else self._governance_head_row(governance_head_row)
                    assert_snapshot_context(snapshot, scope_head, governance_head)

                    cur.execute(
                        """INSERT INTO mission_task_decompositions
                        (decomposition_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                         decomposition_version, schema_version, request_sha256, idempotency_key,
                         canonical_sha256, task_set_sha256, canonical_json, source_state_version,
                         source_plan_sha256, source_snapshot_sha256, source_version_sha256, task_count,
                         created_by, reason, created_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            decomposition_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                            decomposition_version, TASK_DECOMPOSITION_SCHEMA_VERSION, request_sha256, idempotency_key,
                            canonical_sha256, task_set_sha256, canonical_json_value, expected_state_version,
                            expected_plan_sha256, expected_snapshot_sha256, source_version_sha256, len(task_contracts),
                            actor, reason, self._mysql_dt(created_at),
                        ),
                    )
                    for task in task_contracts:
                        identity = task["identity"]
                        spec = task["specification"]
                        cur.execute(
                            """INSERT INTO mission_planned_tasks
                            (planned_task_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                             snapshot_id, snapshot_version, task_key, task_index, schema_version, canonical_sha256,
                             canonical_json, required_subsystem, required_capability, task_status, created_at)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                            (
                                identity["planned_task_id"], mission_id, decomposition_id, decomposition_version,
                                plan_id, plan_version, snapshot_id, snapshot_version, identity["task_key"],
                                int(identity["task_index"]), PLANNED_TASK_SCHEMA_VERSION,
                                task["integrity"]["canonical_sha256"],
                                json.dumps(task, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
                                spec["required_subsystem"], spec["required_capability"],
                                task["semantics"]["task_status"], self._mysql_dt(created_at),
                            ),
                        )
                    cur.execute(
                        "SELECT * FROM mission_task_decompositions WHERE decomposition_id=%s", (decomposition_id,)
                    )
                    row = cur.fetchone()
                conn.commit()
                return self._task_decomposition_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

