    def store_task_dependency_graph(
        self,
        *,
        mission_id: str,
        graph_id: str,
        graph_version: int,
        decomposition_id: str,
        decomposition_version: int,
        plan_id: str,
        plan_version: int,
        snapshot_id: str,
        snapshot_version: int,
        request_sha256: str,
        idempotency_key: str,
        graph: Dict[str, Any],
        expected_state_version: int,
        expected_plan_sha256: str,
        expected_snapshot_sha256: str,
        expected_decomposition_sha256: str,
        expected_task_set_sha256: str,
        source_version_sha256: str,
        actor: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(graph, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha256 = graph["integrity"]["canonical_sha256"]
        node_set_sha256 = graph["graph"]["node_set_sha256"]
        edge_set_sha256 = graph["graph"]["edge_set_sha256"]
        edge_contracts = list(graph["graph"]["edges"])
        nodes = list(graph["graph"]["nodes"])

        def verify_task_rows(rows) -> bool:
            if len(rows) != len(nodes):
                return False
            by_id = {str(row["planned_task_id"]): row for row in rows}
            for node in nodes:
                row = by_id.get(str(node["planned_task_id"]))
                if row is None:
                    return False
                if (
                    row["task_key"] != node["task_key"]
                    or int(row["task_index"]) != int(node["task_index"])
                    or row["canonical_sha256"] != node["task_sha256"]
                    or row["required_subsystem"] != node["required_subsystem"]
                    or row["required_capability"] != node["required_capability"]
                ):
                    return False
            return True

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                if conn.execute(
                    "SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)
                ).fetchone() is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)

                duplicate = conn.execute(
                    "SELECT * FROM mission_task_dependency_graphs WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if duplicate is not None:
                    duplicate_dict = dict(duplicate)
                    if duplicate_dict["request_sha256"] != request_sha256:
                        conn.rollback()
                        raise MissionTaskDependencyGraphConflict(
                            "task-dependency-graph idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._task_dependency_graph_row(duplicate_dict)

                if conn.execute(
                    "SELECT graph_id FROM mission_task_dependency_graphs WHERE mission_id=?", (mission_id,)
                ).fetchone() is not None:
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "Stage 3.3.4 allows exactly one immutable dependency graph per canonical decomposition"
                    )

                plan = conn.execute("SELECT * FROM mission_plans WHERE mission_id=?", (mission_id,)).fetchone()
                snapshot = conn.execute(
                    "SELECT * FROM mission_planner_input_snapshots WHERE mission_id=?", (mission_id,)
                ).fetchone()
                decomposition = conn.execute(
                    "SELECT * FROM mission_task_decompositions WHERE mission_id=?", (mission_id,)
                ).fetchone()
                state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                tasks = conn.execute(
                    "SELECT * FROM mission_planned_tasks WHERE mission_id=? ORDER BY task_index, id", (mission_id,)
                ).fetchall()

                if (
                    plan is None or plan["plan_id"] != plan_id or int(plan["plan_version"]) != int(plan_version)
                    or plan["canonical_sha256"] != expected_plan_sha256
                ):
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "canonical Plan identity/version/hash changed before dependency graph registration"
                    )
                if (
                    snapshot is None or snapshot["snapshot_id"] != snapshot_id
                    or int(snapshot["snapshot_version"]) != int(snapshot_version)
                    or snapshot["canonical_sha256"] != expected_snapshot_sha256
                ):
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "planner-input snapshot identity/version/hash changed before dependency graph registration"
                    )
                if (
                    decomposition is None or decomposition["decomposition_id"] != decomposition_id
                    or int(decomposition["decomposition_version"]) != int(decomposition_version)
                    or decomposition["canonical_sha256"] != expected_decomposition_sha256
                    or decomposition["task_set_sha256"] != expected_task_set_sha256
                ):
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "canonical task decomposition identity/version/hash changed before dependency graph registration"
                    )
                if (
                    state is None or state["state"] != "PLANNING"
                    or int(state["state_version"]) != int(expected_state_version)
                ):
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "mission PLANNING state/version drifted before dependency graph registration"
                    )
                if not verify_task_rows([dict(row) for row in tasks]):
                    conn.rollback()
                    raise MissionTaskDependencyGraphConflict(
                        "canonical planned-task store drifted from the dependency graph node set"
                    )

                conn.execute(
                    """INSERT INTO mission_task_dependency_graphs
                    (graph_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                     snapshot_id, snapshot_version, graph_version, schema_version, request_sha256, idempotency_key,
                     canonical_sha256, node_set_sha256, edge_set_sha256, canonical_json, source_state_version,
                     source_plan_sha256, source_snapshot_sha256, source_decomposition_sha256, source_task_set_sha256,
                     source_version_sha256, node_count, edge_count, validation_status, created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        graph_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                        snapshot_id, snapshot_version, graph_version, TASK_DEPENDENCY_GRAPH_SCHEMA_VERSION,
                        request_sha256, idempotency_key, canonical_sha256, node_set_sha256, edge_set_sha256,
                        canonical_json_value, expected_state_version, expected_plan_sha256, expected_snapshot_sha256,
                        expected_decomposition_sha256, expected_task_set_sha256, source_version_sha256,
                        len(nodes), len(edge_contracts), "PASS", actor, reason, created_at,
                    ),
                )
                for edge in edge_contracts:
                    identity = edge["identity"]
                    dep = edge["dependency"]
                    conn.execute(
                        """INSERT INTO mission_task_dependency_edges
                        (dependency_edge_id, graph_id, graph_version, mission_id, decomposition_id,
                         decomposition_version, plan_id, plan_version, from_planned_task_id, from_task_key,
                         to_planned_task_id, to_task_key, schema_version, canonical_sha256, canonical_json, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                        (
                            identity["dependency_edge_id"], graph_id, graph_version, mission_id, decomposition_id,
                            decomposition_version, plan_id, plan_version, dep["from_planned_task_id"],
                            dep["from_task_key"], dep["to_planned_task_id"], dep["to_task_key"],
                            TASK_DEPENDENCY_EDGE_SCHEMA_VERSION, edge["integrity"]["canonical_sha256"],
                            json.dumps(edge, ensure_ascii=False, sort_keys=True, separators=(",", ":")), created_at,
                        ),
                    )
                row = conn.execute(
                    "SELECT * FROM mission_task_dependency_graphs WHERE graph_id=?", (graph_id,)
                ).fetchone()
                conn.commit()
                return self._task_dependency_graph_row(dict(row))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)
                    cur.execute(
                        "SELECT * FROM mission_task_dependency_graphs WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        if duplicate["request_sha256"] != request_sha256:
                            raise MissionTaskDependencyGraphConflict(
                                "task-dependency-graph idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._task_dependency_graph_row(duplicate)
                    cur.execute("SELECT graph_id FROM mission_task_dependency_graphs WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is not None:
                        raise MissionTaskDependencyGraphConflict(
                            "Stage 3.3.4 allows exactly one immutable dependency graph per canonical decomposition"
                        )
                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    plan = cur.fetchone()
                    cur.execute("SELECT * FROM mission_planner_input_snapshots WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    snapshot = cur.fetchone()
                    cur.execute("SELECT * FROM mission_task_decompositions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    decomposition = cur.fetchone()
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state = cur.fetchone()
                    cur.execute("SELECT * FROM mission_planned_tasks WHERE mission_id=%s ORDER BY task_index, id FOR UPDATE", (mission_id,))
                    tasks = cur.fetchall()
                    if (
                        plan is None or plan["plan_id"] != plan_id or int(plan["plan_version"]) != int(plan_version)
                        or plan["canonical_sha256"] != expected_plan_sha256
                    ):
                        raise MissionTaskDependencyGraphConflict(
                            "canonical Plan identity/version/hash changed before dependency graph registration"
                        )
                    if (
                        snapshot is None or snapshot["snapshot_id"] != snapshot_id
                        or int(snapshot["snapshot_version"]) != int(snapshot_version)
                        or snapshot["canonical_sha256"] != expected_snapshot_sha256
                    ):
                        raise MissionTaskDependencyGraphConflict(
                            "planner-input snapshot identity/version/hash changed before dependency graph registration"
                        )
                    if (
                        decomposition is None or decomposition["decomposition_id"] != decomposition_id
                        or int(decomposition["decomposition_version"]) != int(decomposition_version)
                        or decomposition["canonical_sha256"] != expected_decomposition_sha256
                        or decomposition["task_set_sha256"] != expected_task_set_sha256
                    ):
                        raise MissionTaskDependencyGraphConflict(
                            "canonical task decomposition identity/version/hash changed before dependency graph registration"
                        )
                    if (
                        state is None or state["state"] != "PLANNING"
                        or int(state["state_version"]) != int(expected_state_version)
                    ):
                        raise MissionTaskDependencyGraphConflict(
                            "mission PLANNING state/version drifted before dependency graph registration"
                        )
                    if not verify_task_rows(tasks):
                        raise MissionTaskDependencyGraphConflict(
                            "canonical planned-task store drifted from the dependency graph node set"
                        )
                    cur.execute(
                        """INSERT INTO mission_task_dependency_graphs
                        (graph_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                         snapshot_id, snapshot_version, graph_version, schema_version, request_sha256, idempotency_key,
                         canonical_sha256, node_set_sha256, edge_set_sha256, canonical_json, source_state_version,
                         source_plan_sha256, source_snapshot_sha256, source_decomposition_sha256, source_task_set_sha256,
                         source_version_sha256, node_count, edge_count, validation_status, created_by, reason, created_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                                %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            graph_id, mission_id, decomposition_id, decomposition_version, plan_id, plan_version,
                            snapshot_id, snapshot_version, graph_version, TASK_DEPENDENCY_GRAPH_SCHEMA_VERSION,
                            request_sha256, idempotency_key, canonical_sha256, node_set_sha256, edge_set_sha256,
                            canonical_json_value, expected_state_version, expected_plan_sha256, expected_snapshot_sha256,
                            expected_decomposition_sha256, expected_task_set_sha256, source_version_sha256,
                            len(nodes), len(edge_contracts), "PASS", actor, reason, self._mysql_dt(created_at),
                        ),
                    )
                    for edge in edge_contracts:
                        identity = edge["identity"]
                        dep = edge["dependency"]
                        cur.execute(
                            """INSERT INTO mission_task_dependency_edges
                            (dependency_edge_id, graph_id, graph_version, mission_id, decomposition_id,
                             decomposition_version, plan_id, plan_version, from_planned_task_id, from_task_key,
                             to_planned_task_id, to_task_key, schema_version, canonical_sha256, canonical_json, created_at)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                            (
                                identity["dependency_edge_id"], graph_id, graph_version, mission_id, decomposition_id,
                                decomposition_version, plan_id, plan_version, dep["from_planned_task_id"],
                                dep["from_task_key"], dep["to_planned_task_id"], dep["to_task_key"],
                                TASK_DEPENDENCY_EDGE_SCHEMA_VERSION, edge["integrity"]["canonical_sha256"],
                                json.dumps(edge, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
                                self._mysql_dt(created_at),
                            ),
                        )
                    cur.execute("SELECT * FROM mission_task_dependency_graphs WHERE graph_id=%s", (graph_id,))
                    row = cur.fetchone()
                conn.commit()
                return self._task_dependency_graph_row(row)
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    @classmethod
    def _planner_invocation_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "planner_invocation_id": row["planner_invocation_id"],
            "mission_id": row["mission_id"],
            "plan_id": row["plan_id"],
            "plan_version": int(row["plan_version"]),
            "snapshot_id": row["snapshot_id"],
            "snapshot_version": int(row["snapshot_version"]),
            "decomposition_id": row["decomposition_id"],
            "decomposition_version": int(row["decomposition_version"]),
            "graph_id": row["graph_id"],
            "graph_version": int(row["graph_version"]),
            "generation_version": int(row["generation_version"]),
            "schema_version": row["schema_version"],
            "planner_profile": row["planner_profile"],
            "planner_engine": row["planner_engine"],
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "output_sha256": row["output_sha256"],
            "canonical_sha256": row["canonical_sha256"],
            "planner_invocation": json.loads(row["canonical_json"]),
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "source_plan_sha256": row["source_plan_sha256"],
            "source_snapshot_sha256": row["source_snapshot_sha256"],
            "source_decomposition_sha256": row["source_decomposition_sha256"],
            "source_task_set_sha256": row["source_task_set_sha256"],
            "source_graph_sha256": row["source_graph_sha256"],
            "source_node_set_sha256": row["source_node_set_sha256"],
            "source_edge_set_sha256": row["source_edge_set_sha256"],
            "created_by": row["created_by"],
            "reason": row.get("reason"),
            "created_at": cls._iso_from_db(row["created_at"]),
        }

    @classmethod
    def _generated_plan_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "generated_plan_id": row["generated_plan_id"],
            "planner_invocation_id": row["planner_invocation_id"],
            "mission_id": row["mission_id"],
            "plan_id": row["plan_id"],
            "plan_version": int(row["plan_version"]),
            "generation_version": int(row["generation_version"]),
            "schema_version": row["schema_version"],
            "status": row["status"],
            "planner_profile": row["planner_profile"],
            "planner_output_sha256": row["planner_output_sha256"],
            "canonical_sha256": row["canonical_sha256"],
            "generated_plan": json.loads(row["canonical_json"]),
            "task_count": int(row["task_count"]),
            "dependency_edge_count": int(row["dependency_edge_count"]),
            "planning_layer_count": int(row["planning_layer_count"]),
            "created_at": cls._iso_from_db(row["created_at"]),
        }

    def get_planner_invocation(self, mission_id: str) -> Optional[Dict[str, Any]]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                row = conn.execute(
                    "SELECT * FROM mission_planner_invocations WHERE mission_id=? ORDER BY generation_version DESC, id DESC LIMIT 1",
                    (mission_id,),
                ).fetchone()
            else:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_planner_invocations WHERE mission_id=%s ORDER BY generation_version DESC, id DESC LIMIT 1",
                        (mission_id,),
                    )
                    row = cur.fetchone()
            return None if row is None else self._planner_invocation_row(dict(row))
        finally:
            conn.close()

