    def store_planner_generation(
        self,
        *,
        mission_id: str,
        planner_invocation_id: str,
        generated_plan_id: str,
        generation_version: int,
        plan_id: str,
        plan_version: int,
        snapshot_id: str,
        snapshot_version: int,
        decomposition_id: str,
        decomposition_version: int,
        graph_id: str,
        graph_version: int,
        planner_profile: str,
        request_sha256: str,
        idempotency_key: str,
        planner_invocation: Dict[str, Any],
        generated_plan: Dict[str, Any],
        expected_state_version: int,
        source_version_sha256: str,
        expected_plan_sha256: str,
        expected_snapshot_sha256: str,
        expected_decomposition_sha256: str,
        expected_task_set_sha256: str,
        expected_graph_sha256: str,
        expected_node_set_sha256: str,
        expected_edge_set_sha256: str,
        actor: str,
        reason: Optional[str],
        created_at: str,
    ) -> tuple[Dict[str, Any], Dict[str, Any]]:
        invocation_json = json.dumps(planner_invocation, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        generated_json = json.dumps(generated_plan, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        invocation_sha = planner_invocation["integrity"]["canonical_sha256"]
        generated_sha = generated_plan["integrity"]["canonical_sha256"]
        output_sha = planner_invocation["output"]["output_sha256"]
        generated_body = generated_plan["generated_plan"]

        def validate_heads(plan, snapshot, decomposition, graph, state) -> None:
            if (
                plan is None or plan["plan_id"] != plan_id or int(plan["plan_version"]) != int(plan_version)
                or plan["canonical_sha256"] != expected_plan_sha256
            ):
                raise MissionPlannerGenerationConflict("canonical Plan identity/version/hash changed before planner invocation commit")
            if (
                snapshot is None or snapshot["snapshot_id"] != snapshot_id
                or int(snapshot["snapshot_version"]) != int(snapshot_version)
                or snapshot["canonical_sha256"] != expected_snapshot_sha256
            ):
                raise MissionPlannerGenerationConflict("planner-input snapshot identity/version/hash changed before planner invocation commit")
            if (
                decomposition is None or decomposition["decomposition_id"] != decomposition_id
                or int(decomposition["decomposition_version"]) != int(decomposition_version)
                or decomposition["canonical_sha256"] != expected_decomposition_sha256
                or decomposition["task_set_sha256"] != expected_task_set_sha256
            ):
                raise MissionPlannerGenerationConflict("task decomposition identity/version/hash changed before planner invocation commit")
            if (
                graph is None or graph["graph_id"] != graph_id or int(graph["graph_version"]) != int(graph_version)
                or graph["canonical_sha256"] != expected_graph_sha256
                or graph["node_set_sha256"] != expected_node_set_sha256
                or graph["edge_set_sha256"] != expected_edge_set_sha256
                or graph["validation_status"] != "PASS"
            ):
                raise MissionPlannerGenerationConflict("validated dependency graph identity/version/hash changed before planner invocation commit")
            if state is None or state["state"] != "PLANNING" or int(state["state_version"]) != int(expected_state_version):
                raise MissionPlannerGenerationConflict("mission PLANNING state/version drifted before planner invocation commit")

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None:
                    conn.rollback(); raise MissionNotFound(mission_id)
                dup = conn.execute(
                    "SELECT * FROM mission_planner_invocations WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        conn.rollback(); raise MissionPlannerGenerationConflict(
                            "planner-invocation idempotency_key was already used with a different canonical request"
                        )
                    generated = conn.execute(
                        "SELECT * FROM mission_generated_plans WHERE planner_invocation_id=?",
                        (dup["planner_invocation_id"],),
                    ).fetchone()
                    conn.rollback()
                    if generated is None:
                        raise MissionPlannerGenerationConflict("planner invocation exists without generated-plan artifact")
                    return self._planner_invocation_row(dict(dup)), self._generated_plan_row(dict(generated))
                existing = conn.execute(
                    "SELECT planner_invocation_id FROM mission_planner_invocations WHERE plan_id=? AND plan_version=?",
                    (plan_id, plan_version),
                ).fetchone()
                if existing is not None:
                    conn.rollback(); raise MissionPlannerGenerationConflict(
                        "Stage 3.3.5 allows exactly one immutable planner generation for the current canonical Plan version"
                    )
                plan = conn.execute("SELECT * FROM mission_plans WHERE mission_id=?", (mission_id,)).fetchone()
                snapshot = conn.execute("SELECT * FROM mission_planner_input_snapshots WHERE mission_id=?", (mission_id,)).fetchone()
                decomposition = conn.execute("SELECT * FROM mission_task_decompositions WHERE mission_id=?", (mission_id,)).fetchone()
                graph = conn.execute("SELECT * FROM mission_task_dependency_graphs WHERE mission_id=?", (mission_id,)).fetchone()
                state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                validate_heads(plan, snapshot, decomposition, graph, state)
                conn.execute(
                    """INSERT INTO mission_planner_invocations
                    (planner_invocation_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                     decomposition_id, decomposition_version, graph_id, graph_version, generation_version,
                     schema_version, planner_profile, planner_engine, request_sha256, idempotency_key,
                     output_sha256, canonical_sha256, canonical_json, source_state_version, source_version_sha256,
                     source_plan_sha256, source_snapshot_sha256, source_decomposition_sha256, source_task_set_sha256,
                     source_graph_sha256, source_node_set_sha256, source_edge_set_sha256, created_by, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (planner_invocation_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                     decomposition_id, decomposition_version, graph_id, graph_version, generation_version,
                     PLANNER_INVOCATION_SCHEMA_VERSION, planner_profile, PLANNER_ENGINE, request_sha256, idempotency_key,
                     output_sha, invocation_sha, invocation_json, expected_state_version, source_version_sha256,
                     expected_plan_sha256, expected_snapshot_sha256, expected_decomposition_sha256,
                     expected_task_set_sha256, expected_graph_sha256, expected_node_set_sha256, expected_edge_set_sha256,
                     actor, reason, created_at)
                )
                conn.execute(
                    """INSERT INTO mission_generated_plans
                    (generated_plan_id, planner_invocation_id, mission_id, plan_id, plan_version, generation_version,
                     schema_version, status, planner_profile, planner_output_sha256, canonical_sha256, canonical_json,
                     task_count, dependency_edge_count, planning_layer_count, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (generated_plan_id, planner_invocation_id, mission_id, plan_id, plan_version, generation_version,
                     GENERATED_PLAN_SCHEMA_VERSION, GENERATED_PLAN_STATUS, planner_profile, output_sha, generated_sha,
                     generated_json, int(generated_body["task_count"]), int(generated_body["dependency_edge_count"]),
                     int(generated_body["planning_layer_count"]), created_at)
                )
                inv = conn.execute("SELECT * FROM mission_planner_invocations WHERE planner_invocation_id=?", (planner_invocation_id,)).fetchone()
                gen = conn.execute("SELECT * FROM mission_generated_plans WHERE generated_plan_id=?", (generated_plan_id,)).fetchone()
                conn.commit()
                return self._planner_invocation_row(dict(inv)), self._generated_plan_row(dict(gen))

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None: raise MissionNotFound(mission_id)
                    cur.execute(
                        "SELECT * FROM mission_planner_invocations WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionPlannerGenerationConflict(
                                "planner-invocation idempotency_key was already used with a different canonical request"
                            )
                        cur.execute("SELECT * FROM mission_generated_plans WHERE planner_invocation_id=%s", (dup["planner_invocation_id"],))
                        gen = cur.fetchone(); conn.rollback()
                        if gen is None: raise MissionPlannerGenerationConflict("planner invocation exists without generated-plan artifact")
                        return self._planner_invocation_row(dup), self._generated_plan_row(gen)
                    cur.execute("SELECT planner_invocation_id FROM mission_planner_invocations WHERE plan_id=%s AND plan_version=%s FOR UPDATE", (plan_id, plan_version))
                    if cur.fetchone() is not None:
                        raise MissionPlannerGenerationConflict(
                            "Stage 3.3.5 allows exactly one immutable planner generation for the current canonical Plan version"
                        )
                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s FOR UPDATE", (mission_id,)); plan=cur.fetchone()
                    cur.execute("SELECT * FROM mission_planner_input_snapshots WHERE mission_id=%s FOR UPDATE", (mission_id,)); snapshot=cur.fetchone()
                    cur.execute("SELECT * FROM mission_task_decompositions WHERE mission_id=%s FOR UPDATE", (mission_id,)); decomposition=cur.fetchone()
                    cur.execute("SELECT * FROM mission_task_dependency_graphs WHERE mission_id=%s FOR UPDATE", (mission_id,)); graph=cur.fetchone()
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    validate_heads(plan, snapshot, decomposition, graph, state)
                    cur.execute(
                        """INSERT INTO mission_planner_invocations
                        (planner_invocation_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                         decomposition_id, decomposition_version, graph_id, graph_version, generation_version,
                         schema_version, planner_profile, planner_engine, request_sha256, idempotency_key,
                         output_sha256, canonical_sha256, canonical_json, source_state_version, source_version_sha256,
                         source_plan_sha256, source_snapshot_sha256, source_decomposition_sha256, source_task_set_sha256,
                         source_graph_sha256, source_node_set_sha256, source_edge_set_sha256, created_by, reason, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (planner_invocation_id, mission_id, plan_id, plan_version, snapshot_id, snapshot_version,
                         decomposition_id, decomposition_version, graph_id, graph_version, generation_version,
                         PLANNER_INVOCATION_SCHEMA_VERSION, planner_profile, PLANNER_ENGINE, request_sha256, idempotency_key,
                         output_sha, invocation_sha, invocation_json, expected_state_version, source_version_sha256,
                         expected_plan_sha256, expected_snapshot_sha256, expected_decomposition_sha256,
                         expected_task_set_sha256, expected_graph_sha256, expected_node_set_sha256, expected_edge_set_sha256,
                         actor, reason, self._db_datetime(created_at))
                    )
                    cur.execute(
                        """INSERT INTO mission_generated_plans
                        (generated_plan_id, planner_invocation_id, mission_id, plan_id, plan_version, generation_version,
                         schema_version, status, planner_profile, planner_output_sha256, canonical_sha256, canonical_json,
                         task_count, dependency_edge_count, planning_layer_count, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (generated_plan_id, planner_invocation_id, mission_id, plan_id, plan_version, generation_version,
                         GENERATED_PLAN_SCHEMA_VERSION, GENERATED_PLAN_STATUS, planner_profile, output_sha, generated_sha,
                         generated_json, int(generated_body["task_count"]), int(generated_body["dependency_edge_count"]),
                         int(generated_body["planning_layer_count"]), self._db_datetime(created_at))
                    )
                    cur.execute("SELECT * FROM mission_planner_invocations WHERE planner_invocation_id=%s", (planner_invocation_id,)); inv=cur.fetchone()
                    cur.execute("SELECT * FROM mission_generated_plans WHERE generated_plan_id=%s", (generated_plan_id,)); gen=cur.fetchone()
                conn.commit()
                return self._planner_invocation_row(inv), self._generated_plan_row(gen)
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

    @classmethod
    def _plan_validation_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "plan_validation_id": row["plan_validation_id"],
            "mission_id": row["mission_id"],
            "plan_id": row["plan_id"],
            "plan_version": int(row["plan_version"]),
            "generated_plan_id": row["generated_plan_id"],
            "generation_version": int(row["generation_version"]),
            "validation_version": int(row["validation_version"]),
            "schema_version": row["schema_version"],
            "status": row["status"],
            "feasible": bool(row["feasible"]),
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "canonical_sha256": row["canonical_sha256"],
            "plan_validation": json.loads(row["canonical_json"]),
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "source_generated_plan_sha256": row["source_generated_plan_sha256"],
            "created_by": row["created_by"],
            "reason": row.get("reason"),
            "created_at": cls._iso_from_db(row["created_at"]),
        }

    def get_plan_validation(self, mission_id: str) -> Optional[Dict[str, Any]]:
        conn = self._connect()
