    def store_initial_plan_version(
        self, *, mission_id: str, plan_version_record_id: str, canonical_plan_id: str,
        request_sha256: str, idempotency_key: str, plan_version_contract: Dict[str, Any],
        candidate_plan_sha256: str, expected_state_version: int, source_version_sha256: str,
        expected_base_plan_sha256: str, expected_plan_validation_id: str, expected_plan_validation_sha256: str,
        actor: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(plan_version_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = plan_version_contract["integrity"]["canonical_sha256"]
        activation_type = plan_version_contract["activation"]["activation_type"]
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None:
                        raise MissionNotFound(mission_id)
                    dup = conn.execute("SELECT * FROM mission_plan_versions WHERE mission_id=? AND idempotency_key=?", (mission_id, idempotency_key)).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionPlanVersioningConflict("plan-version idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._plan_version_row(dict(dup))
                    if conn.execute("SELECT mission_id FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone() is not None:
                        raise MissionPlanVersioningConflict("initial active Plan version already exists")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    plan = conn.execute("SELECT * FROM mission_plans WHERE mission_id=? AND plan_id=?", (mission_id, canonical_plan_id)).fetchone()
                    validation = conn.execute("SELECT * FROM mission_plan_validations WHERE mission_id=? AND plan_validation_id=?", (mission_id, expected_plan_validation_id)).fetchone()
                    if state is None or state["state"] != "PLANNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionPlanVersioningConflict("Mission state changed before initial Plan-version activation commit")
                    if plan is None or plan["canonical_sha256"] != expected_base_plan_sha256:
                        raise MissionPlanVersioningConflict("canonical base Plan changed before initial Plan-version activation commit")
                    if validation is None or validation["canonical_sha256"] != expected_plan_validation_sha256 or validation["status"] != "VALIDATED_FEASIBLE" or not bool(validation["feasible"]):
                        raise MissionPlanVersioningConflict("validated-feasible Plan binding changed before initial activation commit")
                    conn.execute(
                        """INSERT INTO mission_plan_versions
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type,
                         predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id,
                         schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, candidate_plan_sha256,
                         source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (?, ?, ?, 1, ?, NULL, NULL, NULL, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                        (plan_version_record_id, mission_id, canonical_plan_id, activation_type, PLAN_VERSIONING_SCHEMA_VERSION,
                         request_sha256, idempotency_key, canonical_sha, canonical_json_value, candidate_plan_sha256,
                         expected_state_version, source_version_sha256, actor, reason, created_at),
                    )
                    conn.execute(
                        "INSERT INTO mission_plan_version_heads (mission_id, active_plan_version_record_id, active_plan_version, active_plan_sha256, updated_at) VALUES (?, ?, 1, ?, ?)",
                        (mission_id, plan_version_record_id, canonical_sha, created_at),
                    )
                    row = conn.execute("SELECT * FROM mission_plan_versions WHERE plan_version_record_id=?", (plan_version_record_id,)).fetchone()
                    conn.commit(); return self._plan_version_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None: raise MissionNotFound(mission_id)
                    cur.execute("SELECT * FROM mission_plan_versions WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup=cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256: raise MissionPlanVersioningConflict("plan-version idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._plan_version_row(dict(dup))
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is not None: raise MissionPlanVersioningConflict("initial active Plan version already exists")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s AND plan_id=%s FOR UPDATE", (mission_id, canonical_plan_id)); plan=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_validations WHERE mission_id=%s AND plan_validation_id=%s FOR UPDATE", (mission_id, expected_plan_validation_id)); validation=cur.fetchone()
                    if state is None or state["state"] != "PLANNING" or int(state["state_version"]) != int(expected_state_version): raise MissionPlanVersioningConflict("Mission state changed before initial Plan-version activation commit")
                    if plan is None or plan["canonical_sha256"] != expected_base_plan_sha256: raise MissionPlanVersioningConflict("canonical base Plan changed before initial Plan-version activation commit")
                    if validation is None or validation["canonical_sha256"] != expected_plan_validation_sha256 or validation["status"] != "VALIDATED_FEASIBLE" or not bool(validation["feasible"]): raise MissionPlanVersioningConflict("validated-feasible Plan binding changed before initial activation commit")
                    cur.execute(
                        """INSERT INTO mission_plan_versions
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type, predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id, schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, candidate_plan_sha256, source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (%s,%s,%s,1,%s,NULL,NULL,NULL,NULL,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (plan_version_record_id, mission_id, canonical_plan_id, activation_type, PLAN_VERSIONING_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha, canonical_json_value, candidate_plan_sha256, expected_state_version, source_version_sha256, actor, reason, self._mysql_dt(created_at)),
                    )
                    cur.execute("INSERT INTO mission_plan_version_heads (mission_id, active_plan_version_record_id, active_plan_version, active_plan_sha256, updated_at) VALUES (%s,%s,1,%s,%s)", (mission_id, plan_version_record_id, canonical_sha, self._mysql_dt(created_at)))
                    cur.execute("SELECT * FROM mission_plan_versions WHERE plan_version_record_id=%s", (plan_version_record_id,)); row=cur.fetchone()
                conn.commit(); return self._plan_version_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

    def store_successor_plan_version(
        self, *, mission_id: str, plan_version_record_id: str, canonical_plan_id: str, plan_version: int,
        predecessor_plan_version_record_id: str, predecessor_plan_version: int, expected_active_plan_sha256: str,
        replan_id: str, replan_transition_id: str, request_sha256: str, idempotency_key: str,
        plan_version_contract: Dict[str, Any], candidate_plan_sha256: str, expected_state_version: int,
        source_version_sha256: str, expected_base_plan_sha256: str, actor: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(plan_version_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = plan_version_contract["integrity"]["canonical_sha256"]
        activation_type = plan_version_contract["activation"]["activation_type"]
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None: raise MissionNotFound(mission_id)
                    dup = conn.execute("SELECT * FROM mission_plan_versions WHERE mission_id=? AND idempotency_key=?", (mission_id, idempotency_key)).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256: raise MissionPlanVersioningConflict("plan-version idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._plan_version_row(dict(dup))
                    existing_replan = conn.execute("SELECT * FROM mission_plan_versions WHERE mission_id=? AND replan_id=?", (mission_id, replan_id)).fetchone()
                    if existing_replan is not None: raise MissionPlanVersioningConflict("this Stage-3.2.6 replanning episode already has a successor Plan version")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    plan = conn.execute("SELECT * FROM mission_plans WHERE mission_id=? AND plan_id=?", (mission_id, canonical_plan_id)).fetchone()
                    if state is None or state["state"] != "REPLANNING" or int(state["state_version"]) != int(expected_state_version): raise MissionPlanVersioningConflict("Mission state changed before successor Plan-version commit")
                    if head is None or int(head["active_plan_version"]) != int(predecessor_plan_version) or head["active_plan_version_record_id"] != predecessor_plan_version_record_id or head["active_plan_sha256"] != expected_active_plan_sha256: raise MissionPlanVersioningConflict("active Plan head changed before successor Plan-version commit")
                    if int(plan_version) != int(predecessor_plan_version) + 1: raise MissionPlanVersioningConflict("successor Plan version must equal predecessor + 1")
                    if plan is None or plan["canonical_sha256"] != expected_base_plan_sha256: raise MissionPlanVersioningConflict("canonical base Plan changed before successor Plan-version commit")
                    conn.execute(
                        """INSERT INTO mission_plan_versions
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type, predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id, schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, candidate_plan_sha256, source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type, predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id, PLAN_VERSIONING_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha, canonical_json_value, candidate_plan_sha256, expected_state_version, source_version_sha256, actor, reason, created_at),
                    )
                    updated = conn.execute(
                        """UPDATE mission_plan_version_heads SET active_plan_version_record_id=?, active_plan_version=?, active_plan_sha256=?, updated_at=?
                           WHERE mission_id=? AND active_plan_version_record_id=? AND active_plan_version=? AND active_plan_sha256=?""",
                        (plan_version_record_id, plan_version, canonical_sha, created_at, mission_id, predecessor_plan_version_record_id, predecessor_plan_version, expected_active_plan_sha256),
                    )
                    if updated.rowcount != 1: raise MissionPlanVersioningConflict("active Plan head CAS failed")
                    row = conn.execute("SELECT * FROM mission_plan_versions WHERE plan_version_record_id=?", (plan_version_record_id,)).fetchone()
                    conn.commit(); return self._plan_version_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None: raise MissionNotFound(mission_id)
                    cur.execute("SELECT * FROM mission_plan_versions WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup=cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256: raise MissionPlanVersioningConflict("plan-version idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._plan_version_row(dict(dup))
                    cur.execute("SELECT * FROM mission_plan_versions WHERE mission_id=%s AND replan_id=%s FOR UPDATE", (mission_id, replan_id))
                    if cur.fetchone() is not None: raise MissionPlanVersioningConflict("this Stage-3.2.6 replanning episode already has a successor Plan version")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plans WHERE mission_id=%s AND plan_id=%s FOR UPDATE", (mission_id, canonical_plan_id)); plan=cur.fetchone()
                    if state is None or state["state"] != "REPLANNING" or int(state["state_version"]) != int(expected_state_version): raise MissionPlanVersioningConflict("Mission state changed before successor Plan-version commit")
                    if head is None or int(head["active_plan_version"]) != int(predecessor_plan_version) or head["active_plan_version_record_id"] != predecessor_plan_version_record_id or head["active_plan_sha256"] != expected_active_plan_sha256: raise MissionPlanVersioningConflict("active Plan head changed before successor Plan-version commit")
                    if int(plan_version) != int(predecessor_plan_version) + 1: raise MissionPlanVersioningConflict("successor Plan version must equal predecessor + 1")
                    if plan is None or plan["canonical_sha256"] != expected_base_plan_sha256: raise MissionPlanVersioningConflict("canonical base Plan changed before successor Plan-version commit")
                    cur.execute(
                        """INSERT INTO mission_plan_versions
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type, predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id, schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, candidate_plan_sha256, source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        (plan_version_record_id, mission_id, canonical_plan_id, plan_version, activation_type, predecessor_plan_version_record_id, predecessor_plan_version, replan_id, replan_transition_id, PLAN_VERSIONING_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha, canonical_json_value, candidate_plan_sha256, expected_state_version, source_version_sha256, actor, reason, self._mysql_dt(created_at)),
                    )
                    cur.execute(
                        """UPDATE mission_plan_version_heads SET active_plan_version_record_id=%s, active_plan_version=%s, active_plan_sha256=%s, updated_at=%s
                           WHERE mission_id=%s AND active_plan_version_record_id=%s AND active_plan_version=%s AND active_plan_sha256=%s""",
                        (plan_version_record_id, plan_version, canonical_sha, self._mysql_dt(created_at), mission_id, predecessor_plan_version_record_id, predecessor_plan_version, expected_active_plan_sha256),
                    )
                    if cur.rowcount != 1: raise MissionPlanVersioningConflict("active Plan head CAS failed")
                    cur.execute("SELECT * FROM mission_plan_versions WHERE plan_version_record_id=%s", (plan_version_record_id,)); row=cur.fetchone()
                conn.commit(); return self._plan_version_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

