    def store_task_readiness_projection(
        self, *, mission_id: str, projection_id: str, plan_version_record_id: str, plan_version: int,
        request_sha256: str, idempotency_key: str, projection_contract: Dict[str, Any],
        expected_state_version: int, source_version_sha256: str, expected_active_plan_sha256: str,
        actor: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(projection_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = projection_contract["integrity"]["canonical_sha256"]
        projection = projection_contract["projection"]
        values = (
            projection_id, mission_id, plan_version_record_id, int(plan_version), TASK_READINESS_PROJECTION_SCHEMA_VERSION,
            request_sha256, idempotency_key, canonical_sha, canonical_json_value, int(expected_state_version),
            source_version_sha256, int(projection["ready_task_count"]), int(projection["blocked_task_count"]),
            int(projection["task_count"]), int(projection["scheduling_projection"]["wave_count"]), actor, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None:
                        raise MissionNotFound(mission_id)
                    dup = conn.execute(
                        "SELECT * FROM mission_task_readiness_projections WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionTaskReadinessProjectionConflict("task-readiness projection idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._task_readiness_projection_row(dict(dup))
                    existing = conn.execute(
                        "SELECT * FROM mission_task_readiness_projections WHERE mission_id=? AND plan_version=?",
                        (mission_id, int(plan_version)),
                    ).fetchone()
                    if existing is not None:
                        raise MissionTaskReadinessProjectionConflict("active Plan version already has an immutable Stage-3.3.8 readiness projection")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionTaskReadinessProjectionConflict("Mission state changed before task-readiness projection commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionTaskReadinessProjectionConflict("active Plan head changed before task-readiness projection commit")
                    conn.execute(
                        """INSERT INTO mission_task_readiness_projections
                        (projection_id, mission_id, plan_version_record_id, plan_version, schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, source_state_version, source_version_sha256, ready_task_count, blocked_task_count, task_count, wave_count, created_by, reason, created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", values)
                    row = conn.execute("SELECT * FROM mission_task_readiness_projections WHERE projection_id=?", (projection_id,)).fetchone()
                    conn.commit(); return self._task_readiness_projection_row(dict(row))
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None: raise MissionNotFound(mission_id)
                    cur.execute("SELECT * FROM mission_task_readiness_projections WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup=cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionTaskReadinessProjectionConflict("task-readiness projection idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._task_readiness_projection_row(dict(dup))
                    cur.execute("SELECT * FROM mission_task_readiness_projections WHERE mission_id=%s AND plan_version=%s FOR UPDATE", (mission_id, int(plan_version)))
                    if cur.fetchone() is not None: raise MissionTaskReadinessProjectionConflict("active Plan version already has an immutable Stage-3.3.8 readiness projection")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head=cur.fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionTaskReadinessProjectionConflict("Mission state changed before task-readiness projection commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionTaskReadinessProjectionConflict("active Plan head changed before task-readiness projection commit")
                    mysql_values = list(values); mysql_values[-1] = self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_task_readiness_projections
                        (projection_id, mission_id, plan_version_record_id, plan_version, schema_version, request_sha256, idempotency_key, canonical_sha256, canonical_json, source_state_version, source_version_sha256, ready_task_count, blocked_task_count, task_count, wave_count, created_by, reason, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", tuple(mysql_values))
                    cur.execute("SELECT * FROM mission_task_readiness_projections WHERE projection_id=%s", (projection_id,)); row=cur.fetchone()
                conn.commit(); return self._task_readiness_projection_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

