    def store_task_routing_eligibility(
        self, *, mission_id: str, eligibility_gate_id: str, routing_intent_id: str,
        plan_version_record_id: str, plan_version: int, readiness_projection_id: str,
        planned_task_id: str, task_key: str, request_sha256: str, idempotency_key: str,
        registry_id: str, registry_version: int, registry_sha256: str,
        routing_intent_sha256: str, eligibility_contract: Dict[str, Any],
        expected_state_version: int, source_version_sha256: str,
        expected_active_plan_sha256: str, expected_readiness_projection_sha256: str,
        actor: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(eligibility_contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = eligibility_contract["integrity"]["canonical_sha256"]
        gate = eligibility_contract["eligibility_gate"]
        values = (
            eligibility_gate_id, mission_id, routing_intent_id, plan_version_record_id, int(plan_version),
            readiness_projection_id, planned_task_id, task_key, TASK_ROUTING_ELIGIBILITY_SCHEMA_VERSION,
            request_sha256, idempotency_key, registry_id, int(registry_version), registry_sha256,
            routing_intent_sha256, gate["gate_result"], gate["eligibility_status"],
            int(gate["candidate_count"]), int(gate["eligible_candidate_count"]), int(gate["ineligible_candidate_count"]),
            canonical_sha, canonical_json_value, int(expected_state_version), source_version_sha256,
            actor, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None:
                        raise MissionNotFound(mission_id)
                    dup = conn.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionTaskRoutingEligibilityConflict(
                                "task-routing eligibility idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._task_routing_eligibility_row(dict(dup))
                    existing = conn.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE mission_id=? AND routing_intent_id=?",
                        (mission_id, routing_intent_id),
                    ).fetchone()
                    if existing is not None:
                        raise MissionTaskRoutingEligibilityConflict(
                            "Stage-3.4.2 routing intent already has an immutable Stage-3.4.3 eligibility gate"
                        )
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    readiness = conn.execute(
                        "SELECT * FROM mission_task_readiness_projections WHERE mission_id=? AND projection_id=?",
                        (mission_id, readiness_projection_id),
                    ).fetchone()
                    routing_intent = conn.execute(
                        "SELECT * FROM mission_task_routing_intents WHERE mission_id=? AND routing_intent_id=?",
                        (mission_id, routing_intent_id),
                    ).fetchone()
                    registry = conn.execute(
                        "SELECT * FROM subsystem_registry_snapshots WHERE registry_id=? AND registry_version=?",
                        (registry_id, int(registry_version)),
                    ).fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionTaskRoutingEligibilityConflict("Mission state changed before task-routing eligibility commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionTaskRoutingEligibilityConflict("active Plan head changed before task-routing eligibility commit")
                    if readiness is None or int(readiness["plan_version"]) != int(plan_version) or readiness["canonical_sha256"] != expected_readiness_projection_sha256:
                        raise MissionTaskRoutingEligibilityConflict("active task-readiness projection changed before task-routing eligibility commit")
                    if routing_intent is None or routing_intent["canonical_sha256"] != routing_intent_sha256:
                        raise MissionTaskRoutingEligibilityConflict("Stage-3.4.2 routing intent changed before eligibility commit")
                    if registry is None or registry["canonical_sha256"] != registry_sha256:
                        raise MissionTaskRoutingEligibilityConflict("canonical subsystem registry changed before eligibility commit")
                    conn.execute(
                        """INSERT INTO mission_task_routing_eligibility_gates
                        (eligibility_gate_id, mission_id, routing_intent_id, plan_version_record_id, plan_version, readiness_projection_id, planned_task_id, task_key, schema_version, request_sha256, idempotency_key, registry_id, registry_version, registry_sha256, routing_intent_sha256, gate_result, eligibility_status, candidate_count, eligible_candidate_count, ineligible_candidate_count, canonical_sha256, canonical_json, source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE eligibility_gate_id=?",
                        (eligibility_gate_id,),
                    ).fetchone()
                    conn.commit()
                    return self._task_routing_eligibility_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)
                    cur.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionTaskRoutingEligibilityConflict(
                                "task-routing eligibility idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._task_routing_eligibility_row(dict(dup))
                    cur.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE mission_id=%s AND routing_intent_id=%s FOR UPDATE",
                        (mission_id, routing_intent_id),
                    )
                    if cur.fetchone() is not None:
                        raise MissionTaskRoutingEligibilityConflict(
                            "Stage-3.4.2 routing intent already has an immutable Stage-3.4.3 eligibility gate"
                        )
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state = cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    head = cur.fetchone()
                    cur.execute(
                        "SELECT * FROM mission_task_readiness_projections WHERE mission_id=%s AND projection_id=%s FOR UPDATE",
                        (mission_id, readiness_projection_id),
                    )
                    readiness = cur.fetchone()
                    cur.execute(
                        "SELECT * FROM mission_task_routing_intents WHERE mission_id=%s AND routing_intent_id=%s FOR UPDATE",
                        (mission_id, routing_intent_id),
                    )
                    routing_intent = cur.fetchone()
                    cur.execute(
                        "SELECT * FROM subsystem_registry_snapshots WHERE registry_id=%s AND registry_version=%s FOR UPDATE",
                        (registry_id, int(registry_version)),
                    )
                    registry = cur.fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionTaskRoutingEligibilityConflict("Mission state changed before task-routing eligibility commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionTaskRoutingEligibilityConflict("active Plan head changed before task-routing eligibility commit")
                    if readiness is None or int(readiness["plan_version"]) != int(plan_version) or readiness["canonical_sha256"] != expected_readiness_projection_sha256:
                        raise MissionTaskRoutingEligibilityConflict("active task-readiness projection changed before task-routing eligibility commit")
                    if routing_intent is None or routing_intent["canonical_sha256"] != routing_intent_sha256:
                        raise MissionTaskRoutingEligibilityConflict("Stage-3.4.2 routing intent changed before eligibility commit")
                    if registry is None or registry["canonical_sha256"] != registry_sha256:
                        raise MissionTaskRoutingEligibilityConflict("canonical subsystem registry changed before eligibility commit")
                    mysql_values = list(values)
                    mysql_values[-1] = self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_task_routing_eligibility_gates
                        (eligibility_gate_id, mission_id, routing_intent_id, plan_version_record_id, plan_version, readiness_projection_id, planned_task_id, task_key, schema_version, request_sha256, idempotency_key, registry_id, registry_version, registry_sha256, routing_intent_sha256, gate_result, eligibility_status, candidate_count, eligible_candidate_count, ineligible_candidate_count, canonical_sha256, canonical_json, source_state_version, source_version_sha256, created_by, reason, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        tuple(mysql_values),
                    )
                    cur.execute(
                        "SELECT * FROM mission_task_routing_eligibility_gates WHERE eligibility_gate_id=%s",
                        (eligibility_gate_id,),
                    )
                    row = cur.fetchone()
                conn.commit()
                return self._task_routing_eligibility_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

