                    if conn.execute(
                        "SELECT 1 FROM mission_delegation_deliveries WHERE mission_id=? AND delegation_id=?",
                        (mission_id, delegation_id),
                    ).fetchone() is not None:
                        raise MissionDelegationDeliveryConflict(
                            "Stage-3.4.6 delegation already has an immutable Stage-3.4.7 delivery/acknowledgement/ownership receipt"
                        )
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
