    def store_delegation_recovery_control(
        self,
        *,
        mission_id: str,
        recovery_control_id: str,
        delivery_receipt_id: str,
        delegation_id: str,
        route_decision_id: str,
        plan_version_record_id: str,
        plan_version: int,
        planned_task_id: str,
        task_key: str,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        expected_state_version: int,
        expected_control_count: int,
        source_version_sha256: str,
        requested_by: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        ident = contract["identity"]
        source = contract["source_bindings"]
        decision = contract["recovery_control"]
        current_owner = decision["current_owner"]
        candidate = decision.get("fallback_candidate") or decision.get("reassignment_candidate")
        values = (
            recovery_control_id,
            mission_id,
            delivery_receipt_id,
            delegation_id,
            route_decision_id,
            plan_version_record_id,
            int(plan_version),
            planned_task_id,
            task_key,
            RECOVERY_CONTROL_SCHEMA_VERSION,
            request_sha256,
            idempotency_key,
            int(ident["control_sequence"]),
            decision["requested_action"],
            decision["control_outcome"],
            current_owner["subsystem_id"],
            current_owner["capability_id"],
            int(current_owner["capability_version"]),
            None if candidate is None else candidate["subsystem_id"],
            None if candidate is None else candidate["capability_id"],
            None if candidate is None else int(candidate["capability_version"]),
            None if decision.get("retry_ordinal") is None else int(decision["retry_ordinal"]),
            decision["conflict_status"],
            contract["integrity"]["canonical_sha256"],
            canonical_json_value,
            int(expected_state_version),
            source_version_sha256,
            requested_by,
            reason,
            created_at,
        )
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                conn.execute("BEGIN IMMEDIATE")
                dup = conn.execute(
                    "SELECT * FROM mission_delegation_recovery_controls WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionDelegationRecoveryControlConflict(
                            "delegation recovery-control idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._delegation_recovery_control_row(dict(dup))
                count = int(conn.execute(
                    "SELECT COUNT(*) FROM mission_delegation_recovery_controls WHERE mission_id=? AND delivery_receipt_id=?",
                    (mission_id, delivery_receipt_id),
                ).fetchone()[0])
                if count != int(expected_control_count):
                    raise MissionDelegationRecoveryControlConflict(
                        "delegation recovery-control sequence changed before commit"
                    )
                state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                route = conn.execute(
                    "SELECT * FROM mission_task_route_decisions WHERE mission_id=? AND route_decision_id=?",
                    (mission_id, route_decision_id),
                ).fetchone()
                delegation = conn.execute(
                    "SELECT * FROM mission_task_delegations WHERE mission_id=? AND delegation_id=?",
                    (mission_id, delegation_id),
                ).fetchone()
                delivery = conn.execute(
                    "SELECT * FROM mission_delegation_deliveries WHERE mission_id=? AND delivery_receipt_id=?",
                    (mission_id, delivery_receipt_id),
                ).fetchone()
                previous = None
                if count:
                    previous = conn.execute(
                        "SELECT * FROM mission_delegation_recovery_controls WHERE mission_id=? AND delivery_receipt_id=? ORDER BY control_sequence DESC, id DESC LIMIT 1",
                        (mission_id, delivery_receipt_id),
                    ).fetchone()
                if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                    raise MissionDelegationRecoveryControlConflict("Mission state changed before recovery-control commit")
                if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan_sha256"]:
                    raise MissionDelegationRecoveryControlConflict("active Plan head changed before recovery-control commit")
                if route is None or route["canonical_sha256"] != source["route_decision_sha256"]:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.4 route decision changed before recovery-control commit")
                if delegation is None or delegation["canonical_sha256"] != source["delegation_sha256"] or delegation["route_decision_id"] != route_decision_id:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.6 delegation changed before recovery-control commit")
                if delivery is None or delivery["canonical_sha256"] != source["delivery_receipt_sha256"] or delivery["delegation_id"] != delegation_id:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.7 ownership receipt changed before recovery-control commit")
                prev_id = source.get("previous_recovery_control_id")
                prev_sha = source.get("previous_recovery_control_sha256")
                if count == 0:
                    if prev_id is not None or prev_sha is not None:
                        raise MissionDelegationRecoveryControlConflict("unexpected previous recovery-control binding")
                else:
                    if previous is None or previous["recovery_control_id"] != prev_id or previous["canonical_sha256"] != prev_sha:
                        raise MissionDelegationRecoveryControlConflict("recovery-control predecessor changed before commit")
                conn.execute(
                    """INSERT INTO mission_delegation_recovery_controls
                    (recovery_control_id,mission_id,delivery_receipt_id,delegation_id,route_decision_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,control_sequence,control_action,control_outcome,current_owner_subsystem,current_owner_capability,current_owner_capability_version,proposed_subsystem,proposed_capability,proposed_capability_version,retry_ordinal,conflict_status,canonical_sha256,canonical_json,source_state_version,source_version_sha256,requested_by,reason,created_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    values,
                )
                row = conn.execute(
                    "SELECT * FROM mission_delegation_recovery_controls WHERE recovery_control_id=?",
                    (recovery_control_id,),
                ).fetchone()
                conn.commit()
                return self._delegation_recovery_control_row(dict(row))

            with conn.cursor() as cur:
                cur.execute(
                    "SELECT * FROM mission_delegation_recovery_controls WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                    (mission_id, idempotency_key),
                )
                dup = cur.fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionDelegationRecoveryControlConflict(
                            "delegation recovery-control idempotency_key was already used with a different canonical request"
                        )
                    conn.rollback()
                    return self._delegation_recovery_control_row(dict(dup))
                cur.execute(
                    "SELECT COUNT(*) AS n FROM mission_delegation_recovery_controls WHERE mission_id=%s AND delivery_receipt_id=%s FOR UPDATE",
                    (mission_id, delivery_receipt_id),
                )
                count = int(cur.fetchone()["n"])
                if count != int(expected_control_count):
                    raise MissionDelegationRecoveryControlConflict("delegation recovery-control sequence changed before commit")
                cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                state = cur.fetchone()
                cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,))
                head = cur.fetchone()
                cur.execute("SELECT * FROM mission_task_route_decisions WHERE mission_id=%s AND route_decision_id=%s FOR UPDATE", (mission_id, route_decision_id))
                route = cur.fetchone()
                cur.execute("SELECT * FROM mission_task_delegations WHERE mission_id=%s AND delegation_id=%s FOR UPDATE", (mission_id, delegation_id))
                delegation = cur.fetchone()
                cur.execute("SELECT * FROM mission_delegation_deliveries WHERE mission_id=%s AND delivery_receipt_id=%s FOR UPDATE", (mission_id, delivery_receipt_id))
                delivery = cur.fetchone()
                previous = None
                if count:
                    cur.execute(
                        "SELECT * FROM mission_delegation_recovery_controls WHERE mission_id=%s AND delivery_receipt_id=%s ORDER BY control_sequence DESC, id DESC LIMIT 1 FOR UPDATE",
                        (mission_id, delivery_receipt_id),
                    )
                    previous = cur.fetchone()
                if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                    raise MissionDelegationRecoveryControlConflict("Mission state changed before recovery-control commit")
                if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan_sha256"]:
                    raise MissionDelegationRecoveryControlConflict("active Plan head changed before recovery-control commit")
                if route is None or route["canonical_sha256"] != source["route_decision_sha256"]:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.4 route decision changed before recovery-control commit")
                if delegation is None or delegation["canonical_sha256"] != source["delegation_sha256"] or delegation["route_decision_id"] != route_decision_id:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.6 delegation changed before recovery-control commit")
                if delivery is None or delivery["canonical_sha256"] != source["delivery_receipt_sha256"] or delivery["delegation_id"] != delegation_id:
                    raise MissionDelegationRecoveryControlConflict("Stage-3.4.7 ownership receipt changed before recovery-control commit")
                prev_id = source.get("previous_recovery_control_id")
                prev_sha = source.get("previous_recovery_control_sha256")
                if count == 0:
                    if prev_id is not None or prev_sha is not None:
                        raise MissionDelegationRecoveryControlConflict("unexpected previous recovery-control binding")
                else:
                    if previous is None or previous["recovery_control_id"] != prev_id or previous["canonical_sha256"] != prev_sha:
                        raise MissionDelegationRecoveryControlConflict("recovery-control predecessor changed before commit")
                mysql_values = list(values)
                mysql_values[-1] = self._mysql_dt(created_at)
                cur.execute(
                    """INSERT INTO mission_delegation_recovery_controls
                    (recovery_control_id,mission_id,delivery_receipt_id,delegation_id,route_decision_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,control_sequence,control_action,control_outcome,current_owner_subsystem,current_owner_capability,current_owner_capability_version,proposed_subsystem,proposed_capability,proposed_capability_version,retry_ordinal,conflict_status,canonical_sha256,canonical_json,source_state_version,source_version_sha256,requested_by,reason,created_at)
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                    tuple(mysql_values),
                )
                cur.execute("SELECT * FROM mission_delegation_recovery_controls WHERE recovery_control_id=%s", (recovery_control_id,))
                row = cur.fetchone()
            conn.commit()
            return self._delegation_recovery_control_row(dict(row))
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

