    def store_dispatch_eligibility_gate(
        self,
        *,
        mission_id: str,
        dispatch_eligibility_id: str,
        execution_dispatch_id: str,
        plan_version_record_id: str,
        plan_version: int,
        planned_task_id: str,
        task_key: str,
        task_readiness_projection_id: str,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        expected_state_version: int,
        source_version_sha256: str,
        created_by: str,
        reason: Optional[str],
        created_at: str,
    ) -> Dict[str, Any]:
        src = contract["source_bindings"]
        gate = contract["eligibility_gate"]
        values = (
            dispatch_eligibility_id, mission_id, execution_dispatch_id, plan_version_record_id, int(plan_version),
            planned_task_id, task_key, task_readiness_projection_id, DISPATCH_ELIGIBILITY_SCHEMA_VERSION,
            request_sha256, idempotency_key, gate["gate_result"], gate["eligibility_status"],
            gate["execution_precondition_status"], int(gate["precondition_count"]),
            int(gate["satisfied_precondition_count"]), int(gate["failed_precondition_count"]),
            contract["canonical_sha256"],
            json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False),
            src["source_state"], int(expected_state_version), source_version_sha256, created_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionDispatchEligibilityConflict(
                                "dispatch eligibility idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._dispatch_eligibility_row(dict(dup))
                    if conn.execute(
                        "SELECT 1 FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=? AND execution_dispatch_id=?",
                        (mission_id, execution_dispatch_id),
                    ).fetchone() is not None:
                        raise MissionDispatchEligibilityConflict(
                            "Stage-3.5.1 execution dispatch already has an immutable Stage-3.5.2 eligibility gate"
                        )
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    dispatch = conn.execute(
                        "SELECT * FROM mission_execution_dispatch_contracts WHERE mission_id=? AND execution_dispatch_id=?",
                        (mission_id, execution_dispatch_id),
                    ).fetchone()
                    readiness = conn.execute(
                        "SELECT * FROM mission_task_readiness_projections WHERE mission_id=? AND projection_id=?",
                        (mission_id, task_readiness_projection_id),
                    ).fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionDispatchEligibilityConflict("Mission state changed before Stage-3.5.2 gate commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                        raise MissionDispatchEligibilityConflict("active Plan head changed before Stage-3.5.2 gate commit")
                    if dispatch is None or dispatch["canonical_sha256"] != src["execution_dispatch_sha256"]:
                        raise MissionDispatchEligibilityConflict("Stage-3.5.1 execution dispatch changed before Stage-3.5.2 gate commit")
                    if readiness is None or readiness["canonical_sha256"] != src["task_readiness_projection_sha256"]:
                        raise MissionDispatchEligibilityConflict("task readiness projection changed before Stage-3.5.2 gate commit")
                    conn.execute(
                        """INSERT INTO mission_execution_dispatch_eligibility_gates
                        (dispatch_eligibility_id,mission_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,task_readiness_projection_id,schema_version,request_sha256,idempotency_key,gate_result,eligibility_status,execution_precondition_status,precondition_count,satisfied_precondition_count,failed_precondition_count,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,created_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute(
                        "SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE dispatch_eligibility_id=?",
                        (dispatch_eligibility_id,),
                    ).fetchone()
                    conn.commit()
                    return self._dispatch_eligibility_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionDispatchEligibilityConflict(
                                "dispatch eligibility idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._dispatch_eligibility_row(dict(dup))
                    cur.execute(
                        "SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=%s AND execution_dispatch_id=%s FOR UPDATE",
                        (mission_id, execution_dispatch_id),
                    )
                    if cur.fetchone() is not None:
                        raise MissionDispatchEligibilityConflict(
                            "Stage-3.5.1 execution dispatch already has an immutable Stage-3.5.2 eligibility gate"
                        )
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head = cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_dispatch_contracts WHERE mission_id=%s AND execution_dispatch_id=%s FOR UPDATE", (mission_id, execution_dispatch_id)); dispatch = cur.fetchone()
                    cur.execute("SELECT * FROM mission_task_readiness_projections WHERE mission_id=%s AND projection_id=%s FOR UPDATE", (mission_id, task_readiness_projection_id)); readiness = cur.fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionDispatchEligibilityConflict("Mission state changed before Stage-3.5.2 gate commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                        raise MissionDispatchEligibilityConflict("active Plan head changed before Stage-3.5.2 gate commit")
                    if dispatch is None or dispatch["canonical_sha256"] != src["execution_dispatch_sha256"]:
                        raise MissionDispatchEligibilityConflict("Stage-3.5.1 execution dispatch changed before Stage-3.5.2 gate commit")
                    if readiness is None or readiness["canonical_sha256"] != src["task_readiness_projection_sha256"]:
                        raise MissionDispatchEligibilityConflict("task readiness projection changed before Stage-3.5.2 gate commit")
                    mysql_values = list(values); mysql_values[-1] = self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_execution_dispatch_eligibility_gates
                        (dispatch_eligibility_id,mission_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,task_readiness_projection_id,schema_version,request_sha256,idempotency_key,gate_result,eligibility_status,execution_precondition_status,precondition_count,satisfied_precondition_count,failed_precondition_count,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,created_by,reason,created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        tuple(mysql_values),
                    )
                    cur.execute("SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE dispatch_eligibility_id=%s", (dispatch_eligibility_id,)); row = cur.fetchone()
                conn.commit()
                return self._dispatch_eligibility_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

    @classmethod
    def _pre_dispatch_revalidation_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        contract = row.get("canonical_json")
        if isinstance(contract, str):
            contract = json.loads(contract)
        return {
            "pre_dispatch_revalidation_id": row["pre_dispatch_revalidation_id"],
            "mission_id": row["mission_id"],
            "execution_dispatch_id": row["execution_dispatch_id"],
            "dispatch_eligibility_id": row["dispatch_eligibility_id"],
            "revalidation_sequence": int(row["revalidation_sequence"]),
            "plan_version_record_id": row["plan_version_record_id"],
            "plan_version": int(row["plan_version"]),
            "planned_task_id": row["planned_task_id"],
            "task_key": row["task_key"],
            "schema_version": row["schema_version"],
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "operation_id": row["operation_id"],
            "static_revalidation_status": row["static_revalidation_status"],
            "policy_decision_id": row["policy_decision_id"],
            "policy_decision_hash": row["policy_decision_hash"],
            "governance_decision": row["governance_decision"],
            "policy_version": int(row["policy_version"]),
            "execution_authorization_status": row["execution_authorization_status"],
            "execution_authorized": bool(row["execution_authorized"]),
            "canonical_sha256": row["canonical_sha256"],
            "pre_dispatch_revalidation_contract": contract,
            "source_state": row["source_state"],
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "requested_by": row["requested_by"],
            "reason": row.get("reason"),
            "created_at": cls._iso_from_db(row["created_at"]),
        }

