    def store_execution_attempt(
        self, *, mission_id: str, execution_attempt_id: str, dispatch_envelope_id: str,
        execution_dispatch_id: str, dispatch_eligibility_id: str, pre_dispatch_revalidation_id: str,
        plan_version_record_id: str, plan_version: int, planned_task_id: str, task_key: str,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any],
        expected_state_version: int, source_version_sha256: str, created_by: str,
        reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        src = contract["source_bindings"]
        dispatch_commit = contract["dispatch_commit"]
        attempt = contract["execution_attempt"]
        values = (
            execution_attempt_id, dispatch_envelope_id, mission_id, execution_dispatch_id,
            dispatch_eligibility_id, pre_dispatch_revalidation_id, 1, plan_version_record_id,
            int(plan_version), planned_task_id, task_key, EXECUTION_ATTEMPT_SCHEMA_VERSION,
            request_sha256, idempotency_key, dispatch_commit["dispatch_commit_status"],
            attempt["execution_attempt_status"], src["policy_decision_id"], src["policy_decision_hash"],
            int(src["policy_version"]), contract["canonical_sha256"],
            json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False),
            src["source_state"], int(expected_state_version), source_version_sha256, created_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_execution_attempts WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionExecutionAttemptConflict(
                                "execution attempt idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return self._execution_attempt_row(dict(dup))
                    existing = conn.execute(
                        "SELECT * FROM mission_execution_attempts WHERE mission_id=? AND execution_dispatch_id=?",
                        (mission_id, execution_dispatch_id),
                    ).fetchone()
                    if existing is not None:
                        raise MissionExecutionAttemptConflict(
                            "Stage-3.5.1 execution dispatch already has a canonical initial execution attempt"
                        )
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    dispatch = conn.execute(
                        "SELECT * FROM mission_execution_dispatch_contracts WHERE mission_id=? AND execution_dispatch_id=?",
                        (mission_id, execution_dispatch_id),
                    ).fetchone()
                    eligibility = conn.execute(
                        "SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=? AND dispatch_eligibility_id=?",
                        (mission_id, dispatch_eligibility_id),
                    ).fetchone()
                    revalidation = conn.execute(
                        "SELECT * FROM mission_pre_dispatch_governance_revalidations WHERE mission_id=? AND dispatch_eligibility_id=? ORDER BY revalidation_sequence DESC, id DESC LIMIT 1",
                        (mission_id, dispatch_eligibility_id),
                    ).fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionAttemptConflict("Mission state changed before Stage-3.5.4 dispatch commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                        raise MissionExecutionAttemptConflict("active Plan head changed before Stage-3.5.4 dispatch commit")
                    if dispatch is None or dispatch["canonical_sha256"] != src["execution_dispatch_sha256"]:
                        raise MissionExecutionAttemptConflict("Stage-3.5.1 execution dispatch changed before Stage-3.5.4 dispatch commit")
                    if eligibility is None or eligibility["canonical_sha256"] != src["dispatch_eligibility_sha256"]:
                        raise MissionExecutionAttemptConflict("Stage-3.5.2 dispatch eligibility changed before Stage-3.5.4 dispatch commit")
                    if revalidation is None or revalidation["pre_dispatch_revalidation_id"] != pre_dispatch_revalidation_id or revalidation["canonical_sha256"] != src["pre_dispatch_revalidation_sha256"] or revalidation["governance_decision"] != "ALLOW" or not bool(revalidation["execution_authorized"]):
                        raise MissionExecutionAttemptConflict("latest Stage-3.5.3 execution authorization changed or is not ALLOW before Stage-3.5.4 dispatch commit")
                    conn.execute(
                        """INSERT INTO mission_execution_attempts
                        (execution_attempt_id,dispatch_envelope_id,mission_id,execution_dispatch_id,dispatch_eligibility_id,pre_dispatch_revalidation_id,attempt_ordinal,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,dispatch_commit_status,execution_attempt_status,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,created_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute("SELECT * FROM mission_execution_attempts WHERE execution_attempt_id=?", (execution_attempt_id,)).fetchone()
                    conn.commit()
                    return self._execution_attempt_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_execution_attempts WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionExecutionAttemptConflict("execution attempt idempotency_key was already used with a different canonical request")
                        conn.rollback()
                        return self._execution_attempt_row(dict(dup))
                    cur.execute("SELECT * FROM mission_execution_attempts WHERE mission_id=%s AND execution_dispatch_id=%s FOR UPDATE", (mission_id, execution_dispatch_id)); existing = cur.fetchone()
                    if existing is not None:
                        raise MissionExecutionAttemptConflict("Stage-3.5.1 execution dispatch already has a canonical initial execution attempt")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head = cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_dispatch_contracts WHERE mission_id=%s AND execution_dispatch_id=%s FOR UPDATE", (mission_id, execution_dispatch_id)); dispatch = cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_dispatch_eligibility_gates WHERE mission_id=%s AND dispatch_eligibility_id=%s FOR UPDATE", (mission_id, dispatch_eligibility_id)); eligibility = cur.fetchone()
                    cur.execute("SELECT * FROM mission_pre_dispatch_governance_revalidations WHERE mission_id=%s AND dispatch_eligibility_id=%s ORDER BY revalidation_sequence DESC, id DESC LIMIT 1 FOR UPDATE", (mission_id, dispatch_eligibility_id)); revalidation = cur.fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionAttemptConflict("Mission state changed before Stage-3.5.4 dispatch commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                        raise MissionExecutionAttemptConflict("active Plan head changed before Stage-3.5.4 dispatch commit")
                    if dispatch is None or dispatch["canonical_sha256"] != src["execution_dispatch_sha256"]:
                        raise MissionExecutionAttemptConflict("Stage-3.5.1 execution dispatch changed before Stage-3.5.4 dispatch commit")
                    if eligibility is None or eligibility["canonical_sha256"] != src["dispatch_eligibility_sha256"]:
                        raise MissionExecutionAttemptConflict("Stage-3.5.2 dispatch eligibility changed before Stage-3.5.4 dispatch commit")
                    if revalidation is None or revalidation["pre_dispatch_revalidation_id"] != pre_dispatch_revalidation_id or revalidation["canonical_sha256"] != src["pre_dispatch_revalidation_sha256"] or revalidation["governance_decision"] != "ALLOW" or not bool(revalidation["execution_authorized"]):
                        raise MissionExecutionAttemptConflict("latest Stage-3.5.3 execution authorization changed or is not ALLOW before Stage-3.5.4 dispatch commit")
                    mysql_values = list(values); mysql_values[-1] = self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_execution_attempts
                        (execution_attempt_id,dispatch_envelope_id,mission_id,execution_dispatch_id,dispatch_eligibility_id,pre_dispatch_revalidation_id,attempt_ordinal,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,dispatch_commit_status,execution_attempt_status,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,created_by,reason,created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        tuple(mysql_values),
                    )
                    cur.execute("SELECT * FROM mission_execution_attempts WHERE execution_attempt_id=%s", (execution_attempt_id,)); row = cur.fetchone()
                conn.commit()
                return self._execution_attempt_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

