    def store_execution_delivery(
        self, *, mission_id: str, execution_delivery_id: str, execution_attempt_id: str,
        dispatch_envelope_id: str, execution_dispatch_id: str, plan_version_record_id: str,
        plan_version: int, planned_task_id: str, task_key: str, request_sha256: str,
        idempotency_key: str, contract: Dict[str, Any], expected_state_version: int,
        source_version_sha256: str, delivered_by: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        source = contract["source_bindings"]
        runtime = contract["runtime_binding"]
        delivery = contract["delivery"]
        acknowledgement = contract["acknowledgement"]
        attempt_state = contract["execution_attempt"]
        values = (
            execution_delivery_id, mission_id, execution_attempt_id, dispatch_envelope_id,
            execution_dispatch_id, plan_version_record_id, int(plan_version), planned_task_id, task_key,
            EXECUTION_DELIVERY_SCHEMA_VERSION, request_sha256, idempotency_key,
            delivery["delivery_status"], acknowledgement["acknowledgement_status"],
            attempt_state["execution_attempt_status"], runtime["subsystem_id"], runtime["capability_id"],
            runtime["runtime_endpoint"], runtime["runtime_health_sha256"], acknowledgement["acknowledgement_id"],
            acknowledgement["acknowledgement_sha256"], source["policy_decision_id"], source["policy_decision_hash"],
            int(source["policy_version"]), contract["canonical_sha256"], canonical_json_text,
            source["source_state"], int(source["source_state_version"]), source_version_sha256,
            delivered_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_execution_deliveries WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        row = self._execution_delivery_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionExecutionDeliveryConflict("execution delivery idempotency_key was already used with a different canonical request")
                        conn.rollback()
                        return row
                    existing = conn.execute(
                        "SELECT * FROM mission_execution_deliveries WHERE mission_id=? AND execution_attempt_id=?",
                        (mission_id, execution_attempt_id),
                    ).fetchone()
                    if existing is not None:
                        raise MissionExecutionDeliveryConflict("Stage-3.5.4 execution attempt already has a canonical Stage-3.5.5 delivery acknowledgement")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionDeliveryConflict("Mission state/version changed before execution delivery commit")
                    active = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    if active is None or active["active_plan_version_record_id"] != plan_version_record_id:
                        raise MissionExecutionDeliveryConflict("active Plan head changed before execution delivery commit")
                    attempt = conn.execute(
                        "SELECT * FROM mission_execution_attempts WHERE mission_id=? AND execution_attempt_id=?",
                        (mission_id, execution_attempt_id),
                    ).fetchone()
                    if attempt is None or attempt["canonical_sha256"] != source["execution_attempt_sha256"] or attempt["dispatch_envelope_id"] != dispatch_envelope_id:
                        raise MissionExecutionDeliveryConflict("Stage-3.5.4 execution attempt changed before delivery commit")
                    latest = conn.execute(
                        "SELECT * FROM mission_pre_dispatch_governance_revalidations WHERE mission_id=? AND dispatch_eligibility_id=? ORDER BY id DESC LIMIT 1",
                        (mission_id, attempt["dispatch_eligibility_id"]),
                    ).fetchone()
                    if latest is None or latest["pre_dispatch_revalidation_id"] != attempt["pre_dispatch_revalidation_id"] or latest["governance_decision"] != "ALLOW" or int(latest["execution_authorized"]) != 1:
                        raise MissionExecutionDeliveryConflict("latest pre-dispatch Governance authorization changed before delivery commit")
                    conn.execute(
                        """INSERT INTO mission_execution_deliveries
                        (execution_delivery_id,mission_id,execution_attempt_id,dispatch_envelope_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,delivery_status,acknowledgement_status,execution_attempt_status,recipient_subsystem_id,recipient_capability_id,runtime_endpoint,runtime_health_sha256,acknowledgement_id,acknowledgement_sha256,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,delivered_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute("SELECT * FROM mission_execution_deliveries WHERE execution_delivery_id=?", (execution_delivery_id,)).fetchone()
                    conn.commit()
                    return self._execution_delivery_row(dict(row))
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_execution_deliveries WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        row = self._execution_delivery_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionExecutionDeliveryConflict("execution delivery idempotency_key was already used with a different canonical request")
                        conn.rollback()
                        return row
                    cur.execute("SELECT * FROM mission_execution_deliveries WHERE mission_id=%s AND execution_attempt_id=%s FOR UPDATE", (mission_id, execution_attempt_id))
                    if cur.fetchone() is not None:
                        raise MissionExecutionDeliveryConflict("Stage-3.5.4 execution attempt already has a canonical Stage-3.5.5 delivery acknowledgement")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionDeliveryConflict("Mission state/version changed before execution delivery commit")
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); active = cur.fetchone()
                    if active is None or active["active_plan_version_record_id"] != plan_version_record_id:
                        raise MissionExecutionDeliveryConflict("active Plan head changed before execution delivery commit")
                    cur.execute("SELECT * FROM mission_execution_attempts WHERE mission_id=%s AND execution_attempt_id=%s FOR UPDATE", (mission_id, execution_attempt_id)); attempt = cur.fetchone()
                    if attempt is None or attempt["canonical_sha256"] != source["execution_attempt_sha256"] or attempt["dispatch_envelope_id"] != dispatch_envelope_id:
                        raise MissionExecutionDeliveryConflict("Stage-3.5.4 execution attempt changed before delivery commit")
                    cur.execute("SELECT * FROM mission_pre_dispatch_governance_revalidations WHERE mission_id=%s AND dispatch_eligibility_id=%s ORDER BY id DESC LIMIT 1 FOR UPDATE", (mission_id, attempt["dispatch_eligibility_id"])); latest = cur.fetchone()
                    if latest is None or latest["pre_dispatch_revalidation_id"] != attempt["pre_dispatch_revalidation_id"] or latest["governance_decision"] != "ALLOW" or not bool(latest["execution_authorized"]):
                        raise MissionExecutionDeliveryConflict("latest pre-dispatch Governance authorization changed before delivery commit")
                    mysql_values=list(values); mysql_values[-1]=self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_execution_deliveries
                        (execution_delivery_id,mission_id,execution_attempt_id,dispatch_envelope_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,delivery_status,acknowledgement_status,execution_attempt_status,recipient_subsystem_id,recipient_capability_id,runtime_endpoint,runtime_health_sha256,acknowledgement_id,acknowledgement_sha256,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,delivered_by,reason,created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        tuple(mysql_values),
                    )
                    cur.execute("SELECT * FROM mission_execution_deliveries WHERE execution_delivery_id=%s", (execution_delivery_id,)); row = cur.fetchone()
                conn.commit()
                return self._execution_delivery_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

