    def store_execution_running_projection(
        self, *, mission_id: str, running_projection_id: str, execution_delivery_id: str,
        execution_attempt_id: str, dispatch_envelope_id: str, execution_dispatch_id: str,
        plan_version_record_id: str, plan_version: int, planned_task_id: str, task_key: str,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any],
        expected_state_version: int, source_version_sha256: str, projected_by: str,
        reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        source = contract["source_bindings"]
        runtime = contract["runtime_binding"]
        running = contract["running_state"]
        heartbeat = contract["heartbeat"]
        values = (
            running_projection_id, mission_id, execution_delivery_id, execution_attempt_id,
            dispatch_envelope_id, execution_dispatch_id, plan_version_record_id, int(plan_version),
            planned_task_id, task_key, RUNNING_EXECUTION_SCHEMA_VERSION, request_sha256, idempotency_key,
            running["execution_state"], running["execution_attempt_status"], heartbeat["heartbeat_id"],
            int(heartbeat["heartbeat_sequence"]), heartbeat["heartbeat_at"], heartbeat["heartbeat_status"],
            heartbeat["heartbeat_sha256"], runtime["subsystem_id"], runtime["capability_id"],
            runtime["runtime_endpoint"], runtime["runtime_health_sha256"], source["policy_decision_id"],
            source["policy_decision_hash"], int(source["policy_version"]), contract["canonical_sha256"],
            canonical_json_text, source["source_state"], int(source["source_state_version"]),
            source_version_sha256, projected_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_execution_running_projections WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        row = self._execution_running_projection_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionExecutionRunningProjectionConflict(
                                "running projection idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return row
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionRunningProjectionConflict("Mission state/version changed before RUNNING projection commit")
                    active = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    if active is None or active["active_plan_version_record_id"] != plan_version_record_id or int(active["active_plan_version"]) != int(plan_version) or active["active_plan_sha256"] != source["active_plan_sha256"]:
                        raise MissionExecutionRunningProjectionConflict("active Plan head changed before RUNNING projection commit")
                    delivery = conn.execute(
                        "SELECT * FROM mission_execution_deliveries WHERE mission_id=? AND execution_delivery_id=?",
                        (mission_id, execution_delivery_id),
                    ).fetchone()
                    if delivery is None or delivery["canonical_sha256"] != source["execution_delivery_sha256"] or delivery["execution_attempt_id"] != execution_attempt_id or delivery["dispatch_envelope_id"] != dispatch_envelope_id:
                        raise MissionExecutionRunningProjectionConflict("Stage-3.5.5 execution delivery changed before RUNNING projection commit")
                    attempt = conn.execute(
                        "SELECT * FROM mission_execution_attempts WHERE mission_id=? AND execution_attempt_id=?",
                        (mission_id, execution_attempt_id),
                    ).fetchone()
                    if attempt is None or attempt["canonical_sha256"] != source["execution_attempt_sha256"]:
                        raise MissionExecutionRunningProjectionConflict("Stage-3.5.4 execution attempt changed before RUNNING projection commit")
                    latest = conn.execute(
                        "SELECT * FROM mission_execution_running_projections WHERE mission_id=? AND execution_attempt_id=? ORDER BY heartbeat_sequence DESC, id DESC LIMIT 1",
                        (mission_id, execution_attempt_id),
                    ).fetchone()
                    if latest is not None and int(latest["heartbeat_sequence"]) >= int(heartbeat["heartbeat_sequence"]):
                        raise MissionExecutionRunningProjectionConflict("runtime heartbeat sequence is not newer than the latest durable projection")
                    conn.execute(
                        """INSERT INTO mission_execution_running_projections
                        (running_projection_id,mission_id,execution_delivery_id,execution_attempt_id,dispatch_envelope_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,execution_state,execution_attempt_status,heartbeat_id,heartbeat_sequence,heartbeat_at,heartbeat_status,heartbeat_sha256,recipient_subsystem_id,recipient_capability_id,runtime_endpoint,runtime_health_sha256,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,projected_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute(
                        "SELECT * FROM mission_execution_running_projections WHERE running_projection_id=?",
                        (running_projection_id,),
                    ).fetchone()
                    conn.commit()
                    return self._execution_running_projection_row(dict(row))

                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_execution_running_projections WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        row = self._execution_running_projection_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionExecutionRunningProjectionConflict(
                                "running projection idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return row
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                    if state is None or state["state"] != "RUNNING" or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionRunningProjectionConflict("Mission state/version changed before RUNNING projection commit")
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); active = cur.fetchone()
                    if active is None or active["active_plan_version_record_id"] != plan_version_record_id or int(active["active_plan_version"]) != int(plan_version) or active["active_plan_sha256"] != source["active_plan_sha256"]:
                        raise MissionExecutionRunningProjectionConflict("active Plan head changed before RUNNING projection commit")
                    cur.execute("SELECT * FROM mission_execution_deliveries WHERE mission_id=%s AND execution_delivery_id=%s FOR UPDATE", (mission_id, execution_delivery_id)); delivery = cur.fetchone()
                    if delivery is None or delivery["canonical_sha256"] != source["execution_delivery_sha256"] or delivery["execution_attempt_id"] != execution_attempt_id or delivery["dispatch_envelope_id"] != dispatch_envelope_id:
                        raise MissionExecutionRunningProjectionConflict("Stage-3.5.5 execution delivery changed before RUNNING projection commit")
                    cur.execute("SELECT * FROM mission_execution_attempts WHERE mission_id=%s AND execution_attempt_id=%s FOR UPDATE", (mission_id, execution_attempt_id)); attempt = cur.fetchone()
                    if attempt is None or attempt["canonical_sha256"] != source["execution_attempt_sha256"]:
                        raise MissionExecutionRunningProjectionConflict("Stage-3.5.4 execution attempt changed before RUNNING projection commit")
                    cur.execute("SELECT * FROM mission_execution_running_projections WHERE mission_id=%s AND execution_attempt_id=%s ORDER BY heartbeat_sequence DESC, id DESC LIMIT 1 FOR UPDATE", (mission_id, execution_attempt_id)); latest = cur.fetchone()
                    if latest is not None and int(latest["heartbeat_sequence"]) >= int(heartbeat["heartbeat_sequence"]):
                        raise MissionExecutionRunningProjectionConflict("runtime heartbeat sequence is not newer than the latest durable projection")
                    mysql_values = list(values); mysql_values[-1] = self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_execution_running_projections
                        (running_projection_id,mission_id,execution_delivery_id,execution_attempt_id,dispatch_envelope_id,execution_dispatch_id,plan_version_record_id,plan_version,planned_task_id,task_key,schema_version,request_sha256,idempotency_key,execution_state,execution_attempt_status,heartbeat_id,heartbeat_sequence,heartbeat_at,heartbeat_status,heartbeat_sha256,recipient_subsystem_id,recipient_capability_id,runtime_endpoint,runtime_health_sha256,policy_decision_id,policy_decision_hash,policy_version,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,projected_by,reason,created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        tuple(mysql_values),
                    )
                    cur.execute("SELECT * FROM mission_execution_running_projections WHERE running_projection_id=%s", (running_projection_id,)); row = cur.fetchone()
                conn.commit()
                return self._execution_running_projection_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

