    def get_latest_execution_recovery_checkpoint(self, mission_id: str) -> Optional[Dict[str, Any]]:
        rows = self.list_execution_recovery_checkpoints(mission_id)
        return None if not rows else rows[-1]

    def list_execution_recovery_checkpoints(self, mission_id: str) -> list[Dict[str, Any]]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                rows = conn.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE mission_id=? ORDER BY checkpoint_version ASC, id ASC", (mission_id,)).fetchall()
            else:
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE mission_id=%s ORDER BY checkpoint_version ASC, id ASC", (mission_id,)); rows = cur.fetchall()
            return [self._execution_recovery_checkpoint_row(dict(row)) for row in rows]
        finally:
            conn.close()

    def store_execution_recovery_checkpoint(
        self, *, mission_id: str, checkpoint_id: str, checkpoint_version: int,
        outcome_propagation_id: str, result_capture_id: str, termination_control_id: Optional[str],
        execution_attempt_id: str, plan_version_record_id: str, plan_version: int, planned_task_id: str,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any], expected_state: str,
        expected_state_version: int, source_version_sha256: str, source_event_count: int,
        source_event_tip_sha256: str, expected_mission_event_tip_sha256: str, created_by: str,
        reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        source = contract["source_bindings"]
        values = (
            checkpoint_id, mission_id, int(checkpoint_version), outcome_propagation_id, result_capture_id,
            termination_control_id, execution_attempt_id, plan_version_record_id, int(plan_version), planned_task_id,
            EXECUTION_RECOVERY_CHECKPOINT_SCHEMA_VERSION, request_sha256, idempotency_key,
            contract["integrity"]["canonical_sha256"], canonical_json_value, expected_state,
            int(expected_state_version), source_version_sha256, int(source_event_count), source_event_tip_sha256,
            created_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE mission_id=? AND idempotency_key=?", (mission_id, idempotency_key)).fetchone()
                    if dup is not None:
                        row = self._execution_recovery_checkpoint_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionExecutionRecoveryConflict("execution recovery idempotency_key was already used with a different canonical request")
                        conn.rollback(); return row
                    if conn.execute("SELECT 1 FROM mission_execution_recovery_checkpoints WHERE mission_id=? AND outcome_propagation_id=?", (mission_id, outcome_propagation_id)).fetchone() is not None:
                        raise MissionExecutionRecoveryConflict("Stage-3.5.8 outcome propagation already has an immutable Stage-3.5.9 recovery checkpoint")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    attempt = conn.execute("SELECT * FROM mission_execution_attempts WHERE mission_id=? AND execution_attempt_id=?", (mission_id, execution_attempt_id)).fetchone()
                    delivery = conn.execute("SELECT * FROM mission_execution_deliveries WHERE mission_id=? AND execution_attempt_id=?", (mission_id, execution_attempt_id)).fetchone()
                    running = conn.execute("SELECT * FROM mission_execution_running_projections WHERE mission_id=? AND running_projection_id=?", (mission_id, source["running_projection"]["id"])).fetchone()
                    result = conn.execute("SELECT * FROM mission_execution_result_captures WHERE mission_id=? AND result_capture_id=?", (mission_id, result_capture_id)).fetchone()
                    outcome = conn.execute("SELECT * FROM mission_execution_outcome_propagations WHERE mission_id=? AND outcome_propagation_id=?", (mission_id, outcome_propagation_id)).fetchone()
                    term_count = conn.execute("SELECT COUNT(*) FROM mission_execution_termination_controls WHERE mission_id=? AND execution_attempt_id=?", (mission_id, execution_attempt_id)).fetchone()[0]
                    event_tip = conn.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=? ORDER BY id DESC LIMIT 1", (mission_id,)).fetchone()
                    if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                        raise MissionExecutionRecoveryConflict("Mission state/version changed before execution recovery checkpoint commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan"]["canonical_sha256"]:
                        raise MissionExecutionRecoveryConflict("active Plan head changed before execution recovery checkpoint commit")
                    checks = ((attempt,"execution_attempt"),(delivery,"execution_delivery"),(running,"running_projection"),(result,"result_capture"),(outcome,"outcome_propagation"))
                    if any(row is None or row["canonical_sha256"] != source[key]["canonical_sha256"] for row,key in checks):
                        raise MissionExecutionRecoveryConflict("execution source artifact changed before recovery checkpoint commit")
                    if int(term_count) != int(source["termination_control_count"]):
                        raise MissionExecutionRecoveryConflict("Stage-3.5.8 termination-control count changed before recovery checkpoint commit")
                    if termination_control_id is not None:
                        term = conn.execute("SELECT * FROM mission_execution_termination_controls WHERE mission_id=? AND termination_control_id=?", (mission_id, termination_control_id)).fetchone()
                        if term is None or term["canonical_sha256"] != source["termination_control"]["canonical_sha256"]:
                            raise MissionExecutionRecoveryConflict("Stage-3.5.8 termination-control artifact changed before recovery checkpoint commit")
                    if event_tip is None or event_tip["canonical_sha256"] != expected_mission_event_tip_sha256:
                        raise MissionExecutionRecoveryConflict("Mission event tip changed before execution recovery checkpoint commit")
                    conn.execute("""INSERT INTO mission_execution_recovery_checkpoints
                        (checkpoint_id,mission_id,checkpoint_version,outcome_propagation_id,result_capture_id,termination_control_id,execution_attempt_id,plan_version_record_id,plan_version,planned_task_id,schema_version,request_sha256,idempotency_key,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,source_event_count,source_event_tip_sha256,created_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", values)
                    row = conn.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE checkpoint_id=?", (checkpoint_id,)).fetchone()
                    conn.commit(); return self._execution_recovery_checkpoint_row(dict(row))
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup=cur.fetchone()
                    if dup is not None:
                        row=self._execution_recovery_checkpoint_row(dict(dup))
                        if row["request_sha256"] != request_sha256: raise MissionExecutionRecoveryConflict("execution recovery idempotency_key was already used with a different canonical request")
                        conn.rollback(); return row
                    cur.execute("SELECT 1 FROM mission_execution_recovery_checkpoints WHERE mission_id=%s AND outcome_propagation_id=%s FOR UPDATE", (mission_id, outcome_propagation_id))
                    if cur.fetchone() is not None: raise MissionExecutionRecoveryConflict("Stage-3.5.8 outcome propagation already has an immutable Stage-3.5.9 recovery checkpoint")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head=cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_attempts WHERE mission_id=%s AND execution_attempt_id=%s FOR UPDATE", (mission_id, execution_attempt_id)); attempt=cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_deliveries WHERE mission_id=%s AND execution_attempt_id=%s FOR UPDATE", (mission_id, execution_attempt_id)); delivery=cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_running_projections WHERE mission_id=%s AND running_projection_id=%s FOR UPDATE", (mission_id, source["running_projection"]["id"])); running=cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_result_captures WHERE mission_id=%s AND result_capture_id=%s FOR UPDATE", (mission_id, result_capture_id)); result=cur.fetchone()
                    cur.execute("SELECT * FROM mission_execution_outcome_propagations WHERE mission_id=%s AND outcome_propagation_id=%s FOR UPDATE", (mission_id, outcome_propagation_id)); outcome=cur.fetchone()
                    cur.execute("SELECT COUNT(*) AS n FROM mission_execution_termination_controls WHERE mission_id=%s AND execution_attempt_id=%s", (mission_id, execution_attempt_id)); term_count=int(cur.fetchone()["n"])
                    cur.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=%s ORDER BY id DESC LIMIT 1 FOR UPDATE", (mission_id,)); event_tip=cur.fetchone()
                    if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version): raise MissionExecutionRecoveryConflict("Mission state/version changed before execution recovery checkpoint commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan"]["canonical_sha256"]: raise MissionExecutionRecoveryConflict("active Plan head changed before execution recovery checkpoint commit")
                    checks=((attempt,"execution_attempt"),(delivery,"execution_delivery"),(running,"running_projection"),(result,"result_capture"),(outcome,"outcome_propagation"))
                    if any(row is None or row["canonical_sha256"] != source[key]["canonical_sha256"] for row,key in checks): raise MissionExecutionRecoveryConflict("execution source artifact changed before recovery checkpoint commit")
                    if term_count != int(source["termination_control_count"]): raise MissionExecutionRecoveryConflict("Stage-3.5.8 termination-control count changed before recovery checkpoint commit")
                    if termination_control_id is not None:
                        cur.execute("SELECT * FROM mission_execution_termination_controls WHERE mission_id=%s AND termination_control_id=%s FOR UPDATE", (mission_id, termination_control_id)); term=cur.fetchone()
                        if term is None or term["canonical_sha256"] != source["termination_control"]["canonical_sha256"]: raise MissionExecutionRecoveryConflict("Stage-3.5.8 termination-control artifact changed before recovery checkpoint commit")
                    if event_tip is None or event_tip["canonical_sha256"] != expected_mission_event_tip_sha256: raise MissionExecutionRecoveryConflict("Mission event tip changed before execution recovery checkpoint commit")
                    mysql_values=list(values); mysql_values[-1]=self._mysql_dt(created_at)
                    cur.execute("""INSERT INTO mission_execution_recovery_checkpoints
                        (checkpoint_id,mission_id,checkpoint_version,outcome_propagation_id,result_capture_id,termination_control_id,execution_attempt_id,plan_version_record_id,plan_version,planned_task_id,schema_version,request_sha256,idempotency_key,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,source_event_count,source_event_tip_sha256,created_by,reason,created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", tuple(mysql_values))
                    cur.execute("SELECT * FROM mission_execution_recovery_checkpoints WHERE checkpoint_id=%s", (checkpoint_id,)); row=cur.fetchone()
                conn.commit(); return self._execution_recovery_checkpoint_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

