    def store_planning_recovery_checkpoint(
        self, *, mission_id: str, checkpoint_id: str, checkpoint_version: int,
        plan_version_record_id: str, plan_version: int, request_sha256: str, idempotency_key: str,
        recovery_checkpoint: Dict[str, Any], expected_state_version: int, source_version_sha256: str,
        source_event_count: int, source_event_tip_sha256: str, readiness_projection_id: str,
        readiness_projection_sha256: str, expected_active_plan_sha256: str, expected_mission_event_tip_sha256: str,
        actor: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(recovery_checkpoint, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        canonical_sha = recovery_checkpoint["integrity"]["canonical_sha256"]
        values = (
            checkpoint_id, mission_id, int(checkpoint_version), plan_version_record_id, int(plan_version),
            PLANNING_RECOVERY_CHECKPOINT_SCHEMA_VERSION, request_sha256, idempotency_key, canonical_sha,
            canonical_json_value, int(expected_state_version), source_version_sha256, int(source_event_count),
            source_event_tip_sha256, readiness_projection_id, readiness_projection_sha256, actor, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    if conn.execute("SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)).fetchone() is None:
                        raise MissionNotFound(mission_id)
                    dup = conn.execute(
                        "SELECT * FROM mission_planning_recovery_checkpoints WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionPlanningRecoveryConflict("planning recovery idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._planning_recovery_checkpoint_row(dict(dup))
                    if conn.execute(
                        "SELECT 1 FROM mission_planning_recovery_checkpoints WHERE mission_id=? AND plan_version=?",
                        (mission_id, int(plan_version)),
                    ).fetchone() is not None:
                        raise MissionPlanningRecoveryConflict("active Plan version already has an immutable Stage-3.3.9 planning recovery checkpoint")
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    readiness = conn.execute("SELECT * FROM mission_task_readiness_projections WHERE projection_id=? AND mission_id=?", (readiness_projection_id, mission_id)).fetchone()
                    event_count = conn.execute("SELECT COUNT(*) FROM mission_events WHERE mission_id=?", (mission_id,)).fetchone()[0]
                    event_tip = conn.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=? ORDER BY id DESC LIMIT 1", (mission_id,)).fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionPlanningRecoveryConflict("Mission state changed before planning recovery checkpoint commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionPlanningRecoveryConflict("active Plan head changed before planning recovery checkpoint commit")
                    if readiness is None or readiness["canonical_sha256"] != readiness_projection_sha256:
                        raise MissionPlanningRecoveryConflict("task-readiness projection changed before planning recovery checkpoint commit")
                    # The source planning event count is a planning-subchain count, so only the full-chain tip is CAS-checked here.
                    if event_tip is None or event_tip["canonical_sha256"] != expected_mission_event_tip_sha256:
                        raise MissionPlanningRecoveryConflict("Mission event tip changed before planning recovery checkpoint commit")
                    conn.execute(
                        """INSERT INTO mission_planning_recovery_checkpoints
                        (checkpoint_id, mission_id, checkpoint_version, plan_version_record_id, plan_version, schema_version,
                         request_sha256, idempotency_key, canonical_sha256, canonical_json, source_state_version,
                         source_version_sha256, source_event_count, source_event_tip_sha256, readiness_projection_id,
                         readiness_projection_sha256, created_by, reason, created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", values)
                    row = conn.execute("SELECT * FROM mission_planning_recovery_checkpoints WHERE checkpoint_id=?", (checkpoint_id,)).fetchone()
                    conn.commit(); return self._planning_recovery_checkpoint_row(dict(row))
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None: raise MissionNotFound(mission_id)
                    cur.execute("SELECT * FROM mission_planning_recovery_checkpoints WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup=cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionPlanningRecoveryConflict("planning recovery idempotency_key was already used with a different canonical request")
                        conn.rollback(); return self._planning_recovery_checkpoint_row(dict(dup))
                    cur.execute("SELECT 1 FROM mission_planning_recovery_checkpoints WHERE mission_id=%s AND plan_version=%s FOR UPDATE", (mission_id, int(plan_version)))
                    if cur.fetchone() is not None: raise MissionPlanningRecoveryConflict("active Plan version already has an immutable Stage-3.3.9 planning recovery checkpoint")
                    cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state=cur.fetchone()
                    cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head=cur.fetchone()
                    cur.execute("SELECT * FROM mission_task_readiness_projections WHERE projection_id=%s AND mission_id=%s FOR UPDATE", (readiness_projection_id, mission_id)); readiness=cur.fetchone()
                    cur.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=%s ORDER BY id DESC LIMIT 1 FOR UPDATE", (mission_id,)); event_tip=cur.fetchone()
                    if state is None or state["state"] not in {"PLANNING", "REPLANNING"} or int(state["state_version"]) != int(expected_state_version):
                        raise MissionPlanningRecoveryConflict("Mission state changed before planning recovery checkpoint commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != expected_active_plan_sha256:
                        raise MissionPlanningRecoveryConflict("active Plan head changed before planning recovery checkpoint commit")
                    if readiness is None or readiness["canonical_sha256"] != readiness_projection_sha256:
                        raise MissionPlanningRecoveryConflict("task-readiness projection changed before planning recovery checkpoint commit")
                    if event_tip is None or event_tip["canonical_sha256"] != expected_mission_event_tip_sha256:
                        raise MissionPlanningRecoveryConflict("Mission event tip changed before planning recovery checkpoint commit")
                    mysql_values=list(values); mysql_values[-1]=self._mysql_dt(created_at)
                    cur.execute(
                        """INSERT INTO mission_planning_recovery_checkpoints
                        (checkpoint_id, mission_id, checkpoint_version, plan_version_record_id, plan_version, schema_version,
                         request_sha256, idempotency_key, canonical_sha256, canonical_json, source_state_version,
                         source_version_sha256, source_event_count, source_event_tip_sha256, readiness_projection_id,
                         readiness_projection_sha256, created_by, reason, created_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", tuple(mysql_values))
                    cur.execute("SELECT * FROM mission_planning_recovery_checkpoints WHERE checkpoint_id=%s", (checkpoint_id,)); row=cur.fetchone()
                conn.commit(); return self._planning_recovery_checkpoint_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

    @classmethod
    def _mission_event_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        payload = row.get("payload_json")
        if isinstance(payload, str):
            payload = json.loads(payload or "{}")
        out = {
            "schema_version": row["schema_version"],
            "event_id": row["event_id"],
            "mission_id": row["mission_id"],
            "trace_id": row["trace_id"],
            "correlation_id": row["correlation_id"],
            "causation_id": row.get("causation_id"),
            "parent_event_id": row.get("parent_event_id"),
            "source_component": row["source_component"],
            "event_type": row["event_type"],
            "state_version": None if row.get("state_version") is None else int(row["state_version"]),
            "plan_version": row.get("plan_version"),
            "policy_version": row.get("policy_version"),
            "payload": payload or {},
            "previous_event_sha256": row.get("previous_event_sha256"),
            "canonical_sha256": row["canonical_sha256"],
            "occurred_at": cls._iso_from_db(row["occurred_at"]),
            "recorded_at": cls._iso_from_db(row["recorded_at"]),
        }
        return out

    def append_mission_event(self, event_hook: Dict[str, Any]) -> tuple[Dict[str, Any], bool]:
        mission_id = str(event_hook["mission_id"])
        event_type = str(event_hook["event_type"]).upper()
        causation_id = str(event_hook["causation_id"])
        payload_json = json.dumps(event_hook.get("payload") or {}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

        if self.driver == "sqlite":
            with self._lock, self._connect() as conn:
                conn.execute("BEGIN IMMEDIATE")
                mission = conn.execute(
                    "SELECT mission_id FROM global_missions WHERE mission_id=?", (mission_id,)
                ).fetchone()
                if mission is None:
                    conn.rollback()
                    raise MissionNotFound(mission_id)
                duplicate = conn.execute(
                    "SELECT * FROM mission_events WHERE mission_id=? AND event_type=? AND causation_id=?",
                    (mission_id, event_type, causation_id),
                ).fetchone()
                if duplicate is not None:
                    conn.rollback()
                    return self._mission_event_row(dict(duplicate)), True
                previous_row = conn.execute(
                    "SELECT * FROM mission_events WHERE mission_id=? ORDER BY id DESC LIMIT 1", (mission_id,)
                ).fetchone()
                previous = None if previous_row is None else self._mission_event_row(dict(previous_row))
                event = build_event_record(
                    event_id=event_hook["event_id"],
                    mission_id=mission_id,
                    correlation_id=event_hook["correlation_id"],
                    event_type=event_type,
                    payload=event_hook.get("payload") or {},
                    occurred_at=event_hook["occurred_at"],
                    previous_event=previous,
                    source_component=event_hook.get("source_component") or "APTS-MO01",
                    state_version=event_hook.get("state_version"),
                    plan_version=event_hook.get("plan_version"),
                    policy_version=event_hook.get("policy_version"),
                    parent_event_id=event_hook.get("parent_event_id"),
                    causation_id=causation_id,
                )
                conn.execute(
                    """INSERT INTO mission_events
                    (event_id, mission_id, schema_version, trace_id, correlation_id, causation_id,
                     parent_event_id, source_component, event_type, state_version, plan_version, policy_version,
                     payload_json, previous_event_sha256, canonical_sha256, occurred_at, recorded_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        event["event_id"], event["mission_id"], event["schema_version"], event["trace_id"],
                        event["correlation_id"], event["causation_id"], event["parent_event_id"],
                        event["source_component"], event["event_type"], event["state_version"],
                        None if event["plan_version"] is None else str(event["plan_version"]),
                        None if event["policy_version"] is None else str(event["policy_version"]),
                        payload_json, event["previous_event_sha256"], event["canonical_sha256"],
                        event["occurred_at"], event["occurred_at"],
                    ),
                )
                row = conn.execute("SELECT * FROM mission_events WHERE event_id=?", (event["event_id"],)).fetchone()
                conn.commit()
                return self._mission_event_row(dict(row)), False

        with self._lock:
            conn = self._connect()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT mission_id FROM global_missions WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    if cur.fetchone() is None:
                        raise MissionNotFound(mission_id)
                    cur.execute(
                        "SELECT * FROM mission_events WHERE mission_id=%s AND event_type=%s AND causation_id=%s FOR UPDATE",
                        (mission_id, event_type, causation_id),
                    )
                    duplicate = cur.fetchone()
                    if duplicate is not None:
                        conn.rollback()
                        return self._mission_event_row(duplicate), True
                    cur.execute(
                        "SELECT * FROM mission_events WHERE mission_id=%s ORDER BY id DESC LIMIT 1 FOR UPDATE",
                        (mission_id,),
                    )
                    previous_row = cur.fetchone()
                    previous = None if previous_row is None else self._mission_event_row(previous_row)
                    event = build_event_record(
                        event_id=event_hook["event_id"],
                        mission_id=mission_id,
                        correlation_id=event_hook["correlation_id"],
                        event_type=event_type,
                        payload=event_hook.get("payload") or {},
                        occurred_at=event_hook["occurred_at"],
                        previous_event=previous,
                        source_component=event_hook.get("source_component") or "APTS-MO01",
                        state_version=event_hook.get("state_version"),
                        plan_version=event_hook.get("plan_version"),
                        policy_version=event_hook.get("policy_version"),
                        parent_event_id=event_hook.get("parent_event_id"),
                        causation_id=causation_id,
                    )
                    cur.execute(
                        """INSERT INTO mission_events
                        (event_id, mission_id, schema_version, trace_id, correlation_id, causation_id,
                         parent_event_id, source_component, event_type, state_version, plan_version, policy_version,
                         payload_json, previous_event_sha256, canonical_sha256, occurred_at, recorded_at)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                        (
                            event["event_id"], event["mission_id"], event["schema_version"], event["trace_id"],
                            event["correlation_id"], event["causation_id"], event["parent_event_id"],
                            event["source_component"], event["event_type"], event["state_version"],
                            None if event["plan_version"] is None else str(event["plan_version"]),
                            None if event["policy_version"] is None else str(event["policy_version"]),
                            payload_json, event["previous_event_sha256"], event["canonical_sha256"],
                            self._mysql_dt(event["occurred_at"]), self._mysql_dt(event["occurred_at"]),
                        ),
                    )
                    cur.execute("SELECT * FROM mission_events WHERE event_id=%s", (event["event_id"],))
                    row = cur.fetchone()
                conn.commit()
                return self._mission_event_row(row), False
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()

