    def store_task_outcome(
        self, *, mission_id: str, task_outcome_id: str, plan_version_record_id: str,
        plan_version: int, planned_task_id: str, task_key: str, execution_attempt_id: str,
        result_capture_id: str, outcome_propagation_id: str, execution_recovery_checkpoint_id: str,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any], expected_state: str,
        expected_state_version: int, source_version_sha256: str, created_by: str,
        reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        src = contract["source_bindings"]
        outcome = contract["task_outcome"]
        values = (
            task_outcome_id, mission_id, plan_version_record_id, int(plan_version), planned_task_id, task_key,
            execution_attempt_id, result_capture_id, outcome_propagation_id, execution_recovery_checkpoint_id,
            TASK_OUTCOME_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key, outcome["contract_status"],
            outcome["execution_state"], outcome["source_task_outcome_status"], outcome["outcome_classification"],
            src["result_capture_sha256"], src["outcome_propagation_sha256"], src["execution_recovery_checkpoint_sha256"],
            contract["canonical_sha256"], canonical_json_value, expected_state, int(expected_state_version),
            source_version_sha256, created_by, reason, created_at,
        )
        with self._lock:
            conn = self._connect()
