    def store_task_terminality_eligibility(
        self, *, mission_id: str, eligibility_gate_id: str, plan_version_record_id: str,
        plan_version: int, planned_task_id: str, task_key: str, task_outcome_id: str,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any],
        expected_state: str, expected_state_version: int, source_version_sha256: str,
        evaluated_by: str, reason: Optional[str], evaluated_at: str,
    ) -> Dict[str, Any]:
        canonical_json_value = json.dumps(
            contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
        )
        terminality = contract["terminality"]
        eligibility = contract["completion_eligibility"]
        source = contract["source_bindings"]
        values = (
            eligibility_gate_id, mission_id, plan_version_record_id, int(plan_version), planned_task_id,
            task_key, task_outcome_id, TASK_TERMINALITY_CONTRACT_SCHEMA_VERSION, request_sha256,
            idempotency_key, terminality["gate_status"], int(bool(terminality["terminality_confirmed"])),
            terminality["terminality_status"], eligibility["completion_eligibility_status"],
            int(bool(eligibility["completion_eligible"])), eligibility["eligibility_reason_code"],
            source["task_outcome_sha256"], contract["canonical_sha256"], canonical_json_value,
            expected_state, int(expected_state_version), source_version_sha256, evaluated_by, reason, evaluated_at,
        )
