    def store_task_evidence_binding_verification(
        self, *, mission_id: str, verification_id: str, plan_version_record_id: str,
        plan_version: int, planned_task_id: str, task_key: str, task_outcome_id: str,
        eligibility_gate_id: str, result_capture_id: str, request_sha256: str,
        idempotency_key: str, contract: Dict[str, Any], expected_state: str,
        expected_state_version: int, source_version_sha256: str, verified_by: str,
        reason: Optional[str], verified_at: str,
    ) -> Dict[str, Any]:
        verification = contract["evidence_binding_verification"]
        source = contract["source_bindings"]
        canonical_json_value = json.dumps(
            contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
        )
        values = (
            verification_id, mission_id, plan_version_record_id, int(plan_version), planned_task_id,
            task_key, task_outcome_id, eligibility_gate_id, result_capture_id,
            TASK_EVIDENCE_BINDING_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key,
            verification["verification_status"], int(bool(verification["evidence_binding_verified"])),
            int(bool(verification["artifact_binding_verified"])), int(verification["evidence_reference_count"]),
            int(verification["artifact_reference_count"]), verification["evidence_manifest_sha256"],
            verification["artifact_manifest_sha256"], source["task_outcome_sha256"],
            source["eligibility_gate_sha256"], source["result_capture_sha256"], contract["canonical_sha256"],
            canonical_json_value, source["source_state"], int(expected_state_version), source_version_sha256,
            verified_by, reason, verified_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_task_evidence_binding_verifications WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        row = self._task_evidence_binding_verification_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionTaskEvidenceBindingConflict(
                                "task evidence-binding verification idempotency_key was already used with a different canonical request"
                            )
                        conn.rollback()
                        return row
                    if conn.execute(
                        "SELECT 1 FROM mission_task_evidence_binding_verifications WHERE mission_id=? AND eligibility_gate_id=?",
                        (mission_id, eligibility_gate_id),
                    ).fetchone() is not None:
                        raise MissionTaskEvidenceBindingConflict(
                            "Stage-3.6.2 eligibility gate already has an immutable Stage-3.6.3 evidence-binding verification"
                        )
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    outcome = conn.execute(
                        "SELECT * FROM mission_task_outcomes WHERE mission_id=? AND task_outcome_id=?", (mission_id, task_outcome_id)
                    ).fetchone()
                    gate = conn.execute(
                        "SELECT * FROM mission_task_terminality_eligibility_gates WHERE mission_id=? AND eligibility_gate_id=?", (mission_id, eligibility_gate_id)
                    ).fetchone()
                    result = conn.execute(
                        "SELECT * FROM mission_execution_result_captures WHERE mission_id=? AND result_capture_id=?", (mission_id, result_capture_id)
                    ).fetchone()
                    if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                        raise MissionTaskEvidenceBindingConflict("Mission state/version changed before task evidence-binding verification commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan_sha256"]:
                        raise MissionTaskEvidenceBindingConflict("active Plan head changed before task evidence-binding verification commit")
                    if outcome is None or outcome["canonical_sha256"] != source["task_outcome_sha256"]:
                        raise MissionTaskEvidenceBindingConflict("Stage-3.6.1 task outcome changed before task evidence-binding verification commit")
                    if gate is None or gate["canonical_sha256"] != source["eligibility_gate_sha256"]:
                        raise MissionTaskEvidenceBindingConflict("Stage-3.6.2 eligibility gate changed before task evidence-binding verification commit")
                    if result is None or result["canonical_sha256"] != source["result_capture_sha256"]:
                        raise MissionTaskEvidenceBindingConflict("Stage-3.5.7 result capture changed before task evidence-binding verification commit")
                    conn.execute(
                        """INSERT INTO mission_task_evidence_binding_verifications
                        (verification_id,mission_id,plan_version_record_id,plan_version,planned_task_id,task_key,task_outcome_id,eligibility_gate_id,result_capture_id,schema_version,request_sha256,idempotency_key,verification_status,evidence_binding_verified,artifact_binding_verified,evidence_reference_count,artifact_reference_count,evidence_manifest_sha256,artifact_manifest_sha256,task_outcome_sha256,eligibility_gate_sha256,result_capture_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,verified_by,reason,verified_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute(
                        "SELECT * FROM mission_task_evidence_binding_verifications WHERE verification_id=?", (verification_id,)
                    ).fetchone()
                else:
                    with conn.cursor() as cur:
                        cur.execute(
                            "SELECT * FROM mission_task_evidence_binding_verifications WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                            (mission_id, idempotency_key),
                        )
                        dup = cur.fetchone()
                        if dup is not None:
                            row = self._task_evidence_binding_verification_row(dict(dup))
                            if row["request_sha256"] != request_sha256:
                                raise MissionTaskEvidenceBindingConflict(
                                    "task evidence-binding verification idempotency_key was already used with a different canonical request"
                                )
                            conn.rollback()
                            return row
                        cur.execute(
                            "SELECT 1 FROM mission_task_evidence_binding_verifications WHERE mission_id=%s AND eligibility_gate_id=%s FOR UPDATE",
                            (mission_id, eligibility_gate_id),
                        )
                        if cur.fetchone() is not None:
                            raise MissionTaskEvidenceBindingConflict(
                                "Stage-3.6.2 eligibility gate already has an immutable Stage-3.6.3 evidence-binding verification"
                            )
                        cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                        cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head = cur.fetchone()
                        cur.execute("SELECT * FROM mission_task_outcomes WHERE mission_id=%s AND task_outcome_id=%s FOR UPDATE", (mission_id, task_outcome_id)); outcome = cur.fetchone()
                        cur.execute("SELECT * FROM mission_task_terminality_eligibility_gates WHERE mission_id=%s AND eligibility_gate_id=%s FOR UPDATE", (mission_id, eligibility_gate_id)); gate = cur.fetchone()
                        cur.execute("SELECT * FROM mission_execution_result_captures WHERE mission_id=%s AND result_capture_id=%s FOR UPDATE", (mission_id, result_capture_id)); result = cur.fetchone()
                        if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                            raise MissionTaskEvidenceBindingConflict("Mission state/version changed before task evidence-binding verification commit")
                        if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != source["active_plan_sha256"]:
                            raise MissionTaskEvidenceBindingConflict("active Plan head changed before task evidence-binding verification commit")
                        if outcome is None or outcome["canonical_sha256"] != source["task_outcome_sha256"]:
                            raise MissionTaskEvidenceBindingConflict("Stage-3.6.1 task outcome changed before task evidence-binding verification commit")
                        if gate is None or gate["canonical_sha256"] != source["eligibility_gate_sha256"]:
                            raise MissionTaskEvidenceBindingConflict("Stage-3.6.2 eligibility gate changed before task evidence-binding verification commit")
                        if result is None or result["canonical_sha256"] != source["result_capture_sha256"]:
                            raise MissionTaskEvidenceBindingConflict("Stage-3.5.7 result capture changed before task evidence-binding verification commit")
                        mysql_values = list(values)
                        mysql_values[-1] = self._mysql_dt(verified_at)
                        cur.execute(
                            """INSERT INTO mission_task_evidence_binding_verifications
                            (verification_id,mission_id,plan_version_record_id,plan_version,planned_task_id,task_key,task_outcome_id,eligibility_gate_id,result_capture_id,schema_version,request_sha256,idempotency_key,verification_status,evidence_binding_verified,artifact_binding_verified,evidence_reference_count,artifact_reference_count,evidence_manifest_sha256,artifact_manifest_sha256,task_outcome_sha256,eligibility_gate_sha256,result_capture_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,verified_by,reason,verified_at)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                            tuple(mysql_values),
                        )
                        cur.execute("SELECT * FROM mission_task_evidence_binding_verifications WHERE verification_id=%s", (verification_id,)); row = cur.fetchone()
                conn.commit()
                return self._task_evidence_binding_verification_row(dict(row))
            except Exception:
                conn.rollback()
                raise
            finally:
                conn.close()


    @classmethod
    def _task_completion_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        contract = row.get("canonical_json")
        if isinstance(contract, str):
            contract = json.loads(contract)
        return {
            "task_completion_id": row["task_completion_id"],
            "mission_id": row["mission_id"],
            "plan_version_record_id": row["plan_version_record_id"],
            "plan_version": int(row["plan_version"]),
            "planned_task_id": row["planned_task_id"],
            "task_key": row["task_key"],
            "evidence_binding_verification_id": row["evidence_binding_verification_id"],
            "task_outcome_id": row["task_outcome_id"],
            "eligibility_gate_id": row["eligibility_gate_id"],
            "schema_version": row["schema_version"],
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "completion_status": row["completion_status"],
            "task_outcome_accepted": bool(row["task_outcome_accepted"]),
            "task_completion_committed": bool(row["task_completion_committed"]),
            "dependency_status": row["dependency_status"],
            "dependency_count": int(row["dependency_count"]),
            "completed_dependency_count": int(row["completed_dependency_count"]),
            "dependency_binding_sha256": row["dependency_binding_sha256"],
            "evidence_binding_verification_sha256": row["evidence_binding_verification_sha256"],
            "canonical_sha256": row["canonical_sha256"],
            "task_completion_contract": contract,
            "source_state": row["source_state"],
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "completed_by": row["completed_by"],
            "reason": row.get("reason"),
            "committed_at": cls._iso_from_db(row["committed_at"]),
        }

