    def store_mission_outcome_aggregation(
        self, *, mission_id: str, aggregation_id: str, plan_version_record_id: str, plan_version: int,
        request_sha256: str, idempotency_key: str, contract: Dict[str, Any], expected_state: str,
        expected_state_version: int, source_version_sha256: str, aggregated_by: str,
        reason: Optional[str], aggregated_at: str,
    ) -> Dict[str, Any]:
        agg = contract["mission_outcome_aggregation"]
        src = contract["source_bindings"]
        canonical_json_text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        values = (
            aggregation_id, mission_id, plan_version_record_id, int(plan_version),
            MISSION_OUTCOME_AGGREGATION_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key,
            agg["aggregation_status"], int(agg["task_count"]), int(agg["terminal_task_count"]),
            int(agg["verified_complete_count"]), int(agg["failed_count"]), int(agg["cancelled_count"]),
            int(agg["timed_out_count"]), int(agg["running_count"]), int(agg["blocked_count"]), int(agg["pending_count"]),
            int(bool(agg["all_tasks_terminal"])), int(bool(agg["all_tasks_verified_complete"])),
            agg["source_snapshot_sha256"], contract["canonical_sha256"], canonical_json_text,
            src["source_state"], int(expected_state_version), source_version_sha256, aggregated_by, reason, aggregated_at,
        )
        with self._lock:
            conn = self._connect()
            try:
                if self.driver == "sqlite":
                    conn.execute("BEGIN IMMEDIATE")
                    dup = conn.execute(
                        "SELECT * FROM mission_outcome_aggregations WHERE mission_id=? AND idempotency_key=?",
                        (mission_id, idempotency_key),
                    ).fetchone()
                    if dup is not None:
                        row = self._mission_outcome_aggregation_row(dict(dup))
                        if row["request_sha256"] != request_sha256:
                            raise MissionOutcomeAggregationConflict("mission outcome aggregation idempotency_key conflict")
                        conn.commit(); return row
                    state = conn.execute("SELECT * FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                    head = conn.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                    if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                        raise MissionOutcomeAggregationConflict("Mission state/version changed before Stage-3.6.5 aggregation commit")
                    if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                        raise MissionOutcomeAggregationConflict("active Plan head changed before Stage-3.6.5 aggregation commit")
                    conn.execute(
                        """INSERT INTO mission_outcome_aggregations
                        (aggregation_id,mission_id,plan_version_record_id,plan_version,schema_version,request_sha256,idempotency_key,aggregation_status,task_count,terminal_task_count,verified_complete_count,failed_count,cancelled_count,timed_out_count,running_count,blocked_count,pending_count,all_tasks_terminal,all_tasks_verified_complete,source_snapshot_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,aggregated_by,reason,aggregated_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        values,
                    )
                    row = conn.execute("SELECT * FROM mission_outcome_aggregations WHERE aggregation_id=?", (aggregation_id,)).fetchone()
                else:
                    with conn.cursor() as cur:
                        cur.execute("SELECT * FROM mission_outcome_aggregations WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup = cur.fetchone()
                        if dup is not None:
                            row = self._mission_outcome_aggregation_row(dict(dup))
                            if row["request_sha256"] != request_sha256:
                                raise MissionOutcomeAggregationConflict("mission outcome aggregation idempotency_key conflict")
                            conn.commit(); return row
                        cur.execute("SELECT * FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                        cur.execute("SELECT * FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head = cur.fetchone()
                        if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                            raise MissionOutcomeAggregationConflict("Mission state/version changed before Stage-3.6.5 aggregation commit")
                        if head is None or head["active_plan_version_record_id"] != plan_version_record_id or int(head["active_plan_version"]) != int(plan_version) or head["active_plan_sha256"] != src["active_plan_sha256"]:
                            raise MissionOutcomeAggregationConflict("active Plan head changed before Stage-3.6.5 aggregation commit")
                        mysql_values=list(values); mysql_values[-1]=self._mysql_dt(aggregated_at)
                        cur.execute(
                            """INSERT INTO mission_outcome_aggregations
                            (aggregation_id,mission_id,plan_version_record_id,plan_version,schema_version,request_sha256,idempotency_key,aggregation_status,task_count,terminal_task_count,verified_complete_count,failed_count,cancelled_count,timed_out_count,running_count,blocked_count,pending_count,all_tasks_terminal,all_tasks_verified_complete,source_snapshot_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,aggregated_by,reason,aggregated_at)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                            tuple(mysql_values),
                        )
                        cur.execute("SELECT * FROM mission_outcome_aggregations WHERE aggregation_id=%s", (aggregation_id,)); row = cur.fetchone()
                conn.commit()
                return self._mission_outcome_aggregation_row(dict(row))
            except Exception:
                conn.rollback(); raise
            finally:
                conn.close()

