    def store_outcome_recovery_checkpoint(
        self, *, mission_id: str, checkpoint_id: str, checkpoint_version: int, declaration_id: str,
        plan_version_record_id: str, plan_version: int, request_sha256: str, idempotency_key: str,
        contract: Dict[str, Any], source_state: str, source_state_version: int, source_version_sha256: str,
        source_event_count: int, source_event_tip_sha256: str, created_by: str, reason: Optional[str], created_at: str,
    ) -> Dict[str, Any]:
        text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        values = (
            checkpoint_id, mission_id, int(checkpoint_version), declaration_id, plan_version_record_id, int(plan_version),
            OUTCOME_RECOVERY_CHECKPOINT_SCHEMA_VERSION, request_sha256, idempotency_key, contract["integrity"]["canonical_sha256"],
            text, source_state, int(source_state_version), source_version_sha256, int(source_event_count), source_event_tip_sha256,
            created_by, reason, created_at,
        )
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                dup = conn.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE mission_id=? AND idempotency_key=?", (mission_id, idempotency_key)).fetchone()
                if dup is None:
                    existing = conn.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE mission_id=? AND declaration_id=?", (mission_id, declaration_id)).fetchone()
                    if existing is not None:
                        raise MissionOutcomeRecoveryConflict("Stage-3.6.8 verified completion declaration already has an immutable Stage-3.6.9 outcome recovery checkpoint")
                    conn.execute("""INSERT INTO mission_outcome_recovery_checkpoints
                        (checkpoint_id,mission_id,checkpoint_version,declaration_id,plan_version_record_id,plan_version,schema_version,request_sha256,idempotency_key,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,source_event_count,source_event_tip_sha256,created_by,reason,created_at)
                        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", values)
                    conn.commit()
                    row = conn.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE checkpoint_id=?", (checkpoint_id,)).fetchone()
                else:
                    row = dup
            else:
                mysql_values = list(values); mysql_values[-1] = self._mysql_dt(created_at)
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup = cur.fetchone()
                    if dup is None:
                        cur.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE mission_id=%s AND declaration_id=%s FOR UPDATE", (mission_id, declaration_id)); existing = cur.fetchone()
                        if existing is not None:
                            raise MissionOutcomeRecoveryConflict("Stage-3.6.8 verified completion declaration already has an immutable Stage-3.6.9 outcome recovery checkpoint")
                        cur.execute("""INSERT INTO mission_outcome_recovery_checkpoints
                            (checkpoint_id,mission_id,checkpoint_version,declaration_id,plan_version_record_id,plan_version,schema_version,request_sha256,idempotency_key,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,source_event_count,source_event_tip_sha256,created_by,reason,created_at)
                            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""", tuple(mysql_values))
                        conn.commit(); cur.execute("SELECT * FROM mission_outcome_recovery_checkpoints WHERE checkpoint_id=%s", (checkpoint_id,)); row = cur.fetchone()
                    else:
                        row = dup
            parsed = self._outcome_recovery_checkpoint_row(dict(row))
            if parsed["request_sha256"] != request_sha256:
                raise MissionOutcomeRecoveryConflict("outcome recovery idempotency_key was already used with a different canonical request")
            return parsed
        except Exception:
            conn.rollback(); raise
        finally:
            conn.close()

    def get_repository_metadata(self) -> Dict[str, Any]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                row = conn.execute(
                    "SELECT * FROM mission_repository_metadata WHERE repository_id='canonical-mission-repository'"
                ).fetchone()
            else:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_repository_metadata WHERE repository_id='canonical-mission-repository'"
                    )
                    row = cur.fetchone()
            if row is None:
                raise RuntimeError("mission repository metadata row is missing")
            out = dict(row)
            out["migration_level"] = int(out["migration_level"])
            out["created_at"] = self._iso_from_db(out["created_at"])
            out["updated_at"] = self._iso_from_db(out["updated_at"])
            return out
        finally:
            conn.close()

