    def store_adaptation_replan(
        self,
        *,
        mission_id: str,
        adaptation_episode_id: str,
        replan_trigger_id: str,
        source_plan_version_record_id: str,
        source_plan_version: int,
        source_plan_generation: int,
        target_plan_generation: int,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        source_state: str,
        source_state_version: int,
        source_version_sha256: str,
        trigger_source: str,
        trigger_code: str,
        source_event_id: Optional[str],
        source_event_sha256: Optional[str],
        evidence_refs: list[str],
        detected_by: str,
        reason: Optional[str],
        detected_at: str,
    ) -> Dict[str, Any]:
        text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        evidence_text = json.dumps(list(evidence_refs), ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        values = (
            adaptation_episode_id, replan_trigger_id, mission_id, source_plan_version_record_id,
            int(source_plan_version), int(source_plan_generation), int(target_plan_generation),
            ADAPTATION_REPLAN_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key,
            contract["adaptation_episode"]["episode_state"], trigger_source, trigger_code,
            source_event_id, source_event_sha256, len(evidence_refs), evidence_text,
            contract["canonical_sha256"], text, source_state, int(source_state_version),
            source_version_sha256, detected_by, reason, detected_at,
        )
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                conn.execute("BEGIN IMMEDIATE")
                dup = conn.execute(
                    "SELECT * FROM mission_adaptation_replan_contracts WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionAdaptationReplanConflict("adaptation/replan idempotency key already exists with different request material")
                    conn.commit()
                    return self._adaptation_replan_row(dict(dup))
                state_row = conn.execute("SELECT state,state_version FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                    raise MissionAdaptationReplanConflict("Mission state changed before adaptation/replan detection commit")
                head = conn.execute(
                    """SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                         FROM mission_plan_version_heads h
                         JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                        WHERE h.mission_id=?""",
                    (mission_id,),
                ).fetchone()
                if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != contract["source_bindings"]["source_plan_sha256"]:
                    raise MissionAdaptationReplanConflict("active Plan head changed before adaptation/replan detection commit")
                if source_event_id is not None:
                    event = conn.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=? AND event_id=?", (mission_id, source_event_id)).fetchone()
                    if event is None or event["canonical_sha256"] != source_event_sha256:
                        raise MissionAdaptationReplanConflict("source Mission event binding changed before adaptation/replan detection commit")
                conn.execute(
                    """INSERT INTO mission_adaptation_replan_contracts
                    (adaptation_episode_id,replan_trigger_id,mission_id,source_plan_version_record_id,source_plan_version,source_plan_generation,target_plan_generation,schema_version,request_sha256,idempotency_key,episode_state,trigger_source,trigger_code,source_event_id,source_event_sha256,evidence_ref_count,evidence_refs_json,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,detected_by,reason,detected_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    values,
                )
                conn.commit()
                row = conn.execute("SELECT * FROM mission_adaptation_replan_contracts WHERE adaptation_episode_id=?", (adaptation_episode_id,)).fetchone()
            else:
                conn.begin()
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_adaptation_replan_contracts WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionAdaptationReplanConflict("adaptation/replan idempotency key already exists with different request material")
                        conn.commit()
                        return self._adaptation_replan_row(dict(dup))
                    cur.execute("SELECT state,state_version FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state_row = cur.fetchone()
                    if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                        raise MissionAdaptationReplanConflict("Mission state changed before adaptation/replan detection commit")
                    cur.execute(
                        """SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                             FROM mission_plan_version_heads h
                             JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                            WHERE h.mission_id=%s FOR UPDATE""",
                        (mission_id,),
                    )
                    head = cur.fetchone()
                    if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != contract["source_bindings"]["source_plan_sha256"]:
                        raise MissionAdaptationReplanConflict("active Plan head changed before adaptation/replan detection commit")
                    if source_event_id is not None:
                        cur.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=%s AND event_id=%s", (mission_id, source_event_id))
                        event = cur.fetchone()
                        if event is None or event["canonical_sha256"] != source_event_sha256:
                            raise MissionAdaptationReplanConflict("source Mission event binding changed before adaptation/replan detection commit")
                    cur.execute(
                        """INSERT INTO mission_adaptation_replan_contracts
                        (adaptation_episode_id,replan_trigger_id,mission_id,source_plan_version_record_id,source_plan_version,source_plan_generation,target_plan_generation,schema_version,request_sha256,idempotency_key,episode_state,trigger_source,trigger_code,source_event_id,source_event_sha256,evidence_ref_count,evidence_refs_json,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,detected_by,reason,detected_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        values,
                    )
                conn.commit()
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_adaptation_replan_contracts WHERE adaptation_episode_id=%s", (adaptation_episode_id,))
                    row = cur.fetchone()
            return self._adaptation_replan_row(dict(row))
        except MissionAdaptationReplanConflict:
            conn.rollback()
            raise
        except Exception as exc:
            conn.rollback()
            # Normalize uniqueness races without exposing backend-specific errors.
            if isinstance(exc, sqlite3.IntegrityError):
                raise MissionAdaptationReplanConflict("adaptation/replan immutable identity conflict") from exc
            raise
        finally:
            conn.close()

    @classmethod
    def _adaptation_trigger_classification_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        contract = row.get("canonical_json")
