    def store_adaptation_trigger_classification(
        self,
        *,
        mission_id: str,
        classification_id: str,
        adaptation_episode_id: str,
        replan_trigger_id: str,
        source_plan_version_record_id: str,
        source_plan_version: int,
        source_plan_generation: int,
        canonical_plan_id: str,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        source_state: str,
        source_state_version: int,
        source_version_sha256: str,
        reason_code: str,
        severity: str,
        replan_scope_level: str,
        source_stage: str,
        source_event_id: Optional[str],
        source_event_sha256: Optional[str],
        evidence_refs: list[str],
        detection_event_id: str,
        detection_event_sha256: str,
        source_adaptation_replan_sha256: str,
        classified_by: str,
        reason: Optional[str],
        classified_at: str,
    ) -> Dict[str, Any]:
        text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        evidence_text = json.dumps(list(evidence_refs), ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        values = (
            classification_id, adaptation_episode_id, replan_trigger_id, mission_id,
            source_plan_version_record_id, int(source_plan_version), int(source_plan_generation), canonical_plan_id,
            ADAPTATION_TRIGGER_CLASSIFICATION_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key,
            contract["trigger_classification"]["classification_status"], reason_code, severity, replan_scope_level,
            source_stage, source_event_id, source_event_sha256, len(evidence_refs), evidence_text,
            detection_event_id, detection_event_sha256, source_adaptation_replan_sha256,
            contract["canonical_sha256"], text, source_state, int(source_state_version), source_version_sha256,
            classified_by, reason, classified_at,
        )
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                conn.execute("BEGIN IMMEDIATE")
                dup = conn.execute(
                    "SELECT * FROM mission_adaptation_trigger_classifications WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionAdaptationTriggerClassificationConflict(
                            "adaptation trigger classification idempotency key already exists with different request material"
                        )
                    conn.commit()
                    return self._adaptation_trigger_classification_row(dict(dup))
                source = conn.execute(
                    "SELECT canonical_sha256,replan_trigger_id,source_plan_version_record_id,source_plan_version,source_plan_generation FROM mission_adaptation_replan_contracts WHERE mission_id=? AND adaptation_episode_id=?",
                    (mission_id, adaptation_episode_id),
                ).fetchone()
                if source is None or source["canonical_sha256"] != source_adaptation_replan_sha256 or source["replan_trigger_id"] != replan_trigger_id:
                    raise MissionAdaptationTriggerClassificationConflict("Stage-3.7.1 adaptation/replan source changed before classification commit")
                existing_episode = conn.execute(
                    "SELECT classification_id FROM mission_adaptation_trigger_classifications WHERE adaptation_episode_id=?",
                    (adaptation_episode_id,),
                ).fetchone()
                if existing_episode is not None:
                    raise MissionAdaptationTriggerClassificationConflict("adaptation episode is already classified")
                detection = conn.execute(
                    "SELECT canonical_sha256 FROM mission_events WHERE mission_id=? AND event_id=? AND event_type='MISSION_ADAPTATION_REPLAN_DETECTED' AND causation_id=?",
                    (mission_id, detection_event_id, adaptation_episode_id),
                ).fetchone()
                if detection is None or detection["canonical_sha256"] != detection_event_sha256:
                    raise MissionAdaptationTriggerClassificationConflict("adaptation detection event changed before classification commit")
                state_row = conn.execute("SELECT state,state_version FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                    raise MissionAdaptationTriggerClassificationConflict("Mission state changed before adaptation trigger classification commit")
                head = conn.execute(
                    """SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                         FROM mission_plan_version_heads h
                         JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                        WHERE h.mission_id=?""",
                    (mission_id,),
                ).fetchone()
                if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != contract["source_bindings"]["source_plan_sha256"]:
                    raise MissionAdaptationTriggerClassificationConflict("active Plan head changed before adaptation trigger classification commit")
                conn.execute(
                    """INSERT INTO mission_adaptation_trigger_classifications
                    (classification_id,adaptation_episode_id,replan_trigger_id,mission_id,source_plan_version_record_id,source_plan_version,source_plan_generation,canonical_plan_id,schema_version,request_sha256,idempotency_key,classification_status,reason_code,severity,replan_scope_level,source_stage,source_event_id,source_event_sha256,evidence_ref_count,evidence_refs_json,detection_event_id,detection_event_sha256,source_adaptation_replan_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,classified_by,reason,classified_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    values,
                )
                conn.commit()
                row = conn.execute("SELECT * FROM mission_adaptation_trigger_classifications WHERE classification_id=?", (classification_id,)).fetchone()
            else:
                conn.begin()
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_adaptation_trigger_classifications WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionAdaptationTriggerClassificationConflict(
                                "adaptation trigger classification idempotency key already exists with different request material"
                            )
                        conn.commit()
                        return self._adaptation_trigger_classification_row(dict(dup))
                    cur.execute(
                        "SELECT canonical_sha256,replan_trigger_id,source_plan_version_record_id,source_plan_version,source_plan_generation FROM mission_adaptation_replan_contracts WHERE mission_id=%s AND adaptation_episode_id=%s FOR UPDATE",
                        (mission_id, adaptation_episode_id),
                    )
                    source = cur.fetchone()
                    if source is None or source["canonical_sha256"] != source_adaptation_replan_sha256 or source["replan_trigger_id"] != replan_trigger_id:
                        raise MissionAdaptationTriggerClassificationConflict("Stage-3.7.1 adaptation/replan source changed before classification commit")
                    cur.execute(
                        "SELECT classification_id FROM mission_adaptation_trigger_classifications WHERE adaptation_episode_id=%s FOR UPDATE",
                        (adaptation_episode_id,),
                    )
                    existing_episode = cur.fetchone()
                    if existing_episode is not None:
                        raise MissionAdaptationTriggerClassificationConflict("adaptation episode is already classified")
                    cur.execute(
                        "SELECT canonical_sha256 FROM mission_events WHERE mission_id=%s AND event_id=%s AND event_type='MISSION_ADAPTATION_REPLAN_DETECTED' AND causation_id=%s FOR UPDATE",
                        (mission_id, detection_event_id, adaptation_episode_id),
                    )
                    detection = cur.fetchone()
                    if detection is None or detection["canonical_sha256"] != detection_event_sha256:
                        raise MissionAdaptationTriggerClassificationConflict("adaptation detection event changed before classification commit")
                    cur.execute("SELECT state,state_version FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state_row = cur.fetchone()
                    if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                        raise MissionAdaptationTriggerClassificationConflict("Mission state changed before adaptation trigger classification commit")
                    cur.execute(
                        """SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                             FROM mission_plan_version_heads h
                             JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                            WHERE h.mission_id=%s FOR UPDATE""",
                        (mission_id,),
                    )
                    head = cur.fetchone()
                    if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != contract["source_bindings"]["source_plan_sha256"]:
                        raise MissionAdaptationTriggerClassificationConflict("active Plan head changed before adaptation trigger classification commit")
                    cur.execute(
                        """INSERT INTO mission_adaptation_trigger_classifications
                        (classification_id,adaptation_episode_id,replan_trigger_id,mission_id,source_plan_version_record_id,source_plan_version,source_plan_generation,canonical_plan_id,schema_version,request_sha256,idempotency_key,classification_status,reason_code,severity,replan_scope_level,source_stage,source_event_id,source_event_sha256,evidence_ref_count,evidence_refs_json,detection_event_id,detection_event_sha256,source_adaptation_replan_sha256,canonical_sha256,canonical_json,source_state,source_state_version,source_version_sha256,classified_by,reason,classified_at)
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)""",
                        values,
                    )
                conn.commit()
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_adaptation_trigger_classifications WHERE classification_id=%s", (classification_id,))
                    row = cur.fetchone()
            return self._adaptation_trigger_classification_row(dict(row))
        except MissionAdaptationTriggerClassificationConflict:
            conn.rollback()
            raise
        except Exception as exc:
            conn.rollback()
            if isinstance(exc, sqlite3.IntegrityError):
                raise MissionAdaptationTriggerClassificationConflict("adaptation trigger classification immutable identity conflict") from exc
            raise
        finally:
            conn.close()

    @classmethod
    def _replan_eligibility_governance_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        contract = row.get("canonical_json")
        if isinstance(contract, str):
            contract = json.loads(contract)
        return {
            "eligibility_gate_id": row["eligibility_gate_id"],
            "classification_id": row["classification_id"],
            "adaptation_episode_id": row["adaptation_episode_id"],
            "replan_trigger_id": row["replan_trigger_id"],
            "mission_id": row["mission_id"],
            "source_plan_version_record_id": row["source_plan_version_record_id"],
            "source_plan_version": int(row["source_plan_version"]),
            "source_plan_generation": int(row["source_plan_generation"]),
            "canonical_plan_id": row["canonical_plan_id"],
            "schema_version": row["schema_version"],
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "static_eligibility_status": row["static_eligibility_status"],
            "eligibility_status": row["eligibility_status"],
            "replan_eligible": bool(row["replan_eligible"]),
            "governance_decision": row["governance_decision"],
            "policy_decision_id": row["policy_decision_id"],
            "policy_request_id": row["policy_request_id"],
            "policy_decision_hash": row["policy_decision_hash"],
            "policy_version": int(row["policy_version"]),
            "governance_scope_contract_id": row["governance_scope_contract_id"],
            "governance_scope_version": int(row["governance_scope_version"]),
            "governance_scope_contract_hash": row["governance_scope_contract_hash"],
            "mission_scope_snapshot_id": row["mission_scope_snapshot_id"],
            "mission_scope_sha256": row["mission_scope_sha256"],
            "governance_binding_snapshot_id": row["governance_binding_snapshot_id"],
            "governance_binding_version": int(row["governance_binding_version"]),
            "governance_binding_sha256": row["governance_binding_sha256"],
            "source_classification_sha256": row["source_classification_sha256"],
            "source_adaptation_replan_sha256": row["source_adaptation_replan_sha256"],
            "classification_event_id": row["classification_event_id"],
            "classification_event_sha256": row["classification_event_sha256"],
            "canonical_sha256": row["canonical_sha256"],
            "replan_eligibility_governance_contract": contract,
            "source_state": row["source_state"],
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "requested_by": row["requested_by"],
            "reason": row.get("reason"),
            "evaluated_at": cls._iso_from_db(row["evaluated_at"]),
        }

