    def store_replan_eligibility_governance_gate(
        self,
        *,
        mission_id: str,
        eligibility_gate_id: str,
        classification_id: str,
        adaptation_episode_id: str,
        replan_trigger_id: str,
        source_plan_version_record_id: str,
        source_plan_version: int,
        source_plan_generation: int,
        canonical_plan_id: str,
        request_sha256: str,
        idempotency_key: str,
        contract: Dict[str, Any],
        source_state: str,
        source_state_version: int,
        source_version_sha256: str,
        source_classification_sha256: str,
        source_adaptation_replan_sha256: str,
        classification_event_id: str,
        classification_event_sha256: str,
        requested_by: str,
        reason: Optional[str],
        evaluated_at: str,
    ) -> Dict[str, Any]:
        text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        source = contract["source_bindings"]
        eligibility = contract["eligibility"]
        governance = contract["governance_decision"]
        governance_request = contract["governance_request"]
        binding_scope_hash = governance_request.get("scope_contract_hash")
        if not binding_scope_hash or binding_scope_hash != source.get("governance_scope_contract_hash"):
            raise MissionReplanEligibilityGovernanceConflict(
                "Stage-3.7.3 governance scope contract hash is missing or inconsistent"
            )
        if governance_request.get("scope_contract_id") != governance.get("scope_contract_id"):
            raise MissionReplanEligibilityGovernanceConflict(
                "Stage-3.7.3 Governance request/decision scope contract identity mismatch"
            )
        if int(governance_request.get("scope_version") or 0) != int(governance.get("scope_version") or 0):
            raise MissionReplanEligibilityGovernanceConflict(
                "Stage-3.7.3 Governance request/decision scope version mismatch"
            )
        values = (
            eligibility_gate_id, classification_id, adaptation_episode_id, replan_trigger_id, mission_id,
            source_plan_version_record_id, int(source_plan_version), int(source_plan_generation), canonical_plan_id,
            REPLAN_ELIGIBILITY_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key,
            contract["static_eligibility"]["status"], eligibility["eligibility_status"], int(bool(eligibility["replan_eligible"])),
            governance["decision"], governance["decision_id"], governance["request_id"], governance["decision_hash"],
            int(governance["policy_version"]), governance["scope_contract_id"], int(governance["scope_version"]),
            binding_scope_hash,
            source["mission_scope_snapshot_id"], source["mission_scope_sha256"],
            source["governance_binding_snapshot_id"], int(source["governance_binding_version"]), source["governance_binding_sha256"],
            source_classification_sha256, source_adaptation_replan_sha256,
            classification_event_id, classification_event_sha256,
            contract["canonical_sha256"], text, source_state, int(source_state_version), source_version_sha256,
            requested_by, reason, evaluated_at,
        )

        columns = (
            "eligibility_gate_id,classification_id,adaptation_episode_id,replan_trigger_id,mission_id,"
            "source_plan_version_record_id,source_plan_version,source_plan_generation,canonical_plan_id,schema_version,"
            "request_sha256,idempotency_key,static_eligibility_status,eligibility_status,replan_eligible,governance_decision,"
            "policy_decision_id,policy_request_id,policy_decision_hash,policy_version,governance_scope_contract_id,"
            "governance_scope_version,governance_scope_contract_hash,mission_scope_snapshot_id,mission_scope_sha256,"
            "governance_binding_snapshot_id,governance_binding_version,governance_binding_sha256,source_classification_sha256,"
            "source_adaptation_replan_sha256,classification_event_id,classification_event_sha256,canonical_sha256,canonical_json,"
            "source_state,source_state_version,source_version_sha256,requested_by,reason,evaluated_at"
        )
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                conn.execute("BEGIN IMMEDIATE")
                dup = conn.execute(
                    "SELECT * FROM mission_replan_eligibility_governance_gates WHERE mission_id=? AND idempotency_key=?",
                    (mission_id, idempotency_key),
                ).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionReplanEligibilityGovernanceConflict(
                            "replan eligibility/governance idempotency_key already exists with different request material"
                        )
                    conn.commit()
                    return self._replan_eligibility_governance_row(dict(dup))
                existing = conn.execute(
                    "SELECT eligibility_gate_id FROM mission_replan_eligibility_governance_gates WHERE adaptation_episode_id=?",
                    (adaptation_episode_id,),
                ).fetchone()
                if existing is not None:
                    raise MissionReplanEligibilityGovernanceConflict("adaptation episode already has a replan eligibility/governance gate")
                repl = conn.execute(
                    "SELECT canonical_sha256,replan_trigger_id FROM mission_adaptation_replan_contracts WHERE mission_id=? AND adaptation_episode_id=?",
                    (mission_id, adaptation_episode_id),
                ).fetchone()
                if repl is None or repl["canonical_sha256"] != source_adaptation_replan_sha256 or repl["replan_trigger_id"] != replan_trigger_id:
                    raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.1 adaptation/replan source changed before eligibility commit")
                clsrow = conn.execute(
                    "SELECT canonical_sha256,adaptation_episode_id,replan_trigger_id FROM mission_adaptation_trigger_classifications WHERE mission_id=? AND classification_id=?",
                    (mission_id, classification_id),
                ).fetchone()
                if clsrow is None or clsrow["canonical_sha256"] != source_classification_sha256 or clsrow["adaptation_episode_id"] != adaptation_episode_id or clsrow["replan_trigger_id"] != replan_trigger_id:
                    raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.2 classification changed before eligibility commit")
                ev = conn.execute(
                    "SELECT canonical_sha256 FROM mission_events WHERE mission_id=? AND event_id=? AND event_type='MISSION_ADAPTATION_TRIGGER_CLASSIFIED' AND causation_id=?",
                    (mission_id, classification_event_id, classification_id),
                ).fetchone()
                if ev is None or ev["canonical_sha256"] != classification_event_sha256:
                    raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.2 classification event changed before eligibility commit")
                state_row = conn.execute("SELECT state,state_version FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                    raise MissionReplanEligibilityGovernanceConflict("Mission state changed before replan eligibility commit")
                head = conn.execute(
                    """SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                         FROM mission_plan_version_heads h
                         JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                        WHERE h.mission_id=?""", (mission_id,),
                ).fetchone()
                if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != source["source_plan_sha256"]:
                    raise MissionReplanEligibilityGovernanceConflict("active Plan head changed before replan eligibility commit")
                scope = conn.execute(
                    """SELECT v.snapshot_id,v.canonical_sha256 FROM mission_scope_contract_versions v
                         JOIN mission_scope_contract_heads h ON h.mission_id=v.mission_id AND h.current_version=v.contract_version
                        WHERE v.mission_id=?""", (mission_id,),
                ).fetchone()
                if scope is None or scope["snapshot_id"] != source["mission_scope_snapshot_id"] or scope["canonical_sha256"] != source["mission_scope_sha256"]:
                    raise MissionReplanEligibilityGovernanceConflict("Mission scope changed before replan eligibility commit")
                binding = conn.execute(
                    """SELECT v.binding_snapshot_id,v.binding_version,v.canonical_sha256 FROM mission_governance_binding_versions v
                         JOIN mission_governance_binding_heads h ON h.mission_id=v.mission_id AND h.current_version=v.binding_version
                        WHERE v.mission_id=?""", (mission_id,),
                ).fetchone()
                if binding is None or binding["binding_snapshot_id"] != source["governance_binding_snapshot_id"] or int(binding["binding_version"]) != int(source["governance_binding_version"]) or binding["canonical_sha256"] != source["governance_binding_sha256"]:
                    raise MissionReplanEligibilityGovernanceConflict("Governance binding changed before replan eligibility commit")
                q = ",".join("?" for _ in values)
                conn.execute(f"INSERT INTO mission_replan_eligibility_governance_gates ({columns}) VALUES ({q})", values)
                conn.commit()
                row = conn.execute("SELECT * FROM mission_replan_eligibility_governance_gates WHERE eligibility_gate_id=?", (eligibility_gate_id,)).fetchone()
            else:
                conn.begin()
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM mission_replan_eligibility_governance_gates WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE",
                        (mission_id, idempotency_key),
                    )
                    dup = cur.fetchone()
                    if dup is not None:
                        if dup["request_sha256"] != request_sha256:
                            raise MissionReplanEligibilityGovernanceConflict(
                                "replan eligibility/governance idempotency_key already exists with different request material"
                            )
                        conn.commit()
                        return self._replan_eligibility_governance_row(dict(dup))
                    cur.execute("SELECT eligibility_gate_id FROM mission_replan_eligibility_governance_gates WHERE adaptation_episode_id=%s FOR UPDATE", (adaptation_episode_id,))
                    if cur.fetchone() is not None:
                        raise MissionReplanEligibilityGovernanceConflict("adaptation episode already has a replan eligibility/governance gate")
                    cur.execute("SELECT canonical_sha256,replan_trigger_id FROM mission_adaptation_replan_contracts WHERE mission_id=%s AND adaptation_episode_id=%s FOR UPDATE", (mission_id, adaptation_episode_id))
                    repl = cur.fetchone()
                    if repl is None or repl["canonical_sha256"] != source_adaptation_replan_sha256 or repl["replan_trigger_id"] != replan_trigger_id:
                        raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.1 adaptation/replan source changed before eligibility commit")
                    cur.execute("SELECT canonical_sha256,adaptation_episode_id,replan_trigger_id FROM mission_adaptation_trigger_classifications WHERE mission_id=%s AND classification_id=%s FOR UPDATE", (mission_id, classification_id))
                    clsrow = cur.fetchone()
                    if clsrow is None or clsrow["canonical_sha256"] != source_classification_sha256 or clsrow["adaptation_episode_id"] != adaptation_episode_id or clsrow["replan_trigger_id"] != replan_trigger_id:
                        raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.2 classification changed before eligibility commit")
                    cur.execute("SELECT canonical_sha256 FROM mission_events WHERE mission_id=%s AND event_id=%s AND event_type='MISSION_ADAPTATION_TRIGGER_CLASSIFIED' AND causation_id=%s FOR UPDATE", (mission_id, classification_event_id, classification_id))
                    ev = cur.fetchone()
                    if ev is None or ev["canonical_sha256"] != classification_event_sha256:
                        raise MissionReplanEligibilityGovernanceConflict("Stage-3.7.2 classification event changed before eligibility commit")
                    cur.execute("SELECT state,state_version FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,))
                    state_row = cur.fetchone()
                    if state_row is None or state_row["state"] != source_state or int(state_row["state_version"]) != int(source_state_version):
                        raise MissionReplanEligibilityGovernanceConflict("Mission state changed before replan eligibility commit")
                    cur.execute("""SELECT h.active_plan_version_record_id,h.active_plan_version,v.canonical_sha256
                                     FROM mission_plan_version_heads h JOIN mission_plan_versions v ON v.plan_version_record_id=h.active_plan_version_record_id
                                    WHERE h.mission_id=%s FOR UPDATE""", (mission_id,))
                    head = cur.fetchone()
                    if head is None or head["active_plan_version_record_id"] != source_plan_version_record_id or int(head["active_plan_version"]) != int(source_plan_version) or head["canonical_sha256"] != source["source_plan_sha256"]:
                        raise MissionReplanEligibilityGovernanceConflict("active Plan head changed before replan eligibility commit")
                    cur.execute("""SELECT v.snapshot_id,v.canonical_sha256 FROM mission_scope_contract_versions v
                                     JOIN mission_scope_contract_heads h ON h.mission_id=v.mission_id AND h.current_version=v.contract_version
                                    WHERE v.mission_id=%s FOR UPDATE""", (mission_id,))
                    scope = cur.fetchone()
                    if scope is None or scope["snapshot_id"] != source["mission_scope_snapshot_id"] or scope["canonical_sha256"] != source["mission_scope_sha256"]:
                        raise MissionReplanEligibilityGovernanceConflict("Mission scope changed before replan eligibility commit")
                    cur.execute("""SELECT v.binding_snapshot_id,v.binding_version,v.canonical_sha256 FROM mission_governance_binding_versions v
                                     JOIN mission_governance_binding_heads h ON h.mission_id=v.mission_id AND h.current_version=v.binding_version
                                    WHERE v.mission_id=%s FOR UPDATE""", (mission_id,))
                    binding = cur.fetchone()
                    if binding is None or binding["binding_snapshot_id"] != source["governance_binding_snapshot_id"] or int(binding["binding_version"]) != int(source["governance_binding_version"]) or binding["canonical_sha256"] != source["governance_binding_sha256"]:
                        raise MissionReplanEligibilityGovernanceConflict("Governance binding changed before replan eligibility commit")
                    q = ",".join("%s" for _ in values)
                    cur.execute(f"INSERT INTO mission_replan_eligibility_governance_gates ({columns}) VALUES ({q})", values)
                conn.commit()
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_replan_eligibility_governance_gates WHERE eligibility_gate_id=%s", (eligibility_gate_id,))
                    row = cur.fetchone()
            return self._replan_eligibility_governance_row(dict(row))
        except MissionReplanEligibilityGovernanceConflict:
            conn.rollback()
            raise
        except Exception as exc:
            conn.rollback()
            if isinstance(exc, sqlite3.IntegrityError):
                raise MissionReplanEligibilityGovernanceConflict("replan eligibility/governance immutable identity conflict") from exc
            raise
        finally:
            conn.close()

    @classmethod
    def _replan_snapshot_row(cls, row: Dict[str, Any]) -> Dict[str, Any]:
        contract = row.get("canonical_json")
        if isinstance(contract, str):
            contract = json.loads(contract)
        return {
            "replan_snapshot_id": row["replan_snapshot_id"],
            "adaptation_episode_id": row["adaptation_episode_id"],
            "replan_trigger_id": row["replan_trigger_id"],
            "classification_id": row["classification_id"],
            "eligibility_gate_id": row["eligibility_gate_id"],
            "mission_id": row["mission_id"],
            "source_plan_version_record_id": row["source_plan_version_record_id"],
            "source_plan_version": int(row["source_plan_version"]),
            "source_plan_generation": int(row["source_plan_generation"]),
            "target_plan_generation": int(row["target_plan_generation"]),
            "canonical_plan_id": row["canonical_plan_id"],
            "schema_version": row["schema_version"],
            "request_sha256": row["request_sha256"],
            "idempotency_key": row["idempotency_key"],
            "snapshot_status": row["snapshot_status"],
            "source_adaptation_replan_sha256": row["source_adaptation_replan_sha256"],
            "source_classification_sha256": row["source_classification_sha256"],
            "source_eligibility_sha256": row["source_eligibility_sha256"],
            "policy_decision_hash": row["policy_decision_hash"],
            "mission_scope_snapshot_id": row["mission_scope_snapshot_id"],
            "mission_scope_sha256": row["mission_scope_sha256"],
            "governance_binding_snapshot_id": row["governance_binding_snapshot_id"],
            "governance_binding_version": int(row["governance_binding_version"]),
            "governance_binding_sha256": row["governance_binding_sha256"],
            "task_context_sha256": row["task_context_sha256"],
            "canonical_sha256": row["canonical_sha256"],
            "replan_snapshot_contract": contract,
            "source_state": row["source_state"],
            "source_state_version": int(row["source_state_version"]),
            "source_version_sha256": row["source_version_sha256"],
            "bound_by": row["bound_by"],
            "reason": row.get("reason"),
            "bound_at": cls._iso_from_db(row["bound_at"]),
        }

