    def list_replan_handoffs(self, mission_id: str) -> list[Dict[str, Any]]:
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                rows = conn.execute("SELECT * FROM mission_replan_handoffs WHERE mission_id=? ORDER BY id ASC", (mission_id,)).fetchall()
            else:
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM mission_replan_handoffs WHERE mission_id=%s ORDER BY id ASC", (mission_id,)); rows = cur.fetchall()
            return [self._replan_handoff_row(dict(row)) for row in rows]
        finally:
            conn.close()

    def store_replan_handoff(
        self, *, contract: Dict[str, Any], request_sha256: str, idempotency_key: str,
        handed_off_by: str, reason: Optional[str], handed_off_at: str,
        expected_active_head_id: str, expected_active_head_version: int, expected_active_head_sha256: str,
        expected_state: str, expected_state_version: int,
    ) -> Dict[str, Any]:
        ident = contract["identity"]; bind = contract["atomic_commit_binding"]; hand = contract["task_handoff"]
        text = json.dumps(contract, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False)
        values = (
            ident["replan_handoff_id"], ident["mission_id"], ident["adaptation_episode_id"], ident["replan_trigger_id"],
            ident["replan_commit_id"], ident["replan_validation_id"], bind["predecessor_plan_version_record_id"],
            int(bind["predecessor_plan_version"]), bind["successor_plan_version_record_id"], int(bind["successor_plan_version"]),
            REPLAN_HANDOFF_CONTRACT_SCHEMA_VERSION, request_sha256, idempotency_key, contract["successor_handoff"]["handoff_status"],
            bind["replan_commit_sha256"], bind["predecessor_plan_sha256"], bind["successor_plan_sha256"],
            int(hand["task_disposition_count"]), int(hand["keep_count"]), int(hand["drain_count"]), int(hand["cancel_count"]),
            int(hand["supersede_count"]), int(hand["replace_count"]), contract["canonical_sha256"], text,
            contract["provenance"]["source_state"], int(contract["provenance"]["source_state_version"]), handed_off_by, reason, handed_off_at,
        )
        columns = (
            "replan_handoff_id,mission_id,adaptation_episode_id,replan_trigger_id,replan_commit_id,replan_validation_id,"
            "predecessor_plan_version_record_id,predecessor_plan_version,successor_plan_version_record_id,successor_plan_version,"
            "schema_version,request_sha256,idempotency_key,handoff_status,source_replan_commit_sha256,predecessor_plan_sha256,"
            "successor_plan_sha256,task_disposition_count,keep_count,drain_count,cancel_count,supersede_count,replace_count,"
            "canonical_sha256,canonical_json,source_state,source_state_version,handed_off_by,reason,handed_off_at"
        )
        mission_id = ident["mission_id"]
        conn = self._connect()
        try:
            if self.driver == "sqlite":
                conn.execute("BEGIN IMMEDIATE")
                dup = conn.execute("SELECT * FROM mission_replan_handoffs WHERE mission_id=? AND idempotency_key=?", (mission_id, idempotency_key)).fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionReplanHandoffConflict("replan handoff idempotency_key already exists with different request material")
                    conn.commit(); return self._replan_handoff_row(dict(dup))
                if conn.execute("SELECT 1 FROM mission_replan_handoffs WHERE replan_commit_id=?", (ident["replan_commit_id"],)).fetchone():
                    raise MissionReplanHandoffConflict("ReplanCommit already has a handoff declaration")
                commit = conn.execute("SELECT canonical_sha256,source_state,source_state_version,successor_plan_version_record_id,successor_plan_version,successor_plan_sha256 FROM mission_replan_commits WHERE mission_id=? AND replan_commit_id=?", (mission_id, ident["replan_commit_id"])).fetchone()
                state = conn.execute("SELECT state,state_version FROM mission_states WHERE mission_id=?", (mission_id,)).fetchone()
                head = conn.execute("SELECT active_plan_version_record_id,active_plan_version,active_plan_sha256 FROM mission_plan_version_heads WHERE mission_id=?", (mission_id,)).fetchone()
                if commit is None or commit["canonical_sha256"] != bind["replan_commit_sha256"]:
                    raise MissionReplanHandoffConflict("Stage-3.7.7 ReplanCommit changed before handoff")
                if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                    raise MissionReplanHandoffConflict("Mission state changed before atomic replan handoff")
                if head is None or head["active_plan_version_record_id"] != expected_active_head_id or int(head["active_plan_version"]) != int(expected_active_head_version) or head["active_plan_sha256"] != expected_active_head_sha256:
                    raise MissionReplanHandoffConflict("active Plan head changed before atomic replan handoff")
                q = ",".join("?" for _ in values)
                conn.execute(f"INSERT INTO mission_replan_handoffs ({columns}) VALUES ({q})", values)
                row = conn.execute("SELECT * FROM mission_replan_handoffs WHERE replan_handoff_id=?", (ident["replan_handoff_id"],)).fetchone()
                conn.commit(); return self._replan_handoff_row(dict(row))
            conn.begin()
            with conn.cursor() as cur:
                cur.execute("SELECT * FROM mission_replan_handoffs WHERE mission_id=%s AND idempotency_key=%s FOR UPDATE", (mission_id, idempotency_key)); dup = cur.fetchone()
                if dup is not None:
                    if dup["request_sha256"] != request_sha256:
                        raise MissionReplanHandoffConflict("replan handoff idempotency_key already exists with different request material")
                    conn.commit(); return self._replan_handoff_row(dict(dup))
                cur.execute("SELECT 1 FROM mission_replan_handoffs WHERE replan_commit_id=%s FOR UPDATE", (ident["replan_commit_id"],))
                if cur.fetchone() is not None:
                    raise MissionReplanHandoffConflict("ReplanCommit already has a handoff declaration")
                cur.execute("SELECT canonical_sha256 FROM mission_replan_commits WHERE mission_id=%s AND replan_commit_id=%s FOR UPDATE", (mission_id, ident["replan_commit_id"])); commit = cur.fetchone()
                cur.execute("SELECT state,state_version FROM mission_states WHERE mission_id=%s FOR UPDATE", (mission_id,)); state = cur.fetchone()
                cur.execute("SELECT active_plan_version_record_id,active_plan_version,active_plan_sha256 FROM mission_plan_version_heads WHERE mission_id=%s FOR UPDATE", (mission_id,)); head = cur.fetchone()
                if commit is None or commit["canonical_sha256"] != bind["replan_commit_sha256"]:
                    raise MissionReplanHandoffConflict("Stage-3.7.7 ReplanCommit changed before handoff")
                if state is None or state["state"] != expected_state or int(state["state_version"]) != int(expected_state_version):
                    raise MissionReplanHandoffConflict("Mission state changed before atomic replan handoff")
                if head is None or head["active_plan_version_record_id"] != expected_active_head_id or int(head["active_plan_version"]) != int(expected_active_head_version) or head["active_plan_sha256"] != expected_active_head_sha256:
                    raise MissionReplanHandoffConflict("active Plan head changed before atomic replan handoff")
                q = ",".join("%s" for _ in values); mysql_values=list(values); mysql_values[-1]=self._mysql_dt(handed_off_at)
                cur.execute(f"INSERT INTO mission_replan_handoffs ({columns}) VALUES ({q})", tuple(mysql_values))
                cur.execute("SELECT * FROM mission_replan_handoffs WHERE replan_handoff_id=%s", (ident["replan_handoff_id"],)); row = cur.fetchone()
            conn.commit(); return self._replan_handoff_row(dict(row))
        except MissionReplanHandoffConflict:
            conn.rollback(); raise
        except Exception as exc:
            conn.rollback()
            if isinstance(exc, sqlite3.IntegrityError):
                raise MissionReplanHandoffConflict("atomic replan handoff immutable identity conflict") from exc
            raise
        finally:
            conn.close()

